def visitkorea_festival_id(url: str) -> str:
    """Return the stable VisitKorea festival content id from a detail URL."""
    try:
        return str(parse_qs(urlparse(str(url or "")).query).get("fstvlCntntsId", [""])[0]).strip()
    except (AttributeError, TypeError, ValueError):
        return ""


def build_festival_official_link(event: dict, position: str = "본문중간") -> dict | None:
    """Build the temporary writing-page link for a festival homepage."""
    title = re.sub(r"\s+", " ", str(event.get("title") or "")).strip()
    official_url = normalize_external_url(str(event.get("official_url") or ""))
    if not title or not official_url:
        return None
    if position not in LINK_POSITION_OPTIONS:
        position = "본문중간"
    return {
        "button_text": f"{title}홈페이지 바로가기👆🏻",
        "url": official_url,
        "width": "",
        "full_width": True,
        "position": position,
        "transient": True,
        "source": "festival",
    }


def build_welfare_official_link(event: dict, position: str = "본문하단") -> dict | None:
    """Build a temporary full-width link to the welfare application/detail page."""
    title = re.sub(r"\s+", " ", str(event.get("title") or "")).strip()
    target_url = normalize_external_url(
        str(event.get("application_url") or event.get("detail_url") or "")
    )
    if not title or not target_url:
        return None
    if position not in LINK_POSITION_OPTIONS:
        position = "본문하단"
    return {
        "button_text": f"{title} 복지로에서 자세히 보기👆🏻",
        "url": target_url,
        "width": "",
        "full_width": True,
        "position": position,
        "transient": True,
        "source": "welfare",
    }


def build_public_data_automation_payload(
    event: dict,
    source: str,
    link_positions: Iterable[str],
    rank: int = 1,
) -> dict:
    """Convert one detailed festival/welfare record into an automation payload."""
    event = dict(event or {})
    title = re.sub(r"\s+", " ", str(event.get("title") or "")).strip()
    if not title:
        raise ValueError("대기열에 넣을 공공정보 제목이 없습니다.")
    positions = [position for position in link_positions if position in LINK_POSITION_OPTIONS]
    if source == "festival":
        detail_url = normalize_external_url(str(event.get("detail_url") or ""))
        official_url = normalize_external_url(str(event.get("official_url") or ""))
        source_urls = {"대한민국 구석구석": detail_url or VISITKOREA_FESTIVAL_LIST_URL}
        if official_url:
            source_urls["축제 공식 홈페이지"] = official_url
        links = [build_festival_official_link(event, position) for position in positions]
        return {
            "source_name": "구석구석 축제",
            "rank": rank,
            "keyword": title,
            "reference_text": str(event.get("reference_text") or "").strip(),
            "source_urls": source_urls,
            "score": 94,
            "categories": ["축제", str(event.get("area") or "전국")],
            "writing_links": [link for link in links if link],
            "festival": event,
        }
    if source == "welfare":
        detail_url = normalize_external_url(str(event.get("detail_url") or ""))
        application_url = normalize_external_url(str(event.get("application_url") or ""))
        source_urls = {"복지로 공식정보": detail_url or BOKJIRO_WELFARE_LIST_URL}
        if application_url:
            source_urls["온라인 신청/공식 홈페이지"] = application_url
        links = [build_welfare_official_link(event, position) for position in positions]
        return {
            "source_name": "공공 복지",
            "rank": rank,
            "keyword": title,
            "reference_text": str(event.get("reference_text") or "").strip(),
            "source_urls": source_urls,
            "score": 95,
            "categories": ["복지", str(event.get("interest") or event.get("lifecycle") or "정부지원")],
            "writing_links": [link for link in links if link],
            "welfare": event,
        }
    raise ValueError(f"지원하지 않는 공공정보 유형입니다: {source}")


class FestivalStateStore:
    """Persist VisitKorea filters, cached rows, and confirmed publish history."""

    def __init__(self, path: Path = FESTIVAL_STATE_FILE) -> None:
        self.path = Path(path)

    @staticmethod
    def empty_state() -> dict:
        return {
            "filters": {"period": "", "region": "", "category": ""},
            "filter_options": {"period": [], "region": [], "category": []},
            "link_positions": list(LINK_POSITION_OPTIONS),
            "events": [],
            "selected_id": "",
            "selected_ids": [],
            "published": {},
            "active": {},
        }

    def load(self) -> dict:
        state = self.empty_state()
        if not self.path.exists():
            return state
        try:
            payload = json.loads(self.path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError):
            return state
        if not isinstance(payload, dict):
            return state
        for key in state:
            if key in payload and isinstance(payload[key], type(state[key])):
                state[key] = payload[key]
        return state

    def _read_payload(self) -> dict:
        if not self.path.exists():
            return {}
        try:
            payload = json.loads(self.path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError):
            return {}
        return payload if isinstance(payload, dict) else {}

    def save(self, state: dict, preserve_published: bool = True) -> None:
        if preserve_published:
            disk_history = dict(self._read_payload().get("published") or {})
            disk_history.update(dict(state.get("published") or {}))
            state["published"] = disk_history
        self.path.parent.mkdir(parents=True, exist_ok=True)
        temporary_path = self.path.with_suffix(self.path.suffix + ".tmp")
        temporary_path.write_text(
            json.dumps(state, ensure_ascii=False, indent=2),
            encoding="utf-8",
        )
        temporary_path.replace(self.path)

    def clear_published(self, state: dict) -> None:
        state["published"] = {}
        state["active"] = {}
        for event in state.get("events") or []:
            if isinstance(event, dict):
                event["published"] = False
                event["published_at"] = ""
                event["published_urls"] = []
        self.save(state, preserve_published=False)

    def mark_published(
        self,
        state: dict,
        event: dict,
        published_urls: Iterable[str],
        published_at: str = "",
    ) -> dict:
        festival_id = str(event.get("festival_id") or visitkorea_festival_id(event.get("detail_url", ""))).strip()
        if not festival_id:
            raise ValueError("축제 고유 ID가 없어 등록 이력을 저장할 수 없습니다.")
        published = state.setdefault("published", {})
        active_festival_id = str((state.get("active") or {}).get("festival_id") or "").strip()
        if festival_id in published:
            if active_festival_id == festival_id:
                state["active"] = {}
            self.save(state)
            return dict(published[festival_id])
        urls = [
            str(url).strip()
            for url in published_urls
            if str(url).strip().startswith(("http://", "https://"))
        ]
        record = {
            "festival_id": festival_id,
            "title": str(event.get("title") or "").strip(),
            "detail_url": str(event.get("detail_url") or "").strip(),
            "published_at": published_at or time.strftime("%Y-%m-%d %H:%M:%S"),
            "published_urls": list(dict.fromkeys(urls)),
        }
        published[festival_id] = record
        if active_festival_id == festival_id:
            state["active"] = {}
        self.save(state)
        return record


