class ImagenTestWorker(threading.Thread):
    def __init__(self, api_key: str, model_name: str, result_queue: queue.Queue) -> None:
        super().__init__(daemon=True)
        self.api_key = api_key
        self.model_name = model_name
        self.result_queue = result_queue

    def run(self) -> None:
        try:
            output_path = DATA_DIR / "imagen-api-test.png"
            ImagenClient(self.api_key).generate_image(
                self.model_name,
                "Create a simple square blog card background image for an API connection test. Clean abstract shapes, soft blue gradient, checkmark icon only. Absolutely no text, no letters, no numbers, no typography, no labels.",
                output_path,
            )
            self.result_queue.put(
                (
                    "imagen_test_done",
                    {
                        "model_name": self.model_name,
                        "image_path": str(output_path),
                    },
                )
            )
        except Exception as exc:  # pragma: no cover - runtime handling
            self.result_queue.put(("imagen_error", str(exc)))


class CodexCLITestWorker(threading.Thread):
    def __init__(self, settings: WordPressSettings, result_queue: queue.Queue) -> None:
        super().__init__(daemon=True)
        self.settings = settings
        self.result_queue = result_queue

    def run(self) -> None:
        try:
            resolved_cli = resolve_codex_cli_path(self.settings.codex_cli_path)
            if not resolved_cli:
                raise RuntimeError("Codex CLI 실행 파일을 찾지 못했습니다. 자동 감지 또는 찾아보기로 경로를 지정해 주세요.")

            version_text, _parsed_version = codex_cli_version(resolved_cli)
            if not version_text:
                raise RuntimeError("Codex CLI 버전을 확인하지 못했습니다.")
            auth_result = subprocess.run(
                codex_cli_command(resolved_cli, "login", "status"),
                capture_output=True,
                text=True,
                check=False,
                timeout=10,
            )
            auth_text = (auth_result.stdout or auth_result.stderr or "").strip()
            execution = execute_codex_cli_text(
                self.settings,
                "Reply with exactly: BLOG_HELPER_CODEX_OK",
                timeout=max(20, min(int(self.settings.codex_cli_timeout or 120), 90)),
                temp_prefix="blog-helper-codex-test-",
            )
            if not execution.success:
                raise RuntimeError(f"Codex CLI 실행 실패: {execution.error[:700]}")

            self.result_queue.put(
                (
                    "codex_test_done",
                    {
                        "path": resolved_cli,
                        "version": version_text,
                        "output": execution.output[:120],
                        "auth": auth_text,
                        "model": execution.model or "CLI 기본 모델",
                        "fallback_used": execution.fallback_used,
                    },
                )
            )
        except Exception as exc:  # pragma: no cover - runtime handling
            self.result_queue.put(("codex_test_error", str(exc)))


def _naver_blog_work_directory(work_folder: str, topic: str) -> Path:
    root = Path(work_folder).expanduser() if str(work_folder or "").strip() else DATA_DIR / "Naver Blog Work"
    safe_topic = re.sub(r'[<>:"/\\|?*\x00-\x1f]', "", re.sub(r"\s+", "_", topic.strip())).strip(" ._")
    safe_topic = safe_topic[:70] or "naver-blog"
    work_dir = root / f"{time.strftime('%Y%m%d-%H%M%S')}-{safe_topic}"
    work_dir.mkdir(parents=True, exist_ok=True)
    return work_dir


def generate_naver_blog_article(
    settings: WordPressSettings,
    topic: str,
    reference_text: str,
    result_queue: queue.Queue,
    cancel_event: threading.Event | None = None,
) -> tuple[str, str, str, str]:
    _raise_if_naver_blog_cancelled(cancel_event)
    category = str(settings.naver_blog_topic_category or "선택안함").strip()
    title_template = render_prompt_template(
        settings.naver_blog_title_prompt or DEFAULT_NAVER_BLOG_TITLE_PROMPT,
        topic,
        topic,
        reference_text[:12000],
    )
    title_prompt = (
        "[프롬프트관리 > N블로그 > 제목 프롬프트]\n"
        f"{title_template}\n\n"
        "[이번 실행의 필수 조건]\n"
        f"- 글 주제: {topic}\n"
        f"- 카테고리: {category}\n"
        "- 검색된 최신 사실을 반영하되 확인되지 않은 내용은 만들지 않습니다.\n"
        "- 네이버 블로그 제목 한 줄만 반환합니다. 설명, 따옴표, 번호, 마크다운을 쓰지 않습니다.\n\n"
        f"[최신 참고내용]\n{reference_text[:12000]}"
    )
    result_queue.put(("naver_blog_progress", "선택한 N블로그 제목 프롬프트로 제목을 작성하는 중..."))
    raw_title, provider_name = generate_text_with_writing_model(settings, title_prompt)
    _raise_if_naver_blog_cancelled(cancel_event)
    title = clean_generated_title(raw_title, topic)

    article_template = render_prompt_template(
        settings.naver_blog_topic_prompt or DEFAULT_NAVER_BLOG_TOPIC_PROMPT,
        topic,
        topic,
        reference_text[:12000],
        title,
    )
    conversion_rules = str(settings.naver_blog_conversion_rules or DEFAULT_NAVER_BLOG_CONVERSION_RULES).strip()
    article_prompt = (
        "[프롬프트관리 > N블로그 > 본문글작성 프롬프트]\n"
        f"{article_template}\n\n"
        "[N블로그 글변환 규칙]\n"
        f"{conversion_rules}\n\n"
        "[이번 실행의 필수 조건]\n"
        f"- 제목: {title}\n"
        f"- 글 주제: {topic}\n"
        f"- 카테고리: {category}\n"
        "- 참고내용의 최신 사실을 중심으로 사람이 직접 작성한 듯 자연스럽고 읽기 쉽게 씁니다.\n"
        "- 출처 문장을 그대로 복사하지 말고 새로운 문장으로 재작성합니다.\n"
        "- 과장하거나 확인되지 않은 날짜, 수치, 인물 관계를 만들지 않습니다.\n"
        "- 한 문단은 2~4문장으로 짧게 쓰고 문단 사이에는 반드시 빈 줄을 한 줄 넣습니다.\n"
        "- 긴 문장을 한 덩어리로 붙이지 말고 소제목, 짧은 문단, 목록으로 나눠 모바일에서도 읽기 쉽게 작성합니다.\n"
        "- 소제목을 3~6개 만들고 각 소제목은 반드시 `## 소제목` 형식으로 한 줄에 단독 작성합니다.\n"
        "- 각 핵심 구간에서 중요한 문장 한 개는 반드시 `**중요 문장**` 형식으로 한 문단에 단독 작성합니다.\n"
        "- `##`와 `**` 표시는 네이버 에디터에서 각각 인용구와 굵은 글씨로 변환되므로 삭제하지 않습니다.\n"
        "- 제목은 반복하지 말고 본문 HTML만 반환합니다.\n\n"
        f"[최신 참고내용]\n{reference_text[:12000]}"
    )
    result_queue.put(("naver_blog_progress", "선택한 N블로그 본문 프롬프트로 글을 작성하는 중..."))
    raw_article, provider_name = generate_text_with_writing_model(settings, article_prompt)
    _raise_if_naver_blog_cancelled(cancel_event)
    article_html = normalize_generated_article_html(raw_article)
    body_text = normalize_naver_blog_paragraph_spacing(naver_blog_plain_text_from_html(article_html))
    if not body_text:
        raise RuntimeError("N블로그 본문 생성 결과가 비어 있습니다.")
    return title, article_html, body_text, provider_name


def collect_naver_blog_image_files(
    topic: str,
    title: str,
    count: int,
    work_dir: Path,
    result_queue: queue.Queue,
    cancel_event: threading.Event | None = None,
) -> list[str]:
    _raise_if_naver_blog_cancelled(cancel_event)
    target_count = max(1, min(int(count or 2), 10))
    collector = GoogleImageCollageCollector()
    query = f"{topic} {title} 관련 최신 사진"
    result_queue.put(("naver_blog_progress", f"'{topic}' 관련 이미지를 검색해 {target_count}개 저장하는 중..."))
    candidates = collector.collect_web(query, count=max(target_count * 4, 10))
    _raise_if_naver_blog_cancelled(cancel_event)
    if len(candidates) < target_count:
        try:
            candidates.extend(collector.collect_licensed(query, count=target_count * 3))
        except Exception:
            pass

    image_paths: list[str] = []
    seen: set[str] = set()
    for candidate in candidates:
        _raise_if_naver_blog_cancelled(cancel_event)
        fingerprint = str(candidate.get("image_url") or candidate.get("source_url") or candidate.get("data_url") or "")
        if not fingerprint or fingerprint in seen:
            continue
        seen.add(fingerprint)
        destination = work_dir / f"image_{len(image_paths) + 1}.png"
        data_url = str(candidate.get("data_url") or "")
        if _save_reference_image_with_pillow(data_url, destination) or capture_reference_image_region(
            data_url,
            destination,
        ):
            image_paths.append(str(destination))
        if len(image_paths) >= target_count:
            break
    if not image_paths:
        raise RuntimeError("주제와 관련된 첨부 이미지를 저장하지 못했습니다. 잠시 후 다시 시도해 주세요.")
    result_queue.put(("naver_blog_progress", f"관련 이미지 {len(image_paths)}개를 작업 폴더에 저장했습니다."))
    return image_paths


def merge_naver_blog_manual_image_paths(
    existing_paths: list[str] | tuple[str, ...] | None,
    added_paths: list[str] | tuple[str, ...] | None,
    max_count: int,
) -> list[str]:
    """Append unique manual images without exceeding the configured limit."""
    limit = max(1, min(int(max_count or 1), 10))
    merged: list[str] = []
    seen: set[str] = set()
    for raw_path in [*(existing_paths or []), *(added_paths or [])]:
        path = str(raw_path or "").strip()
        if not path:
            continue
        fingerprint = os.path.normcase(os.path.abspath(os.path.expanduser(path)))
        if fingerprint in seen:
            continue
        seen.add(fingerprint)
        merged.append(path)
    if len(merged) > limit:
        raise ValueError(
            f"수동 이미지는 설정의 첨부 이미지 수({limit}장)까지만 추가할 수 있습니다."
        )
    return merged


def prepare_naver_blog_manual_image_files(
    image_paths: list[str] | tuple[str, ...] | None,
    max_count: int,
    work_dir: Path,
    result_queue: queue.Queue,
    cancel_event: threading.Event | None = None,
) -> list[str]:
    """Validate and copy the user's selected images into this run's work folder."""
    _raise_if_naver_blog_cancelled(cancel_event)
    limit = max(1, min(int(max_count or 1), 10))
    sources: list[Path] = []
    seen: set[str] = set()
    for raw_path in image_paths or []:
        clean_path = str(raw_path or "").strip()
        if not clean_path:
            continue
        source = Path(clean_path).expanduser()
        fingerprint = str(source.resolve())
        if fingerprint in seen:
            continue
        seen.add(fingerprint)
        sources.append(source)
    if len(sources) > limit:
        raise RuntimeError(
            f"수동 이미지는 설정의 첨부 이미지 수({limit}장)까지만 선택할 수 있습니다."
        )

    work_dir.mkdir(parents=True, exist_ok=True)
    copied_paths: list[str] = []
    for index, source in enumerate(sources, start=1):
        _raise_if_naver_blog_cancelled(cancel_event)
        if not source.is_file():
            raise RuntimeError(f"선택한 이미지 파일을 찾을 수 없습니다: {source}")
        suffix = source.suffix.lower()
        if suffix not in NAVER_BLOG_MANUAL_IMAGE_SUFFIXES:
            raise RuntimeError(
                f"지원하지 않는 이미지 형식입니다: {source.name}\n"
                "PNG, JPG, JPEG, HEIC, GIF, WEBP, BMP 파일을 선택해 주세요."
            )
        destination = work_dir / f"manual_image_{index}{suffix}"
        shutil.copy2(source, destination)
        copied_paths.append(str(destination))

    result_queue.put(
        (
            "naver_blog_progress",
            f"수동으로 선택한 이미지 {len(copied_paths)}개를 글에 첨부할 준비를 마쳤습니다.",
        )
    )
    return copied_paths


def combine_naver_blog_reference_text(
    manual_reference: str,
    portal_reference: str,
    max_chars: int = 12000,
) -> str:
    """Combine optional user notes with portal facts while retaining both sources."""
    manual = str(manual_reference or "").strip()
    portal = str(portal_reference or "").strip()
    limit = max(1, int(max_chars or 12000))
    if not manual:
        return portal[:limit]

    manual_header = "[직접 입력한 참고내용]\n"
    if not portal:
        return f"{manual_header}{manual}"[:limit]

    portal_header = "\n\n[포털 자동수집 참고내용]\n"
    available = max(0, limit - len(manual_header) - len(portal_header))
    manual_count = min(len(manual), available // 2)
    portal_count = min(len(portal), available // 2)
    remaining = available - manual_count - portal_count
    manual_extra = min(len(manual) - manual_count, remaining)
    manual_count += manual_extra
    remaining -= manual_extra
    portal_count += min(len(portal) - portal_count, remaining)
    return (
        f"{manual_header}{manual[:manual_count]}"
        f"{portal_header}{portal[:portal_count]}"
    )[:limit]


def build_naver_blog_workflow_payload(
    settings: WordPressSettings,
    topic: str,
    image_count: int,
    work_folder: str,
    result_queue: queue.Queue,
    cancel_event: threading.Event | None = None,
    image_mode: str = NAVER_BLOG_IMAGE_MODE_AUTO,
    manual_image_paths: list[str] | tuple[str, ...] | None = None,
) -> dict:
    """Prepare a reusable NBlog article package for manual runs and the future queue."""
    _raise_if_naver_blog_cancelled(cancel_event)
    topic = re.sub(r"\s+", " ", str(topic or "")).strip()
    if not topic:
        raise RuntimeError("글 주제를 입력해 주세요.")
    append_runtime_log("NBlog", f"작성 패키지 준비 시작: {topic}")
    result_queue.put(("naver_blog_progress", f"'{topic}'의 최신 검색 내용과 기사 정보를 수집하는 중..."))
    class NaverBlogProgressQueue:
        def put(self, event) -> None:
            if isinstance(event, tuple) and len(event) == 2 and event[0] == "automation_collect_progress":
                payload = event[1]
                message = (
                    str(payload.get("message") or "")
                    if isinstance(payload, dict)
                    else str(payload or "")
                )
                if message:
                    result_queue.put(("naver_blog_progress", message))
                    append_runtime_log("NBlog", message)
                return
            result_queue.put(event)

    collector = AutomationKeywordQueueWorker(settings, [], NaverBlogProgressQueue())
    portal_reference_text = collector._collect_reference_text_for_keyword(
        {
            "keyword": topic,
            "source_name": "N블로그",
            "reference_text": "",
            "source_urls": {
                "naver": f"https://search.naver.com/search.naver?query={quote_plus(topic)}",
                "google": f"https://www.google.com/search?q={quote_plus(topic)}",
            },
        }
    )
    reference_text = combine_naver_blog_reference_text(
        settings.naver_blog_reference_text,
        portal_reference_text,
    )
    _raise_if_naver_blog_cancelled(cancel_event)
    if not reference_text:
        raise RuntimeError("주제의 최신 참고내용을 수집하지 못했습니다.")
    append_runtime_log("NBlog", f"직접 입력·포털 통합 참고내용 준비 완료: {len(reference_text)}자")
    title, article_html, body_text, provider_name = generate_naver_blog_article(
        settings,
        topic,
        reference_text,
        result_queue,
        cancel_event=cancel_event,
    )
    work_dir = _naver_blog_work_directory(work_folder, topic)
    image_mode = normalize_naver_blog_image_mode(image_mode)
    try:
        if image_mode == NAVER_BLOG_IMAGE_MODE_MANUAL:
            image_paths = prepare_naver_blog_manual_image_files(
                manual_image_paths,
                image_count,
                work_dir,
                result_queue,
                cancel_event=cancel_event,
            )
        else:
            image_paths = collect_naver_blog_image_files(
                topic,
                title,
                image_count,
                work_dir,
                result_queue,
                cancel_event=cancel_event,
            )
        _raise_if_naver_blog_cancelled(cancel_event)
    except NaverBlogAutomationCancelled:
        shutil.rmtree(work_dir, ignore_errors=True)
        raise
    (work_dir / "title.txt").write_text(title, encoding="utf-8")
    (work_dir / "body.txt").write_text(body_text, encoding="utf-8")
    (work_dir / "body.html").write_text(article_html, encoding="utf-8")
    (work_dir / "reference.txt").write_text(reference_text, encoding="utf-8")
    payload = {
        "topic": topic,
        "title": title,
        "article_html": article_html,
        "body_text": body_text,
        "reference_text": reference_text,
        "image_paths": image_paths,
        "image_count": len(image_paths),
        "image_mode": image_mode,
        "provider": provider_name,
        "work_dir": str(work_dir),
        "prompt_id": str(settings.naver_blog_prompt_id or ""),
    }
    (work_dir / "manifest.json").write_text(
        json.dumps(payload, ensure_ascii=False, indent=2),
        encoding="utf-8",
    )
    append_runtime_log(
        "NBlog",
        f"작성 패키지 저장 완료: {work_dir} (이미지 {len(image_paths)}개, 모델 {provider_name})",
    )
    return payload


class NaverBlogBootstrapWorker(threading.Thread):
    def __init__(
        self,
        write_url: str,
        blog_id: str,
        result_queue: queue.Queue,
        settings: WordPressSettings | None = None,
        topic: str = "",
        image_count: int = 2,
        work_folder: str = "",
        body_delay_ms: int = 20,
        automation_mode: str = NAVER_BLOG_AUTOMATION_MODE_SEMI,
        profile_scope: str = NAVER_PLAYWRIGHT_PROFILE_BLOG,
        image_mode: str = NAVER_BLOG_IMAGE_MODE_AUTO,
        manual_image_paths: list[str] | tuple[str, ...] | None = None,
    ) -> None:
        super().__init__(daemon=True)
        self.write_url = write_url
        self.blog_id = blog_id
        self.result_queue = result_queue
        self.settings = WordPressSettings(**asdict(settings)) if settings is not None else None
        self.topic = str(topic or "").strip()
        # Keep the worker limit aligned with the persisted NBlog setting and UI.
        self.image_count = max(1, min(int(image_count or 2), 10))
        self.work_folder = str(work_folder or "").strip()
        self.body_delay_ms = max(0, min(int(body_delay_ms or 20), 100))
        self.automation_mode = normalize_naver_blog_automation_mode(automation_mode)
        self.profile_scope = naver_blog_profile_scope(
            {"profile_scope": profile_scope}
        )
        self.image_mode = normalize_naver_blog_image_mode(image_mode)
        self.manual_image_paths = [
            str(path)
            for path in (manual_image_paths or [])
            if str(path or "").strip()
        ]
        self.cancel_event = threading.Event()
        self.article_payload: dict | None = None

    def cancel(self) -> None:
        self.cancel_event.set()

    def _cleanup_cancelled_work(self) -> None:
        work_dir = str((self.article_payload or {}).get("work_dir") or "").strip()
        if work_dir:
            shutil.rmtree(Path(work_dir), ignore_errors=True)

    def run(self) -> None:
        append_runtime_log("NBlog", f"자동화 작업 시작: 주제={self.topic or '(에디터만 열기)'}")
        try:
            article_payload = None
            _raise_if_naver_blog_cancelled(self.cancel_event)
            if self.settings is not None and self.topic:
                article_payload = build_naver_blog_workflow_payload(
                    self.settings,
                    self.topic,
                    self.image_count,
                    self.work_folder,
                    self.result_queue,
                    cancel_event=self.cancel_event,
                    image_mode=self.image_mode,
                    manual_image_paths=self.manual_image_paths,
                )
                self.article_payload = article_payload
            _raise_if_naver_blog_cancelled(self.cancel_event)
            success, message = run_naver_blog_playwright_bootstrap(
                self.write_url,
                self.result_queue,
                self.blog_id,
                article_payload=article_payload,
                body_delay_ms=self.body_delay_ms,
                automation_mode=self.automation_mode,
                cancel_event=self.cancel_event,
                profile_scope=self.profile_scope,
            )
            if success:
                append_runtime_log("NBlog", "자동화 작업 완료")
                self.result_queue.put(("naver_blog_done", message))
            else:
                append_runtime_log("NBlog", f"자동화 작업 실패 응답: {message}")
                self.result_queue.put(("naver_blog_error", message))
        except NaverBlogAutomationCancelled:
            self._cleanup_cancelled_work()
            append_runtime_log("NBlog", "사용자 요청으로 자동화 작업과 임시 파일을 정리했습니다.")
            self.result_queue.put(("naver_blog_cancelled", "자동화를 중단하고 처음 상태로 돌아왔습니다."))
        except Exception as exc:  # pragma: no cover - runtime handling
            append_runtime_log("NBlog", f"자동화 예외: {exc}\n{traceback.format_exc()}")
            self.result_queue.put(("naver_blog_error", friendly_naver_blog_automation_error(exc)))


class NaverSearchAdvisorWorker(threading.Thread):
    def __init__(
        self,
        published_url: str,
        result_queue: queue.Queue,
        show_feedback: bool = True,
        enabled_tools: list[str] | tuple[str, ...] | None = None,
        profile_scope: str = NAVER_PLAYWRIGHT_PROFILE_WRITING,
    ) -> None:
        super().__init__(daemon=True)
        self.published_url = str(published_url or "").strip()
        self.result_queue = result_queue
        self.show_feedback = bool(show_feedback)
        self.profile_scope = normalize_naver_playwright_profile_scope(profile_scope)
        requested_tools = WEBMASTER_TOOL_KEYS if enabled_tools is None else enabled_tools
        self.enabled_tools = tuple(
            tool for tool in WEBMASTER_TOOL_KEYS if tool in set(requested_tools)
        )

    def run(self) -> None:
        completed_messages: list[str] = []
        failed_messages: list[str] = []
        if WEBMASTER_TOOL_NAVER in self.enabled_tools:
            try:
                naver_success, naver_message = run_naver_search_advisor_playwright(
                    self.published_url,
                    self.result_queue,
                    profile_scope=self.profile_scope,
                )
                if naver_success:
                    completed_messages.append(str(naver_message or "네이버 수집 요청을 완료했습니다."))
                else:
                    failed_messages.append(str(naver_message or "네이버 수집 요청에 실패했습니다."))
            except Exception as exc:  # pragma: no cover - runtime handling
                message = f"네이버: {exc}"
                failed_messages.append(message)
                append_runtime_log("naver-search-advisor", f"네이버 수집 요청 실패, 다음 단계 계속: {exc}")

        # Search engines are independent. One delayed or failed request must
        # never prevent the remaining collection requests from being attempted.
        if WEBMASTER_TOOL_DAUM in self.enabled_tools:
            try:
                daum_success, daum_message = run_daum_webmaster_playwright(
                    self.published_url,
                    self.result_queue,
                )
                if daum_success:
                    completed_messages.append(str(daum_message or "다음 수집 요청을 완료했습니다."))
                else:
                    failed_messages.append(str(daum_message or "다음 수집 요청에 실패했습니다."))
            except Exception as exc:  # pragma: no cover - runtime handling
                message = f"다음: {exc}"
                failed_messages.append(message)
                append_runtime_log("daum-webmaster", f"다음 수집 요청 실패, Google 단계 계속: {exc}")

        if WEBMASTER_TOOL_GOOGLE in self.enabled_tools:
            try:
                google_success, google_message = run_google_search_console_playwright(
                    self.published_url,
                    self.result_queue,
                )
                if google_success:
                    completed_messages.append(str(google_message or "Google 색인 요청을 완료했습니다."))
                else:
                    failed_messages.append(str(google_message or "Google 색인 요청에 실패했습니다."))
            except Exception as exc:  # pragma: no cover - runtime handling
                message = f"Google: {exc}"
                failed_messages.append(message)
                append_runtime_log("google-search-console", f"Google 색인 요청 실패: {exc}")

        selected_labels = "·".join(WEBMASTER_TOOL_LABELS[tool] for tool in self.enabled_tools)
        if not self.enabled_tools:
            self.result_queue.put(
                (
                    "naver_search_advisor_done",
                    {
                        "message": "선택된 웹마스터도구가 없어 수집 요청을 건너뛰었습니다.",
                        "published_url": self.published_url,
                        "show_feedback": self.show_feedback,
                        "partial": False,
                        "selected_labels": "",
                    },
                )
            )
            return

        if completed_messages:
            message_parts = list(completed_messages)
            if failed_messages:
                message_parts.append("확인이 필요한 항목:\n" + "\n".join(failed_messages))
            payload = {
                "message": "\n".join(message_parts),
                "published_url": self.published_url,
                "show_feedback": self.show_feedback,
                "partial": bool(failed_messages),
                "selected_labels": selected_labels,
            }
            self.result_queue.put(("naver_search_advisor_done", payload))
            return

        message = "\n".join(failed_messages) or f"{selected_labels} 수집 요청에 실패했습니다."
        append_runtime_log("naver-search-advisor", f"수집 요청 전체 실패: {message}")
        self.result_queue.put(
            (
                "naver_search_advisor_error",
                {
                    "message": message,
                    "published_url": self.published_url,
                    "show_feedback": self.show_feedback,
                    "selected_labels": selected_labels,
                },
            )
        )


class NaverKinBootstrapWorker(threading.Thread):
    def __init__(self, question_list_url: str, sort_mode: str, result_queue: queue.Queue) -> None:
        super().__init__(daemon=True)
        self.question_list_url = question_list_url.strip() or NAVER_KIN_QUESTION_LIST_URL
        self.sort_mode = sort_mode.strip() or "최신순"
        self.result_queue = result_queue

    def run(self) -> None:
        try:
            success, payload = run_naver_kin_playwright_bootstrap(
                self.question_list_url,
                self.sort_mode,
                self.result_queue,
            )
            if success:
                self.result_queue.put(("naver_kin_done", payload))
            else:
                self.result_queue.put(("naver_kin_error", payload))
        except Exception as exc:  # pragma: no cover - runtime handling
            self.result_queue.put(("naver_kin_error", str(exc)))


class NaverKinAutomationWorker(threading.Thread):
    def __init__(self, settings: WordPressSettings, question: dict, result_queue: queue.Queue) -> None:
        super().__init__(daemon=True)
        self.settings = WordPressSettings(**asdict(settings))
        self.question = dict(question or {})
        self.result_queue = result_queue

    def run(self) -> None:
        cleanup_paths: list[str] = []
        try:
            question_title = clean_naver_kin_question_title(self.question.get("title"))
            question_text = clean_naver_kin_question_body(
                self.question.get("question_text"),
                question_title,
            )
            question_url = str(self.question.get("url") or "").strip()
            if not question_title or not question_url:
                raise RuntimeError("처리할 지식인 질문 제목 또는 URL이 없습니다.")
            if not naver_kin_question_ready(
                {
                    **self.question,
                    "title": question_title,
                    "question_text": question_text,
                    "url": question_url,
                }
            ):
                raise RuntimeError(
                    "질문 상세 본문이 충분히 수집되지 않아 자동 답변을 중단했습니다. "
                    "질문 목록을 다시 수집해 주세요."
                )
            if not self.settings.blog_url or not self.settings.username or not self.settings.app_password:
                raise RuntimeError("워드프레스 연결 정보가 없습니다. 환경설정에서 워드프레스 연결을 먼저 확인해 주세요.")

            put_naver_kin_action_log(self.result_queue, f"선택한 지식인 질문: {question_title}")
            self.result_queue.put(("naver_kin_auto_progress", "지식인 질문 상세페이지 접근 가능 여부를 먼저 확인합니다..."))
            run_naver_kin_answer_playwright(
                question_url,
                "사전 확인",
                self.result_queue,
                login_timeout_seconds=int(getattr(self.settings, "naver_kin_login_timeout_seconds", 300) or 300),
                post_submit_hold_seconds=0,
                question_title=question_title,
                preflight_only=True,
            )
            self.result_queue.put(("naver_kin_auto_progress", "지식인 질문을 바탕으로 워드프레스 글 작성 프롬프트를 준비합니다..."))
            self.settings.target_platforms = ["wordpress"]
            self.settings.post_mode = "공개발행"
            wordpress_prompt = resolve_naver_kin_wordpress_prompt_set(self.settings)
            self.settings.naver_kin_wordpress_prompt_id = str(wordpress_prompt.get("id") or "")
            self.settings.wordpress_title_prompt_template = nonempty_text(
                wordpress_prompt.get("title_prompt"),
                DEFAULT_WORDPRESS_TITLE_PROMPT,
            )
            self.settings.wordpress_article_prompt_template = nonempty_text(
                wordpress_prompt.get("article_prompt"),
                DEFAULT_WORDPRESS_ARTICLE_PROMPT,
            )
            put_naver_kin_action_log(
                self.result_queue,
                f"워드프레스 프롬프트 적용: {wordpress_prompt.get('name') or '기본'}",
            )
            topic = "N지식인 답변"
            keyword = question_title
            reference_text = (
                f"[N지식인 질문]\n{question_title}\n\n"
                f"질문 URL: {question_url}\n\n"
                f"질문 본문:\n{question_text or question_title}\n"
            )
            title, article_html, provider_name = self._generate_article(topic, keyword, reference_text)
            put_naver_kin_action_log(self.result_queue, f"워드프레스 글 생성 완료: {title}")

            self.result_queue.put(("naver_kin_auto_progress", "워드프레스에 공개 발행할 SEO 정보를 준비합니다..."))
            focus_keyword, tag_names = build_naver_kin_focus_keyword_and_tags(question_title, question_text, title)
            slug = slugify_korean_text(focus_keyword or title)
            meta_description = build_meta_description(topic, focus_keyword or keyword)
            wordpress_client = WordPressClient(self.settings)
            tag_ids = wordpress_client.ensure_tag_ids(tag_names)
            wordpress_title = ensure_focus_keyword_in_title(title, focus_keyword)
            content = ensure_focus_keyword_in_content(article_html, focus_keyword)
            featured_media_id = None

            self.result_queue.put(("naver_kin_auto_progress", "기본 썸네일 이미지를 만들고 워드프레스에 업로드합니다..."))
            thumbnail_path = DATA_DIR / f"naver-kin-thumbnail-{int(time.time() * 1000)}.png"
            thumbnail_text = self._generate_thumbnail_text(wordpress_title, focus_keyword, question_title, question_text)
            create_default_thumbnail_png(self.settings, thumbnail_text, thumbnail_path)
            cleanup_paths.append(str(thumbnail_path))
            thumbnail_media = wordpress_client.upload_media(thumbnail_path, wordpress_title)
            featured_media_id = thumbnail_media.get("id")
            thumbnail_url = str(thumbnail_media.get("source_url") or "").strip()
            if thumbnail_url:
                content = (
                    f"<figure class='wp-block-image size-large'>"
                    f"<img src='{escape(thumbnail_url)}' alt='{escape(wordpress_title)}' /></figure>\n"
                    f"{content}"
                )

            cardnews_urls: list[str] = []
            cardnews_count = max(1, min(int(self.settings.inline_images_count or 2), 4))
            summary = plain_text_from_html(content, limit=180) or meta_description or wordpress_title
            self.result_queue.put(("naver_kin_auto_progress", f"본문 카드뉴스 {cardnews_count}장을 만들고 워드프레스에 업로드합니다..."))
            for image_index in range(1, cardnews_count + 1):
                cardnews_path = DATA_DIR / f"naver-kin-cardnews-{int(time.time() * 1000)}-{image_index}.png"
                cardnews_title, cardnews_summary = build_naver_kin_cardnews_copy(
                    wordpress_title,
                    article_html,
                    focus_keyword,
                    image_index,
                    cardnews_count,
                )
                create_default_cardnews_png(
                    self.settings,
                    cardnews_title,
                    cardnews_summary,
                    cardnews_path,
                    image_index,
                    cardnews_count,
                )
                cleanup_paths.append(str(cardnews_path))
                cardnews_media = wordpress_client.upload_media(cardnews_path, f"{cardnews_title} 카드뉴스 {image_index}")
                cardnews_url = str(cardnews_media.get("source_url") or "").strip()
                if cardnews_url:
                    cardnews_urls.append(cardnews_url)
            if cardnews_urls:
                content = insert_cardnews_images(content, cardnews_urls, wordpress_title)

            self.result_queue.put(("naver_kin_auto_progress", "워드프레스에 답변형 글을 공개발행 중입니다..."))
            wordpress_result = wordpress_client.publish_post(
                title=wordpress_title,
                content=content,
                category_id=self.settings.category_id,
                status="publish",
                featured_media_id=featured_media_id,
                tag_ids=tag_ids,
                category_ids=self.settings.category_ids,
                slug=slug,
                excerpt=meta_description,
            )
            post_id = int(wordpress_result.get("post_id") or 0)
            if post_id:
                wordpress_client.update_rank_math_metadata(
                    post_id,
                    {
                        "rank_math_focus_keyword": focus_keyword,
                        "rank_math_description": meta_description,
                        "rank_math_title": wordpress_title,
                    },
                )
            wordpress_url = str(wordpress_result.get("link") or wordpress_result.get("post_url") or "").strip()
            if not wordpress_url:
                raise RuntimeError("워드프레스 공개발행 URL을 가져오지 못했습니다.")
            put_naver_kin_action_log(self.result_queue, f"워드프레스 공개발행 완료: {wordpress_url}")

            self.result_queue.put(("naver_kin_auto_progress", "프롬프트관리의 N지식인자동화 프롬프트를 참고해 지식인 답변을 작성합니다..."))
            answer_text = build_naver_kin_answer_text(
                self.settings,
                question_title,
                question_text,
                wordpress_title,
                wordpress_url,
                meta_description,
            )
            put_naver_kin_action_log(self.result_queue, "지식인 답변 문구 생성 완료. 지식인 상세페이지로 이동합니다.")
            success, answer_message = run_naver_kin_answer_playwright(
                question_url,
                answer_text,
                self.result_queue,
                question_title=question_title,
            )
            if not success:
                raise RuntimeError(answer_message)
            self.result_queue.put(
                (
                    "naver_kin_auto_done",
                    {
                        "question_url": question_url,
                        "question_title": question_title,
                        "wordpress_url": wordpress_url,
                        "wordpress_title": wordpress_title,
                        "answer_text": answer_text,
                        "provider": provider_name,
                        "thumbnail_path": str(thumbnail_path),
                        "cardnews_count": len(cardnews_urls),
                        "cleanup_count": cleanup_generated_upload_images(cleanup_paths),
                        "message": answer_message,
                    },
                )
            )
        except Exception as exc:  # pragma: no cover - runtime handling
            self.result_queue.put(("naver_kin_auto_error", str(exc)))
        finally:
            cleanup_generated_upload_images(cleanup_paths)

    def _generate_article(self, topic: str, keyword: str, reference_text: str) -> tuple[str, str, str]:
        reference_block = (
            "\n\n[참고내용]\n"
            "아래 지식인 질문 내용을 바탕으로 질문자의 의도를 먼저 파악하고, 확인 가능한 사실 중심으로 답변형 글을 작성하세요.\n"
            f"{reference_text[:12000]}\n"
            "[참고내용 끝]\n"
        )
        title_managed_prompt = render_prompt_template(
            self.settings.wordpress_title_prompt_template
            or self.settings.title_prompt_template
            or DEFAULT_WORDPRESS_TITLE_PROMPT,
            topic,
            keyword,
            reference_text[:12000],
        )
        title_prompt = (
            "[프롬프트관리 - 워드프레스 제목 프롬프트]\n"
            f"{title_managed_prompt}\n\n"
            "[N지식인 자동화 조건]\n"
            f"- 아래 지식인 질문 제목은 참고자료일 뿐이며, 그대로 복사하거나 인용하지 않습니다: {keyword}\n"
            "- 질문 제목에서 핵심 키워드만 뽑아 20~34자 내외의 워드프레스용 정보형 제목 1개를 새로 만듭니다.\n"
            "- 질문 말투(예: ~인가요, ~해주세요, 궁금합니다)는 제목에 넣지 않습니다.\n"
            "- 제목은 '핵심 키워드 + 해결 방법/핵심 정리/주의사항'처럼 짧고 검색형으로 작성합니다.\n"
            "- 설명, 번호, 따옴표, 마크다운은 붙이지 않습니다."
            + reference_block
        )
        raw_title, provider_name = self._generate_with_provider(title_prompt)
        generated_title = compact_naver_kin_blog_title(raw_title, keyword, reference_text)

        article_managed_prompt = render_prompt_template(
            self.settings.wordpress_article_prompt_template
            or self.settings.article_prompt_template
            or DEFAULT_WORDPRESS_ARTICLE_PROMPT,
            topic,
            keyword,
            reference_text[:12000],
            generated_title,
        )
        article_prompt = (
            "[프롬프트관리 - 워드프레스 본문글작성 프롬프트]\n"
            f"{article_managed_prompt}\n\n"
            "[N지식인 자동화 필수 조건]\n"
            f"- 글 제목은 '{generated_title}' 입니다.\n"
            f"- 본문은 반드시 지식인 질문 '{keyword}'에 대한 답변형 워드프레스 글이어야 합니다.\n"
            "- 질문 본문에 없는 사실은 단정하지 말고, 필요한 경우 확인 필요라고 표현합니다.\n"
            "- HTML 본문만 반환합니다."
            + reference_block
        )
        article_html, provider_name = self._generate_with_provider(article_prompt)
        article_html = normalize_generated_article_html(article_html)
        title = compact_naver_kin_blog_title(generated_title or extract_title_from_article_html(article_html, keyword), keyword, reference_text)
        return title, article_html, provider_name

    def _generate_thumbnail_text(self, title: str, focus_keyword: str, question_title: str, question_text: str) -> str:
        fallback = shorten_thumbnail_text(title, focus_keyword or question_title, max_chars=18)
        prompt = (
            "[N지식인 워드프레스 썸네일 문구 생성]\n"
            "아래 글 제목을 블로그 썸네일에 들어갈 아주 짧은 대표 문구로 축약하세요.\n\n"
            "[원칙]\n"
            "- 전체 제목을 그대로 쓰지 않습니다.\n"
            "- 8~18자 내외의 핵심 문구만 반환합니다.\n"
            "- 가능하면 2~3개 단어로 구성합니다.\n"
            "- 설명, 따옴표, 번호, 마침표, 마크다운은 금지합니다.\n"
            "- 사망/질병/사고 등 민감 주제는 자극적으로 쓰지 말고 사실 중심으로 축약합니다.\n\n"
            f"글 제목: {title}\n"
            f"핵심 키워드: {focus_keyword or question_title}\n"
            f"질문 본문 요약: {plain_text_from_html(question_text, limit=220)}"
        )
        try:
            generated, _provider = self._generate_with_provider(prompt)
            generated = normalize_generated_article_html(generated)
            generated = re.sub(r"^[\"'`“”‘’\s]+|[\"'`“”‘’\s]+$", "", generated)
            generated = re.split(r"[\n\r]", generated.strip())[0].strip()
            shortened = shorten_thumbnail_text(generated, focus_keyword or question_title, max_chars=18)
            return shortened or fallback
        except Exception:
            return fallback

    def _generate_with_provider(self, prompt: str) -> tuple[str, str]:
        return generate_text_with_writing_model(self.settings, prompt)


class ThumbnailAIWorker(threading.Thread):
    def __init__(
        self,
        settings: WordPressSettings,
        title: str,
        keyword: str,
        article_html: str,
        result_queue: queue.Queue,
    ) -> None:
        super().__init__(daemon=True)
        self.settings = settings
        self.title = title.strip()
        self.keyword = keyword.strip()
        self.article_html = article_html.strip()
        self.result_queue = result_queue

    def run(self) -> None:
        try:
            self.result_queue.put(("thumbnail_ai_progress", "Codex CLI로 썸네일 콘셉트 프롬프트를 설계하는 중..."))
            prompt = self._build_fallback_imagen_prompt()
            codex_prompt = self._build_codex_prompt()
            codex_output = self._run_codex_cli(codex_prompt)
            if codex_output:
                prompt = self._clean_codex_prompt(codex_output)

            self.result_queue.put(("thumbnail_ai_progress", "Imagen 4 Fast로 썸네일 배경 이미지를 생성하는 중..."))
            output_path = DATA_DIR / f"codex-imagen-thumbnail-{int(time.time() * 1000)}.png"
            ImagenClient(self.settings.imagen_api_key).generate_image(self.settings.imagen_model, prompt, output_path)
            self.result_queue.put(
                (
                    "thumbnail_ai_done",
                    {
                        "image_path": str(output_path),
                        "prompt": prompt,
                    },
                )
            )
        except Exception as exc:  # pragma: no cover - runtime handling
            self.result_queue.put(("thumbnail_ai_error", str(exc)))

    def _run_codex_cli(self, prompt: str) -> str:
        if not self.settings.codex_cli_enabled:
            return ""
        result = execute_codex_cli_text(
            self.settings,
            prompt,
            timeout=max(20, int(self.settings.codex_cli_timeout or 120)),
        )
        return result.output if result.success else ""

    def _build_codex_prompt(self) -> str:
        summary = plain_text_from_html(self.article_html, limit=900)
        return (
            "You are a senior Korean blog thumbnail art director.\n"
            "Create exactly one English prompt for Google Imagen 4 Fast to generate a clean blog thumbnail background image.\n"
            "Important constraints:\n"
            "- Output only the Imagen prompt, no markdown, no explanation.\n"
            "- The image prompt must request a text-free background only.\n"
            "- Do not include Korean text, English text, letters, numbers, captions, labels, signboards, UI text, or typography in the image.\n"
            "- Avoid logos, trademarks, UI screenshots, real person likenesses, and clutter.\n"
            "- Style should be editorial, high-conversion Korean blog thumbnail, clear central subject, enough negative space for large Korean title text.\n"
            "- Square 1:1 composition, mobile readable, polished, trustworthy.\n\n"
            f"Blog title: {self.title}\n"
            f"Main keyword: {self.keyword}\n"
            f"Article summary: {summary}\n"
        )

    def _build_fallback_imagen_prompt(self) -> str:
        summary = plain_text_from_html(self.article_html, limit=420)
        return (
            "Square 1:1 Korean blog thumbnail background, clean editorial design, "
            "high-conversion information blog style, clear symbolic visual related to "
            f"'{self.keyword or self.title}', large empty center area for Korean headline overlay, "
            "soft depth, modern composition, trustworthy, bright but not cluttered. "
            "Absolutely no text, no Korean, no English, no letters, no numbers, no typography, no captions, no labels, no logos. "
            f"Context: {summary}"
        )

    def _clean_codex_prompt(self, value: str) -> str:
        value = normalize_generated_article_html(value)
        value = re.sub(r"^imagen prompt\s*:\s*", "", value, flags=re.I).strip()
        value = value.strip("` \n\t\"'")
        if len(value) < 40:
            return self._build_fallback_imagen_prompt()
        return enforce_imagen_no_text_prompt(value[:1800])


class TistoryAutomationWorker(threading.Thread):
    def __init__(
        self,
        title: str,
        article_html: str,
        result_queue: queue.Queue,
        delay_seconds: float = 5.0,
        mode_only: bool = False,
        thumbnail_path: str = "",
        automation_prompt: str = DEFAULT_TISTORY_AUTOMATION_PROMPT,
        tag_names: list[str] | None = None,
        publish_after_input: bool = False,
        save_mode: str = "",
        close_after_publish: bool = False,
        write_url: str = "",
        public_blog_url: str = "",
        reference_image_protection_mode: bool = True,
        input_mode: str = TEXT_INPUT_MODE_FAST,
        ads_enabled: bool = True,
        ads_code: str = DEFAULT_TISTORY_AD_CODE,
        ads_slot_id: str = DEFAULT_TISTORY_AD_SLOT_ID,
        ads_position: str = TISTORY_AD_POSITION_ABOVE,
        ads_count: int = 1,
    ) -> None:
        super().__init__(daemon=True)
        self.title = title
        self.article_html = article_html
        self.result_queue = result_queue
        self.delay_seconds = delay_seconds
        self.mode_only = mode_only
        self.thumbnail_path = thumbnail_path
        self.automation_prompt = automation_prompt
        self.tag_names = tag_names or []
        self.save_mode = normalize_tistory_save_mode(
            save_mode or (
                TISTORY_SAVE_MODE_PUBLISH
                if publish_after_input
                else TISTORY_SAVE_MODE_DRAFT
            )
        )
        self.publish_after_input = self.save_mode == TISTORY_SAVE_MODE_PUBLISH
        self.close_after_publish = close_after_publish
        self.write_url = write_url
        self.public_blog_url = public_blog_url
        self.reference_image_protection_mode = reference_image_protection_mode
        self.input_mode = normalize_text_input_mode(input_mode)
        self.ads_enabled = bool(ads_enabled)
        self.ads_code = str(ads_code or "")
        self.ads_slot_id = normalize_tistory_ad_slot_id(ads_slot_id)
        self.ads_position = normalize_tistory_ad_position(ads_position)
        self.ads_count = normalize_tistory_ad_count(ads_count)

    def run(self) -> None:
        reference_image_paths: list[str] = []
        try:
            thumbnail_data_url = ""
            thumbnail_content_url = ""
            native_image_files: dict[str, str] = {}
            if self.thumbnail_path:
                self.result_queue.put(("tistory_progress", "썸네일 이미지를 티스토리 파일 첨부용으로 준비 중입니다..."))
                thumbnail_data_url = image_file_to_data_url(self.thumbnail_path)
                thumbnail_content_url = "__BLOG_HELPER_TISTORY_NATIVE_THUMBNAIL__"
                native_image_files[thumbnail_content_url] = self.thumbnail_path

            article_html = self.article_html
            if GOOGLE_IMAGE_COLLAGE_ENABLED:
                mode_message = (
                    "글 제목과 일치하는 재사용 허용 참고 이미지를 찾고 있습니다..."
                    if self.reference_image_protection_mode
                    else "저작권 보호 모드 OFF: 뉴스·포털을 포함한 일반 웹 검색에서 관련 이미지를 찾고 있습니다..."
                )
                self.result_queue.put(
                    (
                        "tistory_progress",
                        mode_message,
                    )
                )
                reference_images = collect_tistory_reference_image_files(
                    self.title,
                    self.tag_names,
                    GOOGLE_IMAGE_COLLAGE_COUNT,
                    protection_mode=self.reference_image_protection_mode,
                )
                reference_image_paths = [
                    str(image.get("path") or "").strip()
                    for image in reference_images
                    if str(image.get("path") or "").strip()
                ]
                if reference_images:
                    figures = [
                        build_tistory_reference_image_figure(
                            image,
                            self.title,
                            index,
                            show_source_attribution=self.reference_image_protection_mode,
                        )
                        for index, image in enumerate(reference_images, start=1)
                    ]
                    article_html = insert_reference_images_in_article_middle(article_html, figures)
                    self.result_queue.put(
                        (
                            "tistory_progress",
                            f"관련 참고 이미지 {len(reference_images)}장의 이미지 영역만 캡처해 본문 중간에 배치했습니다.",
                        )
                    )
                else:
                    empty_message = (
                        "제목과 직접 관련되고 재사용 조건을 확인할 수 있는 이미지를 찾지 못해 참고 이미지 삽입은 생략합니다."
                        if self.reference_image_protection_mode
                        else "제목과 직접 관련된 일반 웹 이미지를 찾지 못해 참고 이미지 삽입은 생략합니다."
                    )
                    self.result_queue.put(
                        (
                            "tistory_progress",
                            empty_message,
                        )
                    )

            inserted_ad_count = 0
            if self.ads_enabled:
                article_html, inserted_ad_count = insert_tistory_ads_near_images(
                    article_html,
                    self.ads_code,
                    self.ads_position,
                    self.ads_count,
                    ad_slot_id=self.ads_slot_id,
                )
            if inserted_ad_count:
                ad_message = (
                    f"본문 이미지 {inserted_ad_count}곳의 {self.ads_position}에 "
                    "Google 광고 코드를 삽입했습니다."
                )
            elif self.ads_enabled and self.ads_count > 0 and self.ads_code.strip():
                ad_message = "본문에 첨부 이미지가 없어 Google 광고 삽입을 생략했습니다."
            else:
                ad_message = "티스토리 Google 광고 삽입 설정이 꺼져 있어 광고를 생략했습니다."
            self.result_queue.put(("tistory_progress", ad_message))
            append_runtime_log(
                "TISTORY",
                (
                    f"본문 광고 준비: enabled={self.ads_enabled}, requested={self.ads_count}, "
                    f"inserted={inserted_ad_count}, position={self.ads_position}, "
                    f"slot={self.ads_slot_id or '없음'}"
                ),
            )
            prepared_article_html, article_native_files = prepare_tistory_native_attachment_html(
                article_html,
                self.title,
            )
            final_ad_unit_count = len(
                re.findall(
                    r"<ins\b[^>]*\badsbygoogle\b",
                    prepared_article_html,
                    flags=re.I,
                )
            )
            append_runtime_log(
                "TISTORY",
                (
                    "발행 직전 광고 단위 확인: "
                    f"markers={prepared_article_html.count(TISTORY_ADSENSE_IMAGE_BLOCK_START)}, "
                    f"units={final_ad_unit_count}"
                ),
            )
            native_image_files.update(article_native_files)
            script = build_tistory_editor_automation_script(
                self.title,
                prepared_article_html,
                mode_only=self.mode_only,
                input_mode=self.input_mode,
                thumbnail_data_url=thumbnail_data_url,
                thumbnail_content_url=thumbnail_content_url,
                collage_images=[],
                automation_actions=parse_tistory_automation_prompt(self.automation_prompt),
                tag_names=self.tag_names,
                thumbnail_file_name=Path(self.thumbnail_path).name if self.thumbnail_path else "blog-helper-thumbnail.png",
                publish_after_input=self.publish_after_input,
                save_mode=self.save_mode,
                close_after_publish=self.close_after_publish,
            )
            success, message = run_tistory_playwright_automation(
                self.write_url,
                script,
                self.result_queue,
                publish_after_input=self.publish_after_input,
                native_image_files=native_image_files,
                representative_image_path=self.thumbnail_path if self.publish_after_input else "",
                public_blog_url=self.public_blog_url,
                expected_title=self.title,
                save_mode=self.save_mode,
            )
            if success:
                if isinstance(message, dict):
                    done_payload = {
                        "message": str(message.get("message") or "티스토리 자동화를 완료했습니다."),
                        "published_url": str(message.get("published_url") or "").strip(),
                        "save_mode": normalize_tistory_save_mode(
                            str(message.get("save_mode") or self.save_mode)
                        ),
                    }
                else:
                    done_payload = {
                        "message": str(message or "티스토리 자동화를 완료했습니다."),
                        "published_url": "",
                        "save_mode": self.save_mode,
                    }
                self.result_queue.put(("tistory_automation_done", done_payload))
            else:
                self.result_queue.put(("tistory_automation_error", message))
        except Exception as exc:  # pragma: no cover - runtime handling
            self.result_queue.put(("tistory_automation_error", str(exc)))
        finally:
            cleanup_generated_upload_images(reference_image_paths)
            cleanup_tistory_automation_files()


class ArticleGenerationWorker(threading.Thread):
    def __init__(
        self,
        settings: WordPressSettings,
        topic: str,
        keyword: str,
        reference_text: str,
        result_queue: queue.Queue,
    ) -> None:
        super().__init__(daemon=True)
        self.settings = settings
        self.topic = topic
        self.keyword = keyword
        self.reference_text = reference_text.strip()
        self.result_queue = result_queue

    def run(self) -> None:
        try:
            self.result_queue.put(("article_progress", (0.1, "프롬프트를 준비하고 있습니다...")))
            reference_block = ""
            if self.reference_text:
                reference_block = (
                    "\n\n[참고내용]\n"
                    "아래 참고내용의 정보, 흐름, 사례, 표현 의도를 최대한 활용하되 문장은 새롭게 재작성하세요.\n"
                    "참고내용과 충돌하는 내용은 임의로 만들지 말고, 참고내용에 있는 핵심 사실을 우선 반영하세요.\n"
                    "다른 블로그 원문이 포함된 경우 원문 문장·문단·고유 표현을 그대로 복사하지 말고, 핵심 사실과 구조만 참고해 완전히 새로운 다정한 말투로 작성하세요.\n"
                    f"{self.reference_text[:12000]}\n"
                    "[참고내용 끝]\n"
                )
            title_managed_prompt = render_prompt_template(
                self.settings.title_prompt_template,
                self.topic,
                self.keyword,
                self.reference_text[:12000],
            )
            title_prompt = (
                "[프롬프트관리 - 제목 프롬프트]\n"
                f"{title_managed_prompt}\n\n"
                "[필수 실행 조건]\n"
                f"- 제목의 핵심 키워드는 '{self.keyword}' 입니다.\n"
                "- 제목만 반환하고 설명, 번호, 따옴표, 마크다운은 붙이지 않습니다.\n"
                + reference_block
            )
            self.result_queue.put(("article_progress", (0.25, "AI 모델에 제목 생성을 요청하고 있습니다...")))
            raw_title, provider_name = self._generate_with_provider(title_prompt, progress=0.25)
            generated_title = clean_generated_title(raw_title, self.keyword)

            managed_prompt = render_prompt_template(
                self.settings.article_prompt_template,
                self.topic,
                self.keyword,
                self.reference_text[:12000],
                generated_title,
            )
            prompt = (
                "[프롬프트관리 - 본문글작성 프롬프트]\n"
                f"{managed_prompt}\n\n"
                "[필수 실행 조건]\n"
                f"- 글 제목은 '{generated_title}' 입니다.\n"
                f"- 전체 글의 핵심 주제는 '{self.keyword}' 이어야 합니다.\n"
                f"- '{self.topic}' 은 큰 주제 참고용이며, 본문은 반드시 '{self.keyword}' 중심으로 작성합니다.\n"
                f"- H1 또는 첫 문단에 '{self.keyword}'를 자연스럽게 포함합니다.\n"
                "- 참고내용이 제공된 경우 참고내용의 핵심 정보와 논리 전개를 최우선으로 반영합니다.\n"
                "- 참고내용을 그대로 복붙하지 말고 자연스러운 새 문장으로 재작성합니다.\n"
                "- 벤치마킹 원문이 있는 경우 원문과 구별되는 새 구성, 새 문장, 새 예시 표현으로 작성합니다.\n"
                "- 다른 엉뚱한 주제로 전환하지 않습니다.\n"
                "- HTML 본문만 반환합니다.\n"
                + reference_block
            )
            self.result_queue.put(("article_progress", (0.45, "AI 모델에 본문 생성을 요청하고 있습니다...")))
            article_html, provider_name = self._generate_with_provider(prompt, progress=0.45)

            self.result_queue.put(("article_progress", (0.8, "생성된 글을 정리하고 있습니다...")))
            article_html = normalize_generated_article_html(article_html)
            title = generated_title or extract_title_from_article_html(article_html, self.keyword)
            if self.settings.inline_images_enabled:
                try:
                    article_html = self._attach_inline_images(title, article_html)
                except Exception as image_exc:
                    self.result_queue.put(
                        (
                            "article_progress",
                            (0.94, f"본문 이미지 생성은 건너뛰고 글만 먼저 완료합니다: {str(image_exc)[:120]}"),
                        )
                    )
            self.result_queue.put(
                (
                    "article_done",
                    {
                        "title": title,
                        "html": article_html,
                        "provider": provider_name,
                    },
                )
            )
        except Exception as exc:  # pragma: no cover - runtime handling
            error_message = str(exc).strip() or exc.__class__.__name__
            if is_network_timeout(exc):
                error_message = (
                    "AI 글 생성 응답 시간이 초과되었습니다. 잠시 후 다시 글 작성을 눌러 주세요."
                )
            append_runtime_log("ARTICLE", f"글 생성 실패: {error_message}")
            self.result_queue.put(("article_error", error_message))

    def _generate_with_provider(self, prompt: str, progress: float = 0.45) -> tuple[str, str]:
        def report_retry(message: str) -> None:
            self.result_queue.put(("article_progress", (progress, message)))

        return generate_text_with_writing_model(
            self.settings,
            prompt,
            on_retry=report_retry,
        )

    def _attach_inline_images(self, title: str, article_html: str) -> str:
        if not self.settings.imagen_api_key:
            self.result_queue.put(("article_progress", (0.86, "Imagen API 키가 없어 본문 이미지 삽입은 건너뜁니다.")))
            return article_html
        count = max(1, min(int(self.settings.inline_images_count or 2), 4))
        provider = self.settings.inline_images_provider or "Imagen API"
        if provider == "카드뉴스 생성":
            self.result_queue.put(("article_progress", (0.92, "카드뉴스 생성은 4번 썸네일 제작 단계에서 진행합니다.")))
            return article_html
        imagen_client = ImagenClient(self.settings.imagen_api_key)
        figures: list[str] = []
        started_at = time.time()
        max_total_seconds = 180
        for index in range(1, count + 1):
            if time.time() - started_at > max_total_seconds:
                self.result_queue.put(("article_progress", (0.93, "본문 이미지 생성 시간이 길어져 남은 이미지는 건너뜁니다.")))
                break
            progress = 0.82 + (0.14 * (index / count))
            self.result_queue.put(("article_progress", (progress, f"본문 이미지 {index}/{count} 생성 중...")))
            try:
                if provider == "Codex CLI + Imagen":
                    prompt = refine_inline_image_prompt_with_codex(
                        self.settings,
                        title,
                        self.keyword,
                        article_html,
                        index,
                        count,
                    )
                else:
                    prompt = build_inline_image_prompt(title, self.keyword, article_html, index, count)
                image_path = DATA_DIR / f"inline-image-{int(time.time() * 1000)}-{index}.png"
                imagen_client.generate_image(self.settings.imagen_model, prompt, image_path)
                figures.append(build_inline_image_figure(image_path, title, index))
            except Exception as exc:
                self.result_queue.put(("article_progress", (progress, f"본문 이미지 {index}/{count} 생성 실패 - 다음 단계로 넘어갑니다.")))
                continue
        return insert_inline_image_figures(article_html, figures)


class PublishPipelineWorker(threading.Thread):
    def __init__(
        self,
        settings: WordPressSettings,
        title: str,
        article_html: str,
        thumbnail_path: str,
        focus_keyword: str,
        tag_names: list[str],
        slug: str,
        meta_description: str,
        result_queue: queue.Queue,
    ) -> None:
        super().__init__(daemon=True)
        self.settings = settings
        self.title = title
        self.article_html = article_html
        self.thumbnail_path = thumbnail_path
        self.focus_keyword = focus_keyword
        self.tag_names = tag_names
        self.slug = slug
        self.meta_description = meta_description
        self.result_queue = result_queue

    def run(self) -> None:
        try:
            wordpress_result = None
            prepared_article_html = hydrate_inline_image_placeholders(self.article_html, self.title)
            cleanup_paths: list[str] = []
            if self.thumbnail_path:
                cleanup_paths.append(self.thumbnail_path)
            cleanup_paths.extend(extract_inline_image_paths(self.article_html))
            cleanup_paths.extend(extract_inline_image_paths(prepared_article_html))
            target_platforms = set(self.settings.target_platforms or ["wordpress"])
            if "wordpress" in target_platforms and self.settings.blog_url and self.settings.username and self.settings.app_password:
                self.result_queue.put(("publish_progress", (0.15, "썸네일 파일을 준비하고 있습니다...")))
                wordpress_client = WordPressClient(self.settings)
                featured_media_id = None
                media_url = ""
                wordpress_title = ensure_focus_keyword_in_title(self.title, self.focus_keyword)
                content = ensure_focus_keyword_in_content(prepared_article_html, self.focus_keyword)
                inline_image_count = 0
                if self.thumbnail_path:
                    self.result_queue.put(("publish_progress", (0.28, "워드프레스에 썸네일 이미지를 업로드하고 있습니다...")))
                    media_result = wordpress_client.upload_media(Path(self.thumbnail_path), wordpress_title)
                    featured_media_id = media_result.get("id")
                    media_url = media_result.get("source_url", "")
                    if media_url:
                        content = (
                            f"<figure class='wp-block-image size-large'>"
                            f"<img src='{media_url}' alt='{escape(wordpress_title)}' /></figure>\n"
                            f"{content}"
                        )

                content, inline_image_count = replace_inline_images_for_wordpress(
                    content,
                    wordpress_client,
                    wordpress_title,
                    self.result_queue,
                )

                cardnews_urls: list[str] = []
                if self.settings.cardnews_enabled and not self.settings.inline_images_enabled:
                    if self.settings.imagen_api_key:
                        cardnews_count = max(1, min(int(self.settings.cardnews_count or 2), 4))
                        imagen_client = ImagenClient(self.settings.imagen_api_key)
                        for index in range(1, cardnews_count + 1):
                            progress = 0.34 + (0.22 * (index / cardnews_count))
                            self.result_queue.put(
                                ("publish_progress", (progress, f"Imagen 4 Fast로 카드뉴스 {index}/{cardnews_count} 생성 중..."))
                            )
                            prompt = build_cardnews_prompt(
                                wordpress_title,
                                self.focus_keyword,
                                prepared_article_html,
                                index,
                                cardnews_count,
                            )
                            image_path = DATA_DIR / f"{CARDNEWS_IMAGE_PREFIX}-{index}.png"
                            imagen_client.generate_image(self.settings.imagen_model, prompt, image_path)
                            cleanup_paths.append(str(image_path))
                            self.result_queue.put(
                                ("publish_progress", (progress + 0.03, f"카드뉴스 {index}/{cardnews_count} 워드프레스 업로드 중..."))
                            )
                            cardnews_media = wordpress_client.upload_media(image_path, f"{wordpress_title} 카드뉴스 {index}")
                            cardnews_url = cardnews_media.get("source_url", "")
                            if cardnews_url:
                                cardnews_urls.append(cardnews_url)
                        if cardnews_urls:
                            content = insert_cardnews_images(content, cardnews_urls, wordpress_title)
                    else:
                        self.result_queue.put(("publish_progress", (0.48, "Imagen API 키가 없어 카드뉴스 생성은 건너뜁니다.")))

                self.result_queue.put(("publish_progress", (0.64, "태그를 정리하고 워드프레스에 등록하고 있습니다...")))
                tag_ids = wordpress_client.ensure_tag_ids(self.tag_names)
                self.result_queue.put(("publish_progress", (0.82, "글과 대표 이미지, 카드뉴스를 워드프레스에 등록하고 있습니다...")))
                wordpress_result = wordpress_client.publish_post(
                    title=wordpress_title,
                    content=content,
                    category_id=self.settings.category_id,
                    status="draft" if self.settings.post_mode == "임시저장" else "publish",
                    featured_media_id=featured_media_id,
                    tag_ids=tag_ids,
                    category_ids=self.settings.category_ids,
                    slug=self.slug,
                    excerpt=self.meta_description,
                )
                if wordpress_result.get("post_id"):
                    rank_math_applied = wordpress_client.update_rank_math_metadata(
                        int(wordpress_result["post_id"]),
                        {
                            "rank_math_focus_keyword": self.focus_keyword,
                            "rank_math_description": self.meta_description,
                            "rank_math_title": wordpress_title,
                        },
                    )
                    wordpress_result["focus_keyword"] = self.focus_keyword
                    wordpress_result["focus_keyword_applied"] = rank_math_applied
                    wordpress_result["tag_names"] = self.tag_names
                    wordpress_result["meta_description"] = self.meta_description
                    wordpress_result["meta_description_applied"] = rank_math_applied
                    wordpress_result["seo_title"] = wordpress_title
                    wordpress_result["seo_title_applied"] = rank_math_applied
                    wordpress_result["slug"] = self.slug
                    wordpress_result["category_names"] = self.settings.category_names
                    wordpress_result["cardnews_count"] = len(cardnews_urls) + inline_image_count

            tistory_result = None
            wordpress_url = ""
            if wordpress_result:
                wordpress_url = str(wordpress_result.get("link") or wordpress_result.get("post_url") or "").strip()
            if "tistory" in target_platforms:
                self.result_queue.put(("publish_progress", (0.88, "티스토리 글쓰기 화면용 초안을 준비하고 있습니다...")))
                write_url = build_tistory_write_url(self.settings.tistory_blog_url, self.settings.tistory_write_url)
                draft_html = build_tistory_draft_document(self.title, prepared_article_html, self.thumbnail_path)
                TISTORY_DRAFT_FILE.write_text(draft_html, encoding="utf-8")
                tistory_result = {
                    "status": "ready",
                    "message": "티스토리 글쓰기 화면을 열고 제목/본문/태그/대표이미지/공개발행 자동입력을 준비했습니다.",
                    "write_url": write_url,
                    "public_blog_url": self.settings.tistory_blog_url,
                    "draft_file": str(TISTORY_DRAFT_FILE),
                    "title": self.title,
                    "html": prepared_article_html,
                    "thumbnail_path": self.thumbnail_path,
                    "focus_keyword": self.focus_keyword,
                    "tag_names": self.tag_names,
                    "wordpress_url": wordpress_url,
                }

            blogspot_result = None
            if "blogspot" in target_platforms:
                self.result_queue.put(("publish_progress", (0.94, "블로그스팟에 글을 등록하고 있습니다...")))
                blogspot_content = prepared_article_html
                if self.thumbnail_path and Path(self.thumbnail_path).exists():
                    try:
                        thumbnail_data_url = image_file_to_data_url(self.thumbnail_path)
                        blogspot_content = (
                            f"<figure><img src='{thumbnail_data_url}' alt='{escape(self.title)}' /></figure>\n"
                            f"{blogspot_content}"
                        )
                    except Exception:
                        pass
                blogspot_result = BlogspotClient(
                    blog_id=self.settings.blogspot_blog_id,
                    access_token=self.settings.blogspot_access_token,
                    client_id=self.settings.blogspot_client_id,
                    client_secret=self.settings.blogspot_client_secret,
                    refresh_token=self.settings.blogspot_refresh_token,
                ).publish_post(
                    title=self.title,
                    content=blogspot_content,
                    status="draft" if self.settings.post_mode == "임시저장" else "publish",
                )
                blogspot_result["message"] = "블로그스팟 등록 완료"

            threads_result = None
            if self.settings.threads_auto_publish:
                if not self.settings.threads_user_id or not self.settings.threads_access_token:
                    threads_result = {
                        "error": "Threads User ID 또는 Access Token이 없습니다.",
                        "message": "Threads 자동 게시 실패",
                    }
                published_url = wordpress_url
                if not published_url and blogspot_result:
                    published_url = str(blogspot_result.get("link") or "").strip()
                if threads_result is None and not published_url:
                    threads_result = {
                        "error": "워드프레스 또는 블로그스팟의 공개 발행 URL이 없습니다.",
                        "message": "Threads 자동 게시 실패",
                    }
                if threads_result is None:
                    try:
                        self.result_queue.put(("publish_progress", (0.97, "블로그 글을 Threads에 자동 게시하고 있습니다...")))
                        threads_text = build_threads_post_text(
                            self.settings,
                            self.title,
                            published_url,
                            self.meta_description,
                            self.focus_keyword,
                        )
                        threads_result = ThreadsClient(
                            "",
                            "",
                            "",
                            self.settings.threads_access_token,
                        ).publish_text(self.settings.threads_user_id, threads_text)
                        threads_result["blog_url"] = published_url
                        threads_result["message"] = "Threads 자동 게시 완료"
                    except Exception as threads_exc:
                        threads_result = {
                            "error": str(threads_exc),
                            "message": "Threads 자동 게시 실패",
                            "blog_url": published_url,
                        }
            self.result_queue.put(
                (
                    "publish_pipeline_done",
                    {
                        "wordpress": wordpress_result,
                        "tistory": tistory_result,
                        "blogspot": blogspot_result,
                        "threads": threads_result,
                        "cleanup_paths": cleanup_paths,
                    },
                )
            )
        except Exception as exc:  # pragma: no cover - runtime handling
            self.result_queue.put(("publish_pipeline_error", str(exc)))


def build_wordpress_post(seed_keyword: str, insight: KeywordInsight) -> tuple[str, str]:
    title = f"{insight.keyword} 완벽 가이드"
    source_lines = "".join(
        f"<li><a href='{url}' target='_blank' rel='noopener noreferrer'>{source} 검색 결과 보기</a></li>"
        for source, url in insight.source_urls.items()
    )
    reasons_html = "".join(f"<li>{reason}</li>" for reason in insight.reasons)
    category_text = ", ".join(insight.categories) if insight.categories else "일반형"

    content = f"""
    <h2>{insight.keyword} 주제로 글을 써야 하는 이유</h2>
    <p><strong>{seed_keyword}</strong>를 기준으로 분석한 결과, <strong>{insight.keyword}</strong>는
    전환 가능성과 검색 확장성이 높은 키워드로 분류되었습니다.</p>

    <h2>핵심 포인트</h2>
    <ul>
      <li>예상 수익 점수: {insight.score}/100</li>
      <li>카테고리 성격: {category_text}</li>
      <li>다중 출처 기반 키워드: {", ".join(insight.sources) if insight.sources else "없음"}</li>
    </ul>

    <h2>이 키워드가 유리한 근거</h2>
    <ul>
      {reasons_html}
    </ul>

    <h2>추천 글 구성</h2>
    <ol>
      <li>{insight.keyword}의 기본 개념과 시장 흐름 정리</li>
      <li>비교 포인트 또는 가격/후기 정보 정리</li>
      <li>초보자용 체크리스트와 실행 팁 제시</li>
      <li>관련 서비스 또는 상품 추천으로 전환 유도</li>
    </ol>

    <h2>출처 확인 링크</h2>
    <ul>
      {source_lines or "<li>외부 출처 링크 없음</li>"}
    </ul>

    <p>이 초안은 자동 생성된 기본 구조입니다. 실제 발행 전 본문 예시, 표, 이미지, 개인 경험을 추가하면 훨씬 좋은 품질의 포스트가 됩니다.</p>
    """.strip()
    return title, content


