    def _load_version_catalog(self, force: bool = False) -> None:
        if not hasattr(self, "version_manager_status_label"):
            return
        if self.version_catalog and not force:
            return
        if self.version_catalog_worker and self.version_catalog_worker.is_alive():
            return
        if not platform_asset_name():
            self.version_manager_status_label.configure(text="현재 운영체제에서는 버전 전환을 지원하지 않습니다.")
            self.version_launch_button.configure(state="disabled")
            return
        self.version_manager_status_label.configure(text="사용 가능한 이전 버전을 확인하고 있습니다...")
        self.version_launch_button.configure(state="disabled")
        self.version_catalog_worker = ReleaseCatalogWorker(
            self.result_queue,
            repository=UPDATE_REPOSITORY,
            current_version=APP_VERSION,
        )
        self.version_catalog_worker.start()

    def _handle_version_catalog(self, releases: list[dict]) -> None:
        self.version_catalog = {
            str(item.get("version") or "").strip().lstrip("v"): dict(item)
            for item in releases
            if str(item.get("version") or "").strip()
        }
        versions = sorted(self.version_catalog, key=version_key, reverse=True)
        if versions:
            self.latest_available_version = versions[0]
        if hasattr(self, "latest_version_value_label"):
            self.latest_version_value_label.configure(text=f"v{self.latest_available_version}")

        # A newer release is handled by the normal updater. The temporary
        # launcher only exposes the running version and older stable releases.
        selectable = [version for version in versions if version_key(version) <= version_key(APP_VERSION)]
        if APP_VERSION not in selectable:
            selectable.insert(0, APP_VERSION)
        values = [
            f"v{version}{' (현재)' if version == APP_VERSION else ''}"
            for version in selectable
        ]
        self.version_choice_menu.configure(values=values)
        self.version_choice_menu.set(next((value for value in values if value.startswith(f"v{APP_VERSION}")), values[0]))
        self.version_launch_button.configure(state="normal")
        older_count = sum(1 for version in selectable if version_key(version) < version_key(APP_VERSION))
        self.version_manager_status_label.configure(
            text=f"이전 버전 {older_count}개를 불러왔습니다. 사용할 버전을 선택해 주세요."
        )

    def _handle_version_catalog_error(self, message: str) -> None:
        if hasattr(self, "version_manager_status_label"):
            self.version_manager_status_label.configure(
                text=f"버전 목록을 불러오지 못했습니다. 인터넷 연결을 확인해 주세요.\n{message}",
                text_color="#e05252",
            )
        if hasattr(self, "version_launch_button"):
            self.version_launch_button.configure(state="normal", text="목록 다시 불러오기")

    def _selected_temporary_version(self) -> str:
        if not hasattr(self, "version_choice_menu"):
            return ""
        match = re.search(r"v(\d+(?:\.\d+){1,3})", self.version_choice_menu.get())
        return match.group(1) if match else ""

    def _start_temporary_version(self) -> None:
        if not self.version_catalog:
            self._load_version_catalog(force=True)
            return
        version = self._selected_temporary_version()
        if not version:
            messagebox.showwarning("버전 선택", "임시로 실행할 버전을 선택해 주세요.", parent=self)
            return
        if version == APP_VERSION and not self.temporary_version_mode:
            messagebox.showinfo(
                "현재 버전 사용 중",
                f"현재 이미 v{APP_VERSION} 버전을 사용하고 있습니다.",
                parent=self,
            )
            return
        payload = dict(self.version_catalog.get(version) or {})
        if not payload:
            self._load_version_catalog(force=True)
            return
        if not messagebox.askyesno(
            "이전 버전 임시 실행",
            (
                f"v{version} 버전을 임시로 실행할까요?\n\n"
                f"• 최신 설치본 v{APP_VERSION}은 그대로 보관됩니다.\n"
                "• 임시 버전에서는 자동 업데이트가 실행되지 않습니다.\n"
                "• 임시 버전을 종료한 뒤 기존 Blog Helper를 다시 열면 최신 버전으로 돌아옵니다."
            ),
            parent=self,
        ):
            return
        self.pending_version_payload = payload
        cached_target = archived_version_target(DATA_DIR / "Version Archives", version)
        if cached_target.exists():
            self._launch_temporary_version(cached_target, version)
            return

        self.version_launch_button.configure(state="disabled", text="다운로드 중...")
        self.version_download_progress.set(0)
        self.version_manager_status_label.configure(
            text=f"v{version} 전체 실행파일을 처음 한 번만 다운로드합니다."
        )
        self.version_archive_download_worker = UpdateDownloadWorker(
            self.result_queue,
            payload,
            DATA_DIR / "Version Downloads",
            progress_event="version_archive_progress",
            success_event="version_archive_downloaded",
            error_event="version_archive_error",
        )
        self.version_archive_download_worker.start()

    def _handle_version_archive_progress(self, payload: dict) -> None:
        downloaded = int(payload.get("downloaded") or 0)
        total = int(payload.get("total") or 0)
        ratio = min(1.0, downloaded / total) if total else 0.0
        if total:
            self.version_download_progress.configure(mode="determinate")
            self.version_download_progress.set(ratio)
            self.version_manager_status_label.configure(
                text=(
                    f"v{payload.get('version', '')} 다운로드 {int(ratio * 100)}%\n"
                    f"{downloaded / (1024 * 1024):.1f}MB / {total / (1024 * 1024):.1f}MB"
                )
            )
        else:
            self.version_download_progress.configure(mode="indeterminate")
            self.version_download_progress.start()

    def _handle_version_archive_downloaded(self, payload: dict) -> None:
        self.version_download_progress.stop()
        self.version_download_progress.configure(mode="determinate")
        self.version_download_progress.set(1)
        self.version_manager_status_label.configure(text="다운로드 완료. 임시 실행파일을 준비하고 있습니다...")
        self.version_archive_prepare_worker = ArchivedVersionPrepareWorker(
            self.result_queue,
            payload,
            DATA_DIR / "Version Archives",
        )
        self.version_archive_prepare_worker.start()

    def _handle_version_archive_ready(self, payload: dict) -> None:
        local_path = Path(str(payload.get("local_path") or ""))
        try:
            local_path.unlink(missing_ok=True)
        except OSError:
            pass
        self._launch_temporary_version(
            Path(str(payload.get("archive_target") or "")),
            str(payload.get("version") or ""),
        )

    def _handle_version_archive_error(self, message: str) -> None:
        self.version_download_progress.stop()
        self.version_download_progress.configure(mode="determinate", progress_color="#e05252")
        self.version_download_progress.set(0)
        self.version_launch_button.configure(state="normal", text="선택 버전 임시 실행")
        self.version_manager_status_label.configure(
            text=f"임시 버전을 준비하지 못했습니다.\n{message}",
            text_color="#e05252",
        )

    def _launch_temporary_version(self, target: Path, version: str) -> None:
        try:
            launch_archived_version(target, version)
        except Exception as exc:
            self._handle_version_archive_error(str(exc))
            return
        self.version_manager_status_label.configure(
            text=f"v{version} 임시 버전을 실행했습니다. 현재 창을 종료합니다.",
            text_color="#48d980",
        )
        self.version_launch_button.configure(text="임시 버전 실행 완료")
        self.after(700, self._on_app_close)

    def _save_remote_agent_settings(self) -> None:
        pairing_password = self.remote_pairing_password_entry.get().strip()
        config = RemoteAgentConfig(
            enabled=bool(self.remote_enabled_var.get()),
            gateway_url=self.remote_gateway_entry.get(),
            device_id=self.remote_agent_config.device_id,
            device_name=self.remote_device_name_entry.get(),
            agent_token="" if pairing_password else self.remote_agent_config.agent_token,
            pairing_password=pairing_password,
        ).normalized()
        self.remote_agent_config = config
        self.remote_agent_store.save(config)
        self._restart_remote_agent()

    def _start_remote_agent_if_enabled(self) -> None:
        if not self.remote_agent_config.enabled:
            self._handle_remote_agent_status("disabled", "원격 제어가 꺼져 있습니다.")
            return
        if not self.remote_agent_config.agent_token and not self.remote_agent_config.pairing_password:
            pairing_password = simpledialog.askstring(
                "원격 PC 연결",
                (
                    "이 PC를 원격 웹의 작업 PC 목록에 연결합니다.\n\n"
                    "ai.lhksoul.com의 관리 비밀번호를 한 번만 입력해 주세요.\n"
                    "연결 후에는 이 PC 전용 인증키가 저장되어 다시 입력하지 않아도 됩니다."
                ),
                parent=self,
                show="*",
            )
            if not pairing_password:
                self.remote_agent_config.enabled = False
                self.remote_agent_store.save(self.remote_agent_config)
                self._handle_remote_agent_status(
                    "disabled",
                    "원격 연결이 보류되었습니다. 환경설정에서 언제든 연결할 수 있습니다.",
                )
                return
            self.remote_agent_config.pairing_password = pairing_password.strip()
            self.remote_agent_store.save(self.remote_agent_config)
        self._restart_remote_agent()

    def _restart_remote_agent(self) -> None:
        if self.remote_agent is not None:
            self.remote_agent.stop()
        self.remote_agent = RemoteControlAgent(
            config=self.remote_agent_config,
            app_version=APP_VERSION,
            on_job=lambda payload: self.result_queue.put(("remote_job_received", payload)),
            on_status=lambda status, message: self.result_queue.put(
                ("remote_agent_status", {"status": status, "message": message})
            ),
            on_credentials=lambda token: self.result_queue.put(("remote_agent_credentials", token)),
            on_command=lambda payload: self.result_queue.put(("remote_queue_command", payload)),
        )
        self.remote_agent.start()

    def _handle_remote_agent_credentials(self, token: str) -> None:
        token = str(token or "").strip()
        if not token:
            return
        self.remote_agent_config.agent_token = token
        self.remote_agent_config.pairing_password = ""
        self.remote_agent_config.enabled = True
        self.remote_agent_store.save(self.remote_agent_config)
        if hasattr(self, "remote_pairing_password_entry"):
            self.remote_pairing_password_entry.delete(0, "end")

    def _handle_remote_agent_status(self, status: str, message: str) -> None:
        if status == "online":
            self._send_remote_queue_snapshot(force=True)
        if not hasattr(self, "remote_agent_status_label"):
            return
        color_map = {
            "online": "#48d980",
            "connecting": "#6dadff",
            "offline": "#ffcc66",
            "disabled": "#9aa7bb",
            "error": "#ff6b6b",
        }
        self.remote_agent_status_label.configure(
            text=message,
            text_color=color_map.get(status, "#9aa7bb"),
        )

    def _build_remote_queue_snapshot(self) -> list[dict]:
        snapshot: list[dict] = []
        for item in list(getattr(self, "automation_queue", []))[-30:]:
            try:
                scheduled_at = float(item.get("scheduled_at") or 0)
            except (TypeError, ValueError):
                scheduled_at = 0.0
            article_html = str(item.get("article_html") or "").strip()
            safe_html = re.sub(
                r"<(script|style|iframe|object|embed|form|meta|link)\b[^>]*>.*?</\1\s*>",
                "",
                article_html,
                flags=re.IGNORECASE | re.DOTALL,
            )
            safe_html = re.sub(
                r"<(script|style|iframe|object|embed|form|meta|link)\b[^>]*/?>",
                "",
                safe_html,
                flags=re.IGNORECASE,
            )
            safe_html = re.sub(
                r"<img\b[^>]*>",
                "<p><em>본문 이미지가 포함되어 있습니다.</em></p>",
                safe_html,
                flags=re.IGNORECASE,
            )
            safe_html = re.sub(
                r"\s+on[a-z]+\s*=\s*([\"']).*?\1",
                "",
                safe_html,
                flags=re.IGNORECASE | re.DOTALL,
            )
            safe_html = re.sub(
                r"(href|src)\s*=\s*([\"'])\s*javascript:.*?\2",
                r'\1="#"',
                safe_html,
                flags=re.IGNORECASE | re.DOTALL,
            )
            # WebSocket 메시지가 과도하게 커지지 않도록 원격 미리보기만 적당한 길이로 제한합니다.
            safe_html = safe_html[:8_000]
            plain_text = re.sub(r"<[^>]+>", " ", safe_html)
            plain_text = re.sub(r"\s+", " ", unescape(plain_text)).strip()
            cardnews_paths = item.get("cardnews_image_paths") or item.get("cardnews_paths") or []
            snapshot.append(
                {
                    "id": str(item.get("id") or ""),
                    "title": str(item.get("title") or item.get("keyword") or "제목 없는 글")[:300],
                    "keyword": str(item.get("keyword") or "")[:300],
                    "status": str(item.get("status") or "대기 중")[:60],
                    "scheduledAt": scheduled_at,
                    "createdAt": str(item.get("created_at") or "")[:40],
                    "targetPlatforms": list(item.get("target_platforms") or []),
                    "articleHtml": safe_html,
                    "excerpt": plain_text[:280],
                    "hasThumbnail": bool(str(item.get("thumbnail_path") or "").strip()),
                    "cardnewsCount": len(cardnews_paths),
                }
            )
        return snapshot

    def _send_remote_queue_snapshot(self, force: bool = False) -> None:
        agent = getattr(self, "remote_agent", None)
        if agent is None:
            return
        items = self._build_remote_queue_snapshot()
        signature = tuple(
            (
                item["id"],
                item["title"],
                item["status"],
                item["scheduledAt"],
                tuple(item["targetPlatforms"]),
                hash(item["articleHtml"]),
            )
            for item in items
        )
        if not force and signature == self._last_remote_queue_snapshot_signature:
            return
        self._last_remote_queue_snapshot_signature = signature
        agent.send_queue_snapshot(items)

    def _handle_remote_queue_command(self, payload: dict) -> None:
        agent = getattr(self, "remote_agent", None)
        if agent is None:
            return
        command_type = str(payload.get("type") or "")
        command_id = str(payload.get("commandId") or "")
        item_id = str(payload.get("itemId") or "")
        try:
            if command_type == "queue.request":
                self._send_remote_queue_snapshot(force=True)
                agent.command_result(command_id, True, "대기열을 새로 불러왔습니다.")
                return

            item = self._find_automation_queue_item(item_id)
            if not item:
                raise RuntimeError("선택한 대기열 글을 PC에서 찾지 못했습니다.")

            if command_type == "queue.schedule.update":
                if str(item.get("status") or "") == "업로드 중":
                    raise RuntimeError("현재 발행 중인 글의 예정시간은 변경할 수 없습니다.")
                scheduled_at = float(payload.get("scheduledAt") or 0)
                if not scheduled_at or scheduled_at <= 0:
                    raise RuntimeError("올바른 등록 예정시간을 입력해 주세요.")
                item["scheduled_at"] = scheduled_at
                item["status"] = "대기 중"
                self._save_automation_queue()
                self._refresh_automation_queue()
                agent.command_result(command_id, True, "등록 예정시간을 변경했습니다.")
                return

            if command_type == "queue.publish.now":
                started = self._publish_next_automation_queue_item(
                    scheduled=False,
                    item_id=item_id,
                )
                agent.command_result(
                    command_id,
                    started,
                    "즉시발행을 시작했습니다." if started else "현재 즉시발행을 시작할 수 없습니다.",
                )
                return

            raise RuntimeError("지원하지 않는 원격 대기열 명령입니다.")
        except (RuntimeError, TypeError, ValueError) as exc:
            agent.command_result(command_id, False, str(exc))
            self._send_remote_queue_snapshot(force=True)

    def _start_remote_keyword_job(self, payload: dict) -> None:
        job_id = str(payload.get("id") or "").strip()
        keyword = str(payload.get("keyword") or "").strip()
        if not job_id or not keyword or self.remote_agent is None:
            return
        busy_workers = (
            self.remote_keyword_worker,
            self.article_worker,
            self.pipeline_worker,
            self.automation_keyword_worker,
        )
        if any(worker and worker.is_alive() for worker in busy_workers):
            self.remote_agent.fail(job_id, "이 PC에서 다른 글 작성 작업이 진행 중입니다.")
            return
        settings = self._read_wordpress_settings(include_prompts=True)
        settings.target_platforms = list(payload.get("targets") or ["wordpress"])
        settings.automation_target_platforms = list(settings.target_platforms)
        self.remote_active_job_id = job_id
        self.remote_agent.accept_job(job_id, f"'{keyword}' 원격 글 작성을 시작합니다.")
        self.remote_keyword_worker = RemoteKeywordQueueWorker(settings, payload, self.result_queue)
        self.remote_keyword_worker.start()

    def _handle_remote_job_generated(self, payload: dict) -> None:
        job_id = str(payload.get("remote_job_id") or self.remote_active_job_id).strip()
        if self.remote_agent is None or not job_id:
            return
        self.remote_agent.progress(job_id, 0.82, "글 작성이 끝나 썸네일과 카드뉴스를 준비하고 있습니다.")
        before_count = len(self.automation_queue)
        added = self._handle_automation_keyword_item_collected(payload)
        if not added or len(self.automation_queue) <= before_count:
            self.remote_agent.fail(job_id, "완성된 글을 자동화 대기열에 추가하지 못했습니다.")
        else:
            item = self.automation_queue[-1]
            if str(payload.get("remote_action") or "queue") == "publish":
                self.remote_agent.progress(job_id, 0.9, "글과 이미지를 완성했습니다. 지금 바로 블로그 발행을 시작합니다.")
                started = self._publish_next_automation_queue_item(
                    scheduled=False,
                    item_id=str(item.get("id") or ""),
                )
                if not started:
                    self.remote_agent.fail(job_id, "글은 준비했지만 즉시발행을 시작하지 못했습니다. PC의 블로그 연결 설정을 확인해 주세요.")
            else:
                self.remote_agent.complete(
                    job_id,
                    {
                        "queueId": item.get("id"),
                        "title": item.get("title"),
                        "status": item.get("status"),
                    },
                    "글, 썸네일, 카드뉴스를 완성해 자동화 대기열에 추가했습니다.",
                )
        self.remote_active_job_id = ""
        self.remote_keyword_worker = None

