    def _build_menu_settings_card(self) -> None:
        card = ctk.CTkFrame(
            self.theme_scroll,
            fg_color="#222c3b",
            corner_radius=28,
            border_width=1,
            border_color="#334760",
        )
        card.grid(row=1, column=0, pady=(18, 0), sticky="ew")
        card.grid_columnconfigure(1, weight=1)

        ctk.CTkLabel(
            card,
            text="메뉴 설정",
            font=ctk.CTkFont(size=26, weight="bold"),
            text_color="#6dadff",
        ).grid(row=0, column=0, columnspan=2, padx=28, pady=(28, 8), sticky="w")
        ctk.CTkLabel(
            card,
            text=(
                "사이드 메뉴에 표시할 이름을 수정할 수 있습니다. 이모지도 그대로 저장됩니다.\n"
                "예: ✍️ 블로그글쓰기 · ⚙️ 환경설정"
            ),
            text_color="#a7b3c4",
            font=ctk.CTkFont(size=14),
            justify="left",
        ).grid(row=1, column=0, columnspan=2, padx=28, pady=(0, 20), sticky="w")

        saved_labels = normalize_sidebar_menu_labels(
            self.wordpress_settings.sidebar_menu_labels
        )
        self.sidebar_menu_label_vars: dict[str, tk.StringVar] = {}
        for row, (page_name, default_label) in enumerate(
            SIDEBAR_MENU_DEFAULT_LABELS.items(),
            start=2,
        ):
            ctk.CTkLabel(
                card,
                text=default_label,
                text_color="#cbd6e6",
                font=ctk.CTkFont(size=15, weight="bold"),
            ).grid(
                row=row,
                column=0,
                padx=(28, 16),
                pady=(0, 12),
                sticky="w",
            )
            label_var = tk.StringVar(value=saved_labels[page_name])
            self.sidebar_menu_label_vars[page_name] = label_var
            entry = ctk.CTkEntry(
                card,
                textvariable=label_var,
                height=42,
                corner_radius=14,
                fg_color="#0b1220",
                border_color="#334760",
                text_color="#e6edf7",
                font=ctk.CTkFont(size=15, weight="bold"),
            )
            entry.grid(
                row=row,
                column=1,
                padx=(0, 28),
                pady=(0, 12),
                sticky="ew",
            )
            entry.bind("<KeyRelease>", self._on_sidebar_menu_label_changed)

        action_row = len(SIDEBAR_MENU_DEFAULT_LABELS) + 2
        button_frame = ctk.CTkFrame(card, fg_color="transparent")
        button_frame.grid(
            row=action_row,
            column=0,
            columnspan=2,
            padx=28,
            pady=(4, 10),
            sticky="ew",
        )
        button_frame.grid_columnconfigure(0, weight=1)
        ctk.CTkButton(
            button_frame,
            text="기본값 복원",
            width=120,
            height=40,
            fg_color="#596579",
            hover_color="#6a768b",
            command=self._reset_sidebar_menu_labels,
        ).grid(row=0, column=0, sticky="w")
        ctk.CTkButton(
            button_frame,
            text="저장하기",
            width=110,
            height=40,
            fg_color="#3468e8",
            hover_color="#2d5cd0",
            command=self._save_sidebar_menu_labels,
        ).grid(row=0, column=1, sticky="e")

        self.sidebar_menu_settings_status_label = ctk.CTkLabel(
            card,
            text="입력한 이름은 사이드 메뉴에 즉시 반영되고 자동 저장됩니다.",
            text_color="#9aa7bb",
            font=ctk.CTkFont(size=13, weight="bold"),
        )
        self.sidebar_menu_settings_status_label.grid(
            row=action_row + 1,
            column=0,
            columnspan=2,
            padx=28,
            pady=(0, 28),
            sticky="w",
        )

    def _current_sidebar_menu_labels(self) -> dict[str, str]:
        if not hasattr(self, "sidebar_menu_label_vars"):
            return normalize_sidebar_menu_labels(
                self.wordpress_settings.sidebar_menu_labels
            )
        return normalize_sidebar_menu_labels(
            {
                page_name: label_var.get()
                for page_name, label_var in self.sidebar_menu_label_vars.items()
            }
        )

    def _apply_sidebar_menu_labels(self, labels: object | None = None) -> None:
        normalized = normalize_sidebar_menu_labels(
            labels
            if labels is not None
            else self.wordpress_settings.sidebar_menu_labels
        )
        button_names = {
            "writing": "writing_nav_button",
            "automation": "automation_nav_button",
            "naver_blog": "naver_blog_nav_button",
            "naver_kin": "naver_kin_nav_button",
            "public_data": "public_data_nav_button",
            "prompts": "prompt_nav_button",
            "settings": "settings_nav_button",
        }
        for page_name, button_name in button_names.items():
            button = getattr(self, button_name, None)
            if button is not None:
                button.configure(text=normalized[page_name])

    def _on_sidebar_menu_label_changed(self, event=None) -> None:
        self._mark_text_input_activity(event)
        labels = self._current_sidebar_menu_labels()
        self._apply_sidebar_menu_labels(labels)
        if hasattr(self, "sidebar_menu_settings_status_label"):
            self.sidebar_menu_settings_status_label.configure(
                text="입력 중... 잠시 후 자동 저장됩니다.",
                text_color="#6dadff",
            )
        if self._sidebar_menu_label_save_job is not None:
            self.after_cancel(self._sidebar_menu_label_save_job)
        self._sidebar_menu_label_save_job = self.after(
            700,
            lambda: self._save_sidebar_menu_labels(silent=True),
        )

    def _save_sidebar_menu_labels(self, silent: bool = False) -> None:
        if self._sidebar_menu_label_save_job is not None:
            self.after_cancel(self._sidebar_menu_label_save_job)
            self._sidebar_menu_label_save_job = None
        labels = self._current_sidebar_menu_labels()
        self.wordpress_settings.sidebar_menu_labels = labels
        if hasattr(self, "sidebar_menu_label_vars"):
            for page_name, label_var in self.sidebar_menu_label_vars.items():
                if label_var.get() != labels[page_name]:
                    label_var.set(labels[page_name])
        self._apply_sidebar_menu_labels(labels)
        AppStateStore.save(self.wordpress_settings, save_secrets=False)
        if hasattr(self, "sidebar_menu_settings_status_label"):
            self.sidebar_menu_settings_status_label.configure(
                text="메뉴 이름 자동 저장됨" if silent else "메뉴 이름 저장 완료",
                text_color="#48d980",
            )
        if not silent:
            self._update_quick_status(
                "메뉴 설정 저장됨",
                "이모지를 포함한 사이드 메뉴 이름을 저장했습니다.",
                "#48d980",
            )

    def _reset_sidebar_menu_labels(self) -> None:
        defaults = dict(SIDEBAR_MENU_DEFAULT_LABELS)
        if hasattr(self, "sidebar_menu_label_vars"):
            for page_name, label_var in self.sidebar_menu_label_vars.items():
                label_var.set(defaults[page_name])
        self.wordpress_settings.sidebar_menu_labels = defaults
        self._save_sidebar_menu_labels()

    def _save_basic_settings(self, silent: bool = False) -> None:
        if getattr(self, "_app_title_save_job", None) is not None:
            self.after_cancel(self._app_title_save_job)
            self._app_title_save_job = None
        title = self.app_title_var.get().strip() if hasattr(self, "app_title_var") else ""
        if not title and hasattr(self, "app_title_entry"):
            title = self.app_title_entry.get().strip()
        title = title or "현기쿠"
        if hasattr(self, "app_title_var") and self.app_title_var.get() != title:
            self.app_title_var.set(title)
        self.wordpress_settings.app_title = title
        if hasattr(self, "default_writing_model_var"):
            self.wordpress_settings.preferred_ai_provider = normalize_writing_model(
                self.default_writing_model_var.get()
            )
            if self.wordpress_settings.preferred_ai_provider == WRITING_MODEL_CODEX:
                self.wordpress_settings.codex_cli_enabled = True
        if hasattr(self, "ai_provider_menu"):
            self.ai_provider_menu.set(
                writing_model_label(self.wordpress_settings.preferred_ai_provider)
            )
        if hasattr(self, "app_title_display_label"):
            self.app_title_display_label.configure(text=title)
        if hasattr(self, "sidebar_title"):
            self.sidebar_title.configure(text=title)
        AppStateStore.save(self.wordpress_settings, save_secrets=False)
        if hasattr(self, "basic_settings_status_label"):
            self.basic_settings_status_label.configure(
                text="기본설정 자동 저장됨" if silent else "기본설정 저장 완료",
                text_color="#48d980",
            )
        if not silent:
            self._update_quick_status("기본설정 저장됨", f"타이틀명: {title}", "#48d980")
            self._finish_theme_paint()

    def _on_default_writing_model_changed(self, model_name: str) -> None:
        provider = normalize_writing_model(model_name)
        self.wordpress_settings.preferred_ai_provider = provider
        if provider == WRITING_MODEL_CODEX:
            self.wordpress_settings.codex_cli_enabled = True
            if hasattr(self, "codex_cli_enabled_var"):
                self.codex_cli_enabled_var.set(True)
        if hasattr(self, "ai_provider_menu"):
            self.ai_provider_menu.set(writing_model_label(provider))
        if hasattr(self, "default_writing_model_help_label"):
            help_text = {
                WRITING_MODEL_CODEX: "CLI는 Codex 로그인 상태를 사용하므로 GPT API 토큰을 사용하지 않습니다. 블로그글쓰기, 블로그자동화, 원격글쓰기에 공통 적용됩니다.",
                WRITING_MODEL_GPT: "GPT API 키와 선택한 GPT 모델을 사용합니다. 블로그글쓰기, 블로그자동화, 원격글쓰기에 공통 적용됩니다.",
                WRITING_MODEL_GEMINI: "제미나이 API 키와 선택한 제미나이 모델을 사용합니다. 블로그글쓰기, 블로그자동화, 원격글쓰기에 공통 적용됩니다.",
            }[provider]
            self.default_writing_model_help_label.configure(text=help_text)
        self._save_basic_settings(silent=True)

    def _edit_app_title_dialog(self) -> None:
        current_title = self.app_title_var.get().strip() if hasattr(self, "app_title_var") else ""
        new_title = simpledialog.askstring(
            "타이틀명 수정",
            "왼쪽 상단에 표시할 타이틀명을 입력해 주세요.",
            initialvalue=current_title or "현기쿠",
            parent=self,
        )
        if new_title is None:
            return
        new_title = new_title.strip() or "현기쿠"
        self.app_title_var.set(new_title)
        self._save_basic_settings()

    def _on_app_title_typing(self, _event=None) -> None:
        title = self.app_title_var.get().strip() if hasattr(self, "app_title_var") else ""
        if hasattr(self, "sidebar_title"):
            self.sidebar_title.configure(text=title or "현기쿠")
        if hasattr(self, "basic_settings_status_label"):
            self.basic_settings_status_label.configure(text="입력 중... 잠시 후 자동 저장됩니다.", text_color="#6dadff")
        if getattr(self, "_app_title_save_job", None) is not None:
            self.after_cancel(self._app_title_save_job)
        self._app_title_save_job = self.after(700, lambda: self._save_basic_settings(silent=True))

    def _reset_basic_settings(self) -> None:
        if hasattr(self, "app_title_var"):
            self.app_title_var.set("현기쿠")
        if hasattr(self, "app_title_display_label"):
            self.app_title_display_label.configure(text="현기쿠")
        elif hasattr(self, "app_title_entry"):
            self.app_title_entry.delete(0, "end")
            self.app_title_entry.insert(0, "현기쿠")
        if hasattr(self, "default_writing_model_var"):
            self.default_writing_model_var.set("CLI")
        self.wordpress_settings.preferred_ai_provider = WRITING_MODEL_CODEX
        self.wordpress_settings.codex_cli_enabled = True
        if hasattr(self, "codex_cli_enabled_var"):
            self.codex_cli_enabled_var.set(True)
        self._save_basic_settings()

    def _build_writing_page(self) -> None:
        header = ctk.CTkFrame(self.writing_page, fg_color="transparent")
        header.grid(row=0, column=0, padx=28, pady=(26, 12), sticky="ew")
        header.grid_columnconfigure(0, weight=1)

        page_title = ctk.CTkLabel(
            header,
            text="블로그글쓰기",
            font=ctk.CTkFont(size=28, weight="bold"),
        )
        page_title.grid(row=0, column=0, sticky="w")

        auto_row = ctk.CTkFrame(header, fg_color="transparent")
        auto_row.grid(row=1, column=0, pady=(8, 0), sticky="w")

        self.writing_auto_progress_switch = ctk.CTkSwitch(
            auto_row,
            text="자동진행 OFF",
            variable=self.writing_auto_progress_var,
            onvalue=True,
            offvalue=False,
            switch_width=50,
            switch_height=26,
            corner_radius=13,
            progress_color="#1faa55",
            font=ctk.CTkFont(size=15, weight="bold"),
            command=self._on_writing_auto_progress_toggled,
        )
        self.writing_auto_progress_switch.grid(row=0, column=0, sticky="w")

        self.writing_auto_progress_status = ctk.CTkLabel(
            auto_row,
            text="1·2단계는 직접 선택하고 3·4단계를 자동 진행합니다.",
            text_color="#a7b3c4",
            font=ctk.CTkFont(size=13),
        )
        self.writing_auto_progress_status.grid(row=0, column=1, padx=(12, 0), sticky="w")

        target_row = ctk.CTkFrame(header, fg_color="transparent")
        target_row.grid(row=2, column=0, pady=(8, 0), sticky="w")
        ctk.CTkLabel(
            target_row,
            text="자동 발행 대상",
            font=ctk.CTkFont(size=14, weight="bold"),
        ).grid(row=0, column=0, padx=(0, 14), sticky="w")

        selected_targets = set(self.wordpress_settings.target_platforms or ["wordpress"])
        for index, (platform_key, label) in enumerate(
            [("wordpress", "워드프레스"), ("tistory", "티스토리")],
            start=1,
        ):
            variable = ctk.BooleanVar(value=platform_key in selected_targets)
            self.target_platform_vars[platform_key] = variable
            ctk.CTkCheckBox(
                target_row,
                text=label,
                variable=variable,
                onvalue=True,
                offvalue=False,
                checkbox_width=22,
                checkbox_height=22,
                corner_radius=6,
                font=ctk.CTkFont(size=14, weight="bold"),
                command=self._on_writing_target_changed,
            ).grid(row=0, column=index, padx=(0, 16), sticky="w")

        self._refresh_writing_auto_progress_ui()

        self.writing_scroll = ctk.CTkScrollableFrame(self.writing_page, fg_color="transparent")
        self.writing_scroll.grid(row=1, column=0, padx=28, pady=(0, 10), sticky="nsew")
        self.writing_scroll.grid_columnconfigure(0, weight=1)
        self._build_writing_workflow(self.writing_scroll)

        self._build_fixed_writing_progress_panel()

    def _build_fixed_writing_progress_panel(self) -> None:
        palette = self._theme_palette()
        panel = ctk.CTkFrame(
            self.writing_page,
            corner_radius=18,
            fg_color=palette["card"],
            border_width=1,
            border_color=palette["border"],
        )
        panel.grid(row=2, column=0, padx=28, pady=(0, 18), sticky="ew")
        panel.grid_columnconfigure(1, weight=1)

        self.writing_fixed_stage_badge = ctk.CTkLabel(
            panel,
            text="대기 중",
            width=76,
            height=28,
            corner_radius=10,
            fg_color=palette["button"],
            text_color=palette["text"],
            font=ctk.CTkFont(size=12, weight="bold"),
        )
        self.writing_fixed_stage_badge.grid(row=0, column=0, padx=(16, 12), pady=(12, 6), sticky="w")

        self.writing_fixed_message_label = ctk.CTkLabel(
            panel,
            text=self.writing_progress_message,
            anchor="w",
            justify="left",
            text_color=palette["text"],
            font=ctk.CTkFont(size=13, weight="bold"),
        )
        self.writing_fixed_message_label.grid(row=0, column=1, pady=(12, 6), sticky="ew")

        self.writing_fixed_percent_label = ctk.CTkLabel(
            panel,
            text="0%",
            width=48,
            anchor="e",
            text_color=palette["accent"],
            font=ctk.CTkFont(size=13, weight="bold"),
        )
        self.writing_fixed_percent_label.grid(row=0, column=2, padx=(10, 16), pady=(12, 6), sticky="e")

        stage_row = ctk.CTkFrame(panel, fg_color="transparent")
        stage_row.grid(row=1, column=0, columnspan=3, padx=16, pady=(0, 7), sticky="ew")
        stage_names = ("1 키워드 찾기", "2 참고 수집", "3 글 작성", "4 썸네일·발행")
        for index, stage_name in enumerate(stage_names, start=1):
            stage_row.grid_columnconfigure(index - 1, weight=1, uniform="writing_progress_stage")
            label = ctk.CTkLabel(
                stage_row,
                text=stage_name,
                height=26,
                corner_radius=9,
                fg_color=palette["input"],
                text_color=palette["muted"],
                font=ctk.CTkFont(size=11, weight="bold"),
            )
            label.grid(
                row=0,
                column=index - 1,
                padx=(0, 5) if index < len(stage_names) else 0,
                sticky="ew",
            )
            self.writing_fixed_stage_labels[index] = label

        self.writing_fixed_progress_bar = ctk.CTkProgressBar(
            panel,
            height=10,
            corner_radius=6,
            progress_color="#2f6fed",
        )
        self.writing_fixed_progress_bar.grid(
            row=2,
            column=0,
            columnspan=3,
            padx=16,
            pady=(0, 12),
            sticky="ew",
        )
        self._set_writing_progress(
            self.writing_progress_stage,
            self.writing_progress_message,
            self.writing_progress_fraction,
            state=self.writing_progress_state,
        )

    def _set_writing_progress(
        self,
        stage: int,
        message: str,
        stage_progress: float | None = None,
        *,
        state: str = "active",
    ) -> None:
        stage = max(1, min(4, int(stage)))
        if state == "complete":
            stage = 4
            fraction = 1.0
        elif stage_progress is None:
            if stage == getattr(self, "writing_progress_stage", stage):
                fraction = min(0.94, max(0.05, getattr(self, "writing_progress_fraction", 0.0) + 0.04))
            else:
                fraction = 0.05
        else:
            fraction = max(0.0, min(1.0, float(stage_progress)))

        self.writing_progress_stage = stage
        self.writing_progress_fraction = fraction
        self.writing_progress_message = str(message or "진행 상황을 확인하고 있습니다.").strip()
        self.writing_progress_state = state

        if state == "idle":
            overall_progress = 0.0
        elif state == "complete":
            overall_progress = 1.0
        else:
            overall_progress = ((stage - 1) + fraction) / 4

        if not hasattr(self, "writing_fixed_progress_bar"):
            return

        palette = self._theme_palette()
        is_white = self._normalize_app_theme(self.wordpress_settings.app_theme) == "화이트테마"
        active_bg = "#dbeafe" if is_white else "#1f4a78"
        active_text = "#1d4ed8" if is_white else "#9ac8ff"
        done_bg = "#dcfce7" if is_white else "#17422d"
        done_text = "#187a40" if is_white else "#66e39a"
        error_bg = "#fee2e2" if is_white else "#52252a"
        error_text = "#b42318" if is_white else "#ff8b8b"

        badge_text = "완료" if state == "complete" else ("오류" if state == "error" else f"{stage}단계")
        badge_bg = done_bg if state == "complete" else (error_bg if state == "error" else active_bg)
        badge_text_color = done_text if state == "complete" else (error_text if state == "error" else active_text)
        if state == "idle":
            badge_text = "대기 중"
            badge_bg = palette["button"]
            badge_text_color = palette["text"]

        self.writing_fixed_stage_badge.configure(
            text=badge_text,
            fg_color=badge_bg,
            text_color=badge_text_color,
        )
        self.writing_fixed_message_label.configure(
            text=self.writing_progress_message,
            text_color=error_text if state == "error" else palette["text"],
        )
        self.writing_fixed_percent_label.configure(
            text=f"{round(overall_progress * 100)}%",
            text_color=error_text if state == "error" else (done_text if state == "complete" else palette["accent"]),
        )
        self.writing_fixed_progress_bar.configure(
            progress_color="#e05252" if state == "error" else ("#1faa55" if state == "complete" else "#2f6fed")
        )
        self.writing_fixed_progress_bar.set(overall_progress)

        for index, label in self.writing_fixed_stage_labels.items():
            completed = state == "complete" or index < stage or (index == stage and fraction >= 1.0)
            active = index == stage and not completed and state != "idle"
            if completed:
                fg_color, text_color = done_bg, done_text
            elif active and state == "error":
                fg_color, text_color = error_bg, error_text
            elif active:
                fg_color, text_color = active_bg, active_text
            else:
                fg_color, text_color = palette["input"], palette["muted"]
            label.configure(fg_color=fg_color, text_color=text_color)

    def _refresh_writing_auto_progress_ui(self) -> None:
        if not hasattr(self, "writing_auto_progress_switch"):
            return
        enabled = bool(self.writing_auto_progress_var.get())
        self.writing_auto_progress_switch.configure(text=f"자동진행 {'ON' if enabled else 'OFF'}")
        if not hasattr(self, "writing_auto_progress_status"):
            return
        if self.writing_auto_run_active:
            stage_labels = {
                "keyword": "선택한 키워드의 참고내용을 수집하는 중입니다.",
                "article": "프롬프트에 따라 글을 작성하는 중입니다.",
                "publish": "썸네일·카드뉴스를 준비해 선택한 블로그에 발행하는 중입니다.",
            }
            text = stage_labels.get(self.writing_auto_stage, "자동진행을 준비하고 있습니다.")
            color = "#48d980"
        elif enabled:
            text = "1·2단계에서 키워드를 직접 선택하면 3·4단계를 자동 진행합니다."
            color = "#6dadff"
        else:
            text = "각 단계를 직접 확인하며 진행합니다."
            color = "#a7b3c4"
        self.writing_auto_progress_status.configure(text=text, text_color=color)

    def _on_writing_auto_progress_toggled(self) -> None:
        if not self.writing_auto_progress_var.get():
            self._stop_writing_auto_progress()
        self._refresh_writing_auto_progress_ui()
        self._save_ui_state()

    def _on_writing_target_changed(self) -> None:
        self._save_ui_state()
        self._refresh_writing_auto_progress_ui()

    def _selected_writing_targets(self) -> list[str]:
        return [platform for platform, variable in self.target_platform_vars.items() if variable.get()]

    def _arm_writing_auto_progress(self) -> bool:
        if not self.writing_auto_progress_var.get():
            self._stop_writing_auto_progress()
            return False
        if not self._selected_writing_targets():
            self._stop_writing_auto_progress()
            messagebox.showwarning("자동 발행 대상 필요", "워드프레스 또는 티스토리를 한 개 이상 선택해 주세요.")
            return False
        self.writing_auto_run_active = True
        self.writing_auto_stage = "keyword"
        self._refresh_writing_auto_progress_ui()
        return True

    def _stop_writing_auto_progress(self) -> None:
        self.writing_auto_run_active = False
        self.writing_auto_stage = ""
        self._refresh_writing_auto_progress_ui()

    def _auto_continue_after_reference(self, keyword: str = "") -> None:
        if not self.writing_auto_run_active or not self.writing_auto_progress_var.get():
            return
        selected_keyword = self._selected_or_manual_keyword()
        if keyword and selected_keyword and keyword.strip() != selected_keyword.strip():
            return
        if self.article_worker and self.article_worker.is_alive():
            return
        self.writing_auto_stage = "article"
        self._refresh_writing_auto_progress_ui()
        self._generate_article_from_selection()

    def _start_auto_progress_with_collected_reference(self, keyword: str, source_label: str) -> bool:
        """Continue at article generation when a data page already supplied references."""
        if not self.writing_auto_progress_var.get() or not self._arm_writing_auto_progress():
            return False
        self.keyword_status_label.configure(
            text=f"{source_label} 수집 완료 · 자동진행으로 글 작성을 시작합니다."
        )
        self._set_writing_progress(
            3,
            f"{source_label}를 바탕으로 글 작성을 자동 진행합니다.",
            0.0,
        )
        self.after(
            260,
            lambda current_keyword=keyword: self._auto_continue_after_reference(current_keyword),
        )
        return True

    def _auto_continue_after_article(self) -> None:
        if not self.writing_auto_run_active or not self.writing_auto_progress_var.get():
            return
        if not self._selected_writing_targets():
            self._stop_writing_auto_progress()
            return
        self.writing_auto_stage = "publish"
        self._refresh_writing_auto_progress_ui()
        self._go_to_thumbnail_section()
        self.after(450, self._auto_publish_current_article)

    def _auto_publish_current_article(self) -> None:
        if not self.writing_auto_run_active or not self.writing_auto_progress_var.get():
            return
        self._run_publish_pipeline()
        if not (self.pipeline_worker and self.pipeline_worker.is_alive()):
            self._stop_writing_auto_progress()

    def _is_widget_inside_scroll_frame(self, widget, scroll_frame: ctk.CTkScrollableFrame) -> bool:
        canvas = getattr(scroll_frame, "_parent_canvas", None)
        while widget is not None:
            if widget == canvas:
                return True
            widget = getattr(widget, "master", None)
        return False

    def _is_scroll_content_taller_than_view(self, scroll_frame: ctk.CTkScrollableFrame) -> bool:
        canvas = getattr(scroll_frame, "_parent_canvas", None)
        if canvas is None:
            return False
        try:
            if not canvas.winfo_exists():
                return False
            bbox = canvas.bbox("all")
            if not bbox:
                return False
            return (bbox[3] - bbox[1]) > canvas.winfo_height() + 2
        except tk.TclError:
            return False

    def _contain_child_scroll(self, parent: ctk.CTkScrollableFrame, child: ctk.CTkScrollableFrame) -> None:
        original_check = getattr(parent, "check_if_master_is_canvas", None)
        if not callable(original_check):
            return
        if not hasattr(parent, "_blog_helper_scroll_exclusions"):
            parent._blog_helper_scroll_exclusions = []
            parent._blog_helper_original_check_if_master_is_canvas = original_check

            def guarded_check(widget, scroll_parent=parent):
                for excluded_child in getattr(scroll_parent, "_blog_helper_scroll_exclusions", []):
                    if self._is_scroll_content_taller_than_view(excluded_child) and self._is_widget_inside_scroll_frame(widget, excluded_child):
                        return False
                original = getattr(scroll_parent, "_blog_helper_original_check_if_master_is_canvas", None)
                if callable(original):
                    return original(widget)
                return False

            parent.check_if_master_is_canvas = guarded_check

        if child not in parent._blog_helper_scroll_exclusions:
            parent._blog_helper_scroll_exclusions.append(child)
            self._scroll_exclusion_bindings.append((parent, child))

    def _bind_private_mousewheel_scroll(self, widget) -> None:
        def on_mousewheel(event):
            delta = getattr(event, "delta", 0)
            if delta:
                units = -int(delta / 120) if abs(delta) >= 120 else -int(delta)
                if units == 0:
                    units = -1 if delta > 0 else 1
            else:
                units = -1 if getattr(event, "num", 0) == 4 else 1
            try:
                widget.yview_scroll(units, "units")
            except Exception:
                pass
            return "break"

        targets = [widget]
        internal_textbox = getattr(widget, "_textbox", None)
        if internal_textbox is not None:
            targets.append(internal_textbox)
        for target in targets:
            target.bind("<MouseWheel>", on_mousewheel)
            target.bind("<Button-4>", on_mousewheel)
            target.bind("<Button-5>", on_mousewheel)

