    def _build_naver_kin_page(self) -> None:
        header = ctk.CTkFrame(self.naver_kin_page, fg_color="transparent")
        header.grid(row=0, column=0, padx=28, pady=(26, 12), sticky="ew")
        header.grid_columnconfigure(0, weight=1)

