    def _open_naver_blog_prompt_manager(self) -> None:
        selected_id = str(self.wordpress_settings.naver_blog_prompt_id or "")
        if selected_id:
            self.active_prompt_set_ids["naver_blog"] = selected_id
        self._switch_page("prompts")
        self._switch_prompt_platform("naver_blog")

    def _naver_blog_prompt_menu_values(self) -> list[str]:
        return self._prompt_set_menu_values("naver_blog")

    def _apply_naver_blog_prompt_set(self, prompt_set: dict, persist: bool = False) -> None:
        prompt_id = str(prompt_set.get("id") or "")
        prompt_name = str(prompt_set.get("name") or "기본")
        title_prompt = str(prompt_set.get("title_prompt") or DEFAULT_NAVER_BLOG_TITLE_PROMPT)
        article_prompt = str(prompt_set.get("article_prompt") or DEFAULT_NAVER_BLOG_TOPIC_PROMPT)
        self.wordpress_settings.naver_blog_prompt_id = prompt_id
        self.wordpress_settings.naver_blog_prompt_type = prompt_name
        self.wordpress_settings.naver_blog_title_prompt = title_prompt
        self.wordpress_settings.naver_blog_topic_prompt = article_prompt
        if hasattr(self, "naver_blog_prompt_type_menu"):
            self.naver_blog_prompt_type_menu.set(self._prompt_set_label(prompt_set))
        if hasattr(self, "active_prompt_set_ids"):
            self.active_prompt_set_ids["naver_blog"] = prompt_id
        if persist:
            PromptFileStore.save_values(
                {
                    "naver_blog_title_prompt": title_prompt,
                    "naver_blog_topic_prompt": article_prompt,
                }
            )
            AppStateStore.save(self.wordpress_settings, save_secrets=False)

    def _refresh_naver_blog_prompt_menu(self) -> None:
        if not hasattr(self, "naver_blog_prompt_type_menu"):
            return
        values = self._naver_blog_prompt_menu_values()
        self.naver_blog_prompt_type_menu.configure(values=values)
        selected = self._prompt_set_by_id(str(self.wordpress_settings.naver_blog_prompt_id or ""))
        if not selected or selected.get("platform") != "naver_blog":
            selected = next(
                (item for item in self._prompt_sets() if item.get("platform") == "naver_blog"),
                None,
            )
        if selected:
            self._apply_naver_blog_prompt_set(selected)
        else:
            self.naver_blog_prompt_type_menu.set(values[0])

    def _on_naver_blog_prompt_selected(self, label: str) -> None:
        selected = self._prompt_set_by_label(label, "naver_blog")
        if not selected:
            return
        self._apply_naver_blog_prompt_set(selected, persist=True)
        if hasattr(self, "naver_blog_status_label"):
            self.naver_blog_status_label.configure(
                text=f"현재 상태: {selected.get('name') or '기본'} 프롬프트 선택 완료",
                text_color="#48d980",
            )

    def _build_naver_blog_placeholder_tab(self, parent, title: str, description: str) -> None:
        panel = self._naver_panel(parent, title, 0)
        ctk.CTkLabel(
            panel,
            text=description,
            text_color="#cbd6e6",
            wraplength=760,
            justify="left",
            font=ctk.CTkFont(size=14),
        ).grid(row=1, column=0, columnspan=4, padx=18, pady=(0, 18), sticky="ew")

    def _switch_naver_blog_tab(self, tab_key: str) -> None:
        palette = self._theme_palette()
        self.active_naver_blog_tab = tab_key
        for key, button in self.naver_blog_tab_buttons.items():
            button.configure(
                fg_color=palette["selected"] if key == tab_key else palette["card"],
                hover_color=palette["hover"],
                text_color=palette["accent"] if key == tab_key else palette["text"],
            )
        for key, frame in self.naver_blog_tab_frames.items():
            if key == tab_key:
                frame.grid(row=0, column=0, sticky="ew")
                frame.tkraise()
            else:
                frame.grid_remove()
        try:
            canvas = getattr(self.naver_blog_scroll, "_parent_canvas", None)
            if canvas is not None:
                canvas.yview_moveto(0)
        except Exception:
            pass
        self._finish_theme_paint(force=True)

    def _naver_blog_profiles_from_state(self) -> list[dict]:
        return normalize_naver_blog_profiles(
            self.wordpress_settings.naver_blog_profiles
        )

    def _refresh_naver_profile_cards(self) -> None:
        if not hasattr(self, "naver_profile_cards_frame"):
            return
        for child in self.naver_profile_cards_frame.winfo_children():
            child.destroy()
        self.naver_blog_profile_vars = {}
        active_profile = self.wordpress_settings.naver_blog_active_profile or "블로그 1"
        self.naver_blog_active_profile_var = tk.StringVar(value=active_profile)
        profiles = self._naver_blog_profiles_from_state()
        for index, profile in enumerate(profiles):
            name = str(profile.get("name") or f"블로그 {index + 1}")
            card = ctk.CTkFrame(self.naver_profile_cards_frame, fg_color="#222c3b", corner_radius=16, border_width=1, border_color="#334760")
            card.grid(row=0, column=index, padx=(0 if index == 0 else 10, 0), sticky="nsew")
            card.grid_columnconfigure(1, weight=1)
            ctk.CTkRadioButton(
                card,
                text=name,
                variable=self.naver_blog_active_profile_var,
                value=name,
                command=lambda value=name: self._set_naver_active_profile(value),
                font=ctk.CTkFont(size=14, weight="bold"),
            ).grid(row=0, column=0, columnspan=2, padx=14, pady=(14, 8), sticky="w")
            for row, (field_key, label) in enumerate(
                [("blog_id", "ID"), ("nickname", "닉네임"), ("write_url", "글쓰기 URL")],
                start=1,
            ):
                ctk.CTkLabel(card, text=label, text_color="#aab7c8", font=ctk.CTkFont(size=12, weight="bold")).grid(row=row, column=0, padx=(14, 8), pady=4, sticky="w")
                var = tk.StringVar(value=str(profile.get(field_key) or ""))
                entry = ctk.CTkEntry(card, textvariable=var, height=30, fg_color="#111826", border_color="#314761")
                entry.grid(row=row, column=1, padx=(0, 14), pady=4, sticky="ew")
                entry.bind(
                    "<FocusOut>",
                    lambda _event, value=name: self._on_naver_profile_field_changed(value),
                )
                self.naver_blog_profile_vars[f"{index}:{field_key}"] = var
            ctk.CTkLabel(
                card,
                text="ID는 https://blog.naver.com/{ID} 의 ID 부분입니다.",
                text_color="#77869a",
                font=ctk.CTkFont(size=11),
            ).grid(row=4, column=0, columnspan=2, padx=14, pady=(6, 0), sticky="w")
            button_row = ctk.CTkFrame(card, fg_color="transparent")
            button_row.grid(row=5, column=0, columnspan=2, padx=14, pady=(10, 14), sticky="ew")
            button_row.grid_columnconfigure((0, 1, 2), weight=1)
            ctk.CTkButton(
                button_row,
                text="만들기/로그인",
                height=32,
                fg_color="#314761",
                command=lambda value=name: self._start_naver_blog_bootstrap(value),
            ).grid(row=0, column=0, padx=(0, 6), sticky="ew")
            ctk.CTkButton(
                button_row,
                text="프로필 확인",
                height=32,
                fg_color="#314761",
                command=lambda value=name: self._start_naver_blog_bootstrap(value),
            ).grid(row=0, column=1, padx=(0, 6), sticky="ew")
            ctk.CTkButton(button_row, text="초기화", height=32, fg_color="#596579", command=lambda idx=index: self._reset_naver_profile(idx)).grid(row=0, column=2, sticky="ew")
        self._sync_naver_blog_write_url_from_profile(active_profile, persist=False)
        self._finish_theme_paint()

    def _set_naver_active_profile(self, profile_name: str) -> None:
        write_url = self._sync_naver_blog_write_url_from_profile(profile_name, persist=True)
        if hasattr(self, "naver_blog_status_label"):
            url_status = write_url or "글쓰기 URL 미설정"
            self.naver_blog_status_label.configure(
                text=f"현재 상태: {profile_name} 선택 · {url_status}",
                text_color="#48d980" if write_url else "#ffb86b",
            )

    def _sync_naver_blog_write_url_from_profile(
        self,
        profile_name: str | None = None,
        persist: bool = True,
    ) -> str:
        profiles = self._current_naver_blog_profiles()
        if not profiles:
            return ""
        active_name = str(
            profile_name
            or (
                self.naver_blog_active_profile_var.get()
                if hasattr(self, "naver_blog_active_profile_var")
                else self.wordpress_settings.naver_blog_active_profile
            )
            or ""
        )
        selected_index = next(
            (
                index
                for index, profile in enumerate(profiles)
                if str(profile.get("name") or "") == active_name
            ),
            0,
        )
        selected = profiles[selected_index]
        active_name = str(selected.get("name") or f"블로그 {selected_index + 1}")
        write_url = resolved_naver_blog_profile_write_url(selected)
        selected["write_url"] = write_url

        self.wordpress_settings.naver_blog_profiles = profiles
        self.wordpress_settings.naver_blog_active_profile = active_name
        self.wordpress_settings.naver_blog_write_url = write_url
        if hasattr(self, "naver_blog_active_profile_var"):
            self.naver_blog_active_profile_var.set(active_name)
        profile_url_var = getattr(self, "naver_blog_profile_vars", {}).get(
            f"{selected_index}:write_url"
        )
        if profile_url_var is not None:
            profile_url_var.set(write_url)
        if hasattr(self, "naver_blog_write_url_entry"):
            current_url = self.naver_blog_write_url_entry.get().strip()
            if current_url != write_url:
                self.naver_blog_write_url_entry.delete(0, "end")
                self.naver_blog_write_url_entry.insert(0, write_url)
        if persist:
            AppStateStore.save(self.wordpress_settings, save_secrets=False)
        return write_url

    def _on_naver_profile_field_changed(self, profile_name: str) -> None:
        self.wordpress_settings.naver_blog_profiles = self._current_naver_blog_profiles()
        active_name = (
            self.naver_blog_active_profile_var.get()
            if hasattr(self, "naver_blog_active_profile_var")
            else self.wordpress_settings.naver_blog_active_profile
        )
        if profile_name == active_name:
            self._sync_naver_blog_write_url_from_profile(profile_name, persist=True)
            return
        AppStateStore.save(self.wordpress_settings, save_secrets=False)

    def _reset_naver_profile(self, index: int) -> None:
        profiles = self._naver_blog_profiles_from_state()
        if 0 <= index < len(profiles):
            name = str(profiles[index].get("name") or f"블로그 {index + 1}")
            profile_scope = NAVER_BLOG_PROFILE_SCOPES[index]
            profile_dir, _state_file = naver_playwright_profile_paths(profile_scope)
            profiles[index] = {
                "name": name,
                "blog_id": "",
                "nickname": "",
                "write_url": "",
                "profile_scope": profile_scope,
                "profile_path": str(profile_dir),
            }
            for field_key in ("blog_id", "nickname", "write_url"):
                var = getattr(self, "naver_blog_profile_vars", {}).get(
                    f"{index}:{field_key}"
                )
                if var is not None:
                    var.set("")
            self.wordpress_settings.naver_blog_profiles = profiles
            self._sync_naver_blog_write_url_from_profile(
                self.wordpress_settings.naver_blog_active_profile,
                persist=False,
            )
            AppStateStore.save(self.wordpress_settings, save_secrets=False)
            self._refresh_naver_profile_cards()
            self.naver_blog_status_label.configure(text=f"{name} 프로필 입력값을 초기화했습니다.", text_color="#ffcc66")

    def _current_naver_blog_profiles(self) -> list[dict]:
        profiles = self._naver_blog_profiles_from_state()
        if hasattr(self, "naver_blog_profile_vars"):
            for index, profile in enumerate(profiles):
                for field_key in ("blog_id", "nickname", "write_url"):
                    var = self.naver_blog_profile_vars.get(f"{index}:{field_key}")
                    if var is not None:
                        value = var.get().strip()
                        if field_key == "blog_id":
                            value = self._normalize_naver_blog_id(value)
                            var.set(value)
                        profile[field_key] = value
        return profiles

    def _normalize_naver_blog_id(self, value: str) -> str:
        return normalize_naver_blog_id(value)

    def _selected_naver_blog_profile(self) -> dict:
        profiles = self._current_naver_blog_profiles()
        active_name = (
            self.naver_blog_active_profile_var.get()
            if hasattr(self, "naver_blog_active_profile_var")
            else self.wordpress_settings.naver_blog_active_profile
        )
        return next((profile for profile in profiles if str(profile.get("name") or "") == active_name), profiles[0])

    def _naver_blog_manual_image_limit(self) -> int:
        if hasattr(self, "naver_blog_image_count_menu"):
            return max(
                1,
                min(
                    self._safe_int(
                        self.naver_blog_image_count_menu.get().replace("개", ""),
                        2,
                    ),
                    10,
                ),
            )
        return max(
            1,
            min(int(self.wordpress_settings.naver_blog_image_count or 2), 10),
        )

    def _current_naver_blog_manual_image_paths(self) -> list[str]:
        raw_paths = (
            self.naver_blog_manual_image_paths
            if hasattr(self, "naver_blog_manual_image_paths")
            else self.wordpress_settings.naver_blog_manual_image_paths
        )
        paths: list[str] = []
        seen: set[str] = set()
        for raw_path in raw_paths or []:
            path = str(raw_path or "").strip()
            if not path or path in seen:
                continue
            seen.add(path)
            paths.append(path)
        return paths[: self._naver_blog_manual_image_limit()]

    def _create_naver_blog_manual_thumbnail(
        self,
        image_path: str,
        size: int = 40,
    ) -> ctk.CTkImage | None:
        if Image is None or ImageOps is None:
            return None
        try:
            with Image.open(image_path) as source:
                transposed = ImageOps.exif_transpose(source)
                preview = ImageOps.fit(
                    transposed.convert("RGB"),
                    (size, size),
                    method=Image.Resampling.LANCZOS,
                )
                preview.load()
            return ctk.CTkImage(
                light_image=preview,
                dark_image=preview,
                size=(size, size),
            )
        except Exception:
            return None

    def _load_naver_blog_remove_icon(self) -> ctk.CTkImage | None:
        cached = getattr(self, "naver_blog_manual_remove_icon", None)
        if cached is not None:
            return cached
        if Image is None:
            return None
        try:
            with Image.open(
                io.BytesIO(base64.b64decode(NAVER_BLOG_REMOVE_ICON_PNG_BASE64))
            ) as source:
                icon_image = source.convert("RGBA").copy()
            cached = ctk.CTkImage(
                light_image=icon_image,
                dark_image=icon_image,
                size=(20, 20),
            )
            self.naver_blog_manual_remove_icon = cached
            return cached
        except Exception:
            return None

    def _render_naver_blog_manual_image_thumbnails(
        self,
        paths: list[str],
        enabled: bool,
    ) -> None:
        if not hasattr(self, "naver_blog_manual_thumbnail_frame"):
            return
        frame = self.naver_blog_manual_thumbnail_frame
        for child in frame.winfo_children():
            child.destroy()
        self.naver_blog_manual_thumbnail_images = []
        if not paths:
            ctk.CTkLabel(
                frame,
                text="이미지를 추가하면 여기에 미리보기가 표시됩니다.",
                text_color="#77869a",
                font=ctk.CTkFont(size=12),
            ).grid(row=0, column=0, columnspan=8, pady=8, sticky="w")
            return

        palette = self._theme_palette()
        remove_icon = self._load_naver_blog_remove_icon()
        for index, path in enumerate(paths):
            card = ctk.CTkFrame(
                frame,
                width=66,
                height=74,
                fg_color=palette["input"],
                corner_radius=12,
                border_width=1,
                border_color=palette["border"],
            )
            card.grid(
                row=index // 8,
                column=index % 8,
                padx=(0 if index % 8 == 0 else 6, 0),
                pady=(0, 6),
                sticky="n",
            )
            card.grid_propagate(False)
            thumbnail = self._create_naver_blog_manual_thumbnail(path)
            if thumbnail is not None:
                self.naver_blog_manual_thumbnail_images.append(thumbnail)
                preview_label = ctk.CTkLabel(
                    card,
                    text="",
                    image=thumbnail,
                    width=40,
                    height=40,
                )
            else:
                preview_label = ctk.CTkLabel(
                    card,
                    text="미리보기\n불가",
                    width=40,
                    height=40,
                    fg_color=palette["card"],
                    corner_radius=8,
                    text_color=palette["subtext"],
                    font=ctk.CTkFont(size=9, weight="bold"),
                )
            preview_label.place(x=13, y=6)
            filename = Path(path).name
            display_name = filename if len(filename) <= 10 else f"{filename[:7]}…"
            ctk.CTkLabel(
                card,
                text=display_name,
                text_color=palette["text"],
                font=ctk.CTkFont(size=9),
                width=58,
                anchor="center",
            ).place(x=4, y=51)
            remove_button_kwargs = {
                "text": "" if remove_icon is not None else "×",
                "width": 22,
                "height": 22,
                "corner_radius": 11,
                "fg_color": "transparent",
                "hover_color": palette["hover"],
                "font": ctk.CTkFont(size=14, weight="bold"),
                "state": "normal" if enabled else "disabled",
                "command": lambda selected_path=path: self._remove_naver_blog_manual_image(
                    selected_path
                ),
            }
            if remove_icon is not None:
                remove_button_kwargs["image"] = remove_icon
            ctk.CTkButton(card, **remove_button_kwargs).place(
                relx=1.0,
                x=-1,
                y=1,
                anchor="ne",
            )

    def _remove_naver_blog_manual_image(self, image_path: str) -> None:
        normalized_target = os.path.normcase(
            os.path.abspath(os.path.expanduser(str(image_path or "")))
        )
        self.naver_blog_manual_image_paths = [
            path
            for path in self._current_naver_blog_manual_image_paths()
            if os.path.normcase(os.path.abspath(os.path.expanduser(path)))
            != normalized_target
        ]
        self.wordpress_settings.naver_blog_manual_image_paths = list(
            self.naver_blog_manual_image_paths
        )
        self._refresh_naver_blog_manual_image_controls()
        self._save_naver_blog_settings(silent=True)

    def _refresh_naver_blog_manual_image_controls(self) -> None:
        image_mode = normalize_naver_blog_image_mode(
            self.naver_blog_image_mode_var.get()
            if hasattr(self, "naver_blog_image_mode_var")
            else self.wordpress_settings.naver_blog_image_mode
        )
        limit = self._naver_blog_manual_image_limit()
        paths = self._current_naver_blog_manual_image_paths()
        self.naver_blog_manual_image_paths = paths
        self.wordpress_settings.naver_blog_image_mode = image_mode
        self.wordpress_settings.naver_blog_manual_image_paths = list(paths)
        manual_enabled = image_mode == NAVER_BLOG_IMAGE_MODE_MANUAL
        remaining = max(0, limit - len(paths))
        if hasattr(self, "naver_blog_manual_image_button"):
            self.naver_blog_manual_image_button.configure(
                text=f"컴퓨터에서 이미지 추가 (남은 {remaining}장)",
                state="normal" if manual_enabled and remaining > 0 else "disabled",
            )
        if hasattr(self, "naver_blog_manual_image_clear_button"):
            self.naver_blog_manual_image_clear_button.configure(
                state="normal" if manual_enabled and paths else "disabled"
            )
        self._render_naver_blog_manual_image_thumbnails(paths, manual_enabled)
        if hasattr(self, "naver_blog_manual_image_summary_label"):
            missing_count = sum(1 for path in paths if not Path(path).is_file())
            summary = (
                f"선택 {len(paths)}/{limit}장 · 여러 번 나누어 추가할 수 있습니다."
            )
            if missing_count:
                summary += f" · 찾을 수 없는 파일 {missing_count}개"
            self.naver_blog_manual_image_summary_label.configure(
                text=summary,
                text_color="#a7b3c4" if manual_enabled else "#77869a",
            )
        if hasattr(self, "naver_blog_manual_image_limit_label"):
            self.naver_blog_manual_image_limit_label.configure(
                text=(
                    f"설정 탭의 첨부 이미지 수 기준으로 최대 {limit}장까지 선택할 수 있습니다. "
                    "사진을 여러 번 나누어 추가하거나 썸네일의 × 버튼으로 개별 삭제할 수 있습니다."
                )
            )

    def _on_naver_blog_image_mode_changed(self, value: str) -> None:
        self.wordpress_settings.naver_blog_image_mode = (
            normalize_naver_blog_image_mode(value)
        )
        self._refresh_naver_blog_manual_image_controls()
        self._save_naver_blog_settings(silent=True)

    def _on_naver_blog_image_count_changed(self, value: str) -> None:
        self.wordpress_settings.naver_blog_image_count = max(
            1,
            min(self._safe_int(str(value).replace("개", ""), 2), 10),
        )
        self._refresh_naver_blog_manual_image_controls()
        self._save_naver_blog_settings(silent=True)

    def _choose_naver_blog_manual_images(self) -> None:
        limit = self._naver_blog_manual_image_limit()
        existing_paths = self._current_naver_blog_manual_image_paths()
        remaining = max(0, limit - len(existing_paths))
        if remaining <= 0:
            messagebox.showinfo(
                "이미지 추가 완료",
                f"설정한 최대 이미지 수 {limit}장을 모두 선택했습니다.",
            )
            return
        selected_paths = list(
            filedialog.askopenfilenames(
                title=f"N블로그 이미지 추가 (현재 {len(existing_paths)}장 · 남은 {remaining}장)",
                filetypes=[
                    (
                        "이미지 파일",
                        "*.png *.jpg *.jpeg *.heic *.HEIC *.gif *.webp *.bmp",
                    ),
                    ("모든 파일", "*.*"),
                ],
            )
        )
        if not selected_paths:
            return
        unsupported = [
            Path(path).name
            for path in selected_paths
            if Path(path).suffix.lower() not in NAVER_BLOG_MANUAL_IMAGE_SUFFIXES
        ]
        if unsupported:
            messagebox.showwarning(
                "지원하지 않는 이미지",
                "PNG, JPG, JPEG, HEIC, GIF, WEBP, BMP 파일만 선택할 수 있습니다.\n\n"
                + "\n".join(unsupported),
            )
            return
        try:
            merged_paths = merge_naver_blog_manual_image_paths(
                existing_paths,
                selected_paths,
                limit,
            )
        except ValueError:
            messagebox.showwarning(
                "이미지 수 초과",
                f"현재 {len(existing_paths)}장이 선택되어 있어 {remaining}장만 더 추가할 수 있습니다.\n"
                f"{remaining}장 이하로 다시 선택해 주세요.",
            )
            return
        self.naver_blog_manual_image_paths = merged_paths
        self.wordpress_settings.naver_blog_manual_image_paths = list(
            self.naver_blog_manual_image_paths
        )
        self._refresh_naver_blog_manual_image_controls()
        self._save_naver_blog_settings(silent=True)

    def _clear_naver_blog_manual_images(self) -> None:
        self.naver_blog_manual_image_paths = []
        self.wordpress_settings.naver_blog_manual_image_paths = []
        self._refresh_naver_blog_manual_image_controls()
        self._save_naver_blog_settings(silent=True)

    def _choose_naver_blog_work_folder(self) -> None:
        folder = filedialog.askdirectory(title="네이버 블로그 작업 폴더 선택")
        if not folder:
            return
        self.naver_blog_work_folder_entry.delete(0, "end")
        self.naver_blog_work_folder_entry.insert(0, folder)
        self._save_naver_blog_settings(silent=True)

    def _on_naver_blog_automation_mode_changed(self, value: str) -> None:
        self.wordpress_settings.naver_blog_automation_mode = (
            normalize_naver_blog_automation_mode(value)
        )
        self._save_naver_blog_settings(silent=True)

    def _update_naver_blog_reference_count(self) -> None:
        if not hasattr(self, "naver_blog_reference_count_label"):
            return
        reference = (
            self.naver_blog_reference_textbox.get("1.0", "end").strip()
            if hasattr(self, "naver_blog_reference_textbox")
            else self.wordpress_settings.naver_blog_reference_text
        )
        self.naver_blog_reference_count_label.configure(
            text=(
                f"직접 입력 {len(reference):,}자 · 포털 자동 수집 내용과 합쳐서 글을 작성합니다."
                if reference
                else "비워두면 직접 입력 내용은 사용하지 않고 포털 자동 수집 내용으로 작성합니다."
            )
        )

    def _on_naver_blog_reference_text_changed(self, event=None) -> None:
        self._mark_text_input_activity(event)
        self.wordpress_settings.naver_blog_reference_text = (
            self.naver_blog_reference_textbox.get("1.0", "end").strip()
        )
        self._update_naver_blog_reference_count()
        self._save_ui_state()

    def _clear_naver_blog_reference_text(self) -> None:
        if not hasattr(self, "naver_blog_reference_textbox"):
            return
        self.naver_blog_reference_textbox.delete("1.0", "end")
        self.wordpress_settings.naver_blog_reference_text = ""
        self._update_naver_blog_reference_count()
        self._save_naver_blog_settings(silent=True)

    def _save_naver_blog_settings(self, silent: bool = False) -> None:
        profiles = self._current_naver_blog_profiles()
        self.wordpress_settings.naver_blog_profiles = profiles
        if hasattr(self, "naver_blog_active_profile_var"):
            self.wordpress_settings.naver_blog_active_profile = self.naver_blog_active_profile_var.get()
        if hasattr(self, "naver_blog_write_url_entry"):
            entry_url = self.naver_blog_write_url_entry.get().strip()
            selected_index = next(
                (
                    index
                    for index, profile in enumerate(profiles)
                    if str(profile.get("name") or "")
                    == self.wordpress_settings.naver_blog_active_profile
                ),
                None,
            )
            if selected_index is not None:
                selected = dict(profiles[selected_index])
                selected["write_url"] = entry_url
                entry_url = resolved_naver_blog_profile_write_url(selected)
                profiles[selected_index]["write_url"] = entry_url
                profile_url_var = getattr(self, "naver_blog_profile_vars", {}).get(
                    f"{selected_index}:write_url"
                )
                if profile_url_var is not None:
                    profile_url_var.set(entry_url)
            self.wordpress_settings.naver_blog_profiles = profiles
            self.wordpress_settings.naver_blog_write_url = entry_url
            if self.naver_blog_write_url_entry.get().strip() != entry_url:
                self.naver_blog_write_url_entry.delete(0, "end")
                self.naver_blog_write_url_entry.insert(0, entry_url)
        if hasattr(self, "naver_blog_publish_name_entry"):
            self.wordpress_settings.naver_blog_publish_name = self.naver_blog_publish_name_entry.get().strip()
        if hasattr(self, "naver_blog_body_delay_entry"):
            self.wordpress_settings.naver_blog_body_delay_ms = self._safe_int(self.naver_blog_body_delay_entry.get(), 20)
        if hasattr(self, "naver_blog_automation_mode_var"):
            self.wordpress_settings.naver_blog_automation_mode = (
                normalize_naver_blog_automation_mode(
                    self.naver_blog_automation_mode_var.get()
                )
            )
        if hasattr(self, "naver_blog_run_count_entry"):
            self.wordpress_settings.naver_blog_run_count = self._safe_int(self.naver_blog_run_count_entry.get(), 1)
        if hasattr(self, "naver_blog_image_count_menu"):
            self.wordpress_settings.naver_blog_image_count = max(
                1,
                min(self._safe_int(self.naver_blog_image_count_menu.get().replace("개", ""), 2), 10),
            )
        if hasattr(self, "naver_blog_image_mode_var"):
            self.wordpress_settings.naver_blog_image_mode = (
                normalize_naver_blog_image_mode(
                    self.naver_blog_image_mode_var.get()
                )
            )
        if hasattr(self, "naver_blog_manual_image_paths"):
            self.wordpress_settings.naver_blog_manual_image_paths = (
                self._current_naver_blog_manual_image_paths()
            )
            self._refresh_naver_blog_manual_image_controls()
        if hasattr(self, "naver_blog_work_folder_entry"):
            self.wordpress_settings.naver_blog_work_folder = self.naver_blog_work_folder_entry.get().strip()
        if hasattr(self, "naver_blog_prompt_type_menu"):
            selected = self._prompt_set_by_label(
                self.naver_blog_prompt_type_menu.get(),
                "naver_blog",
            )
            if selected:
                self._apply_naver_blog_prompt_set(selected)
        if hasattr(self, "naver_blog_topic_category_menu"):
            self.wordpress_settings.naver_blog_topic_category = self.naver_blog_topic_category_menu.get()
        if hasattr(self, "naver_blog_reference_textbox"):
            self.wordpress_settings.naver_blog_reference_text = (
                self.naver_blog_reference_textbox.get("1.0", "end").strip()
            )
            self._update_naver_blog_reference_count()
        if hasattr(self, "naver_blog_generation_model_entry"):
            self.wordpress_settings.naver_blog_generation_model = self.naver_blog_generation_model_entry.get().strip() or "[CLI] Codex"
        if hasattr(self, "naver_blog_image_model_entry"):
            self.wordpress_settings.naver_blog_image_model = self.naver_blog_image_model_entry.get().strip() or "[CLI IMG] Codex"
        if hasattr(self, "naver_blog_ai_generation_model_entry"):
            self.wordpress_settings.naver_blog_generation_model = self.naver_blog_ai_generation_model_entry.get().strip() or self.wordpress_settings.naver_blog_generation_model
        if hasattr(self, "naver_blog_ai_image_model_entry"):
            self.wordpress_settings.naver_blog_image_model = self.naver_blog_ai_image_model_entry.get().strip() or self.wordpress_settings.naver_blog_image_model
        if hasattr(self, "naver_blog_rules_box"):
            self.wordpress_settings.naver_blog_conversion_rules = (
                self.naver_blog_rules_box.get("1.0", "end").strip() or DEFAULT_NAVER_BLOG_CONVERSION_RULES
            )
            PromptFileStore.save_values({"naver_blog_conversion_rules": self.wordpress_settings.naver_blog_conversion_rules})
        AppStateStore.save(self.wordpress_settings, save_secrets=False)
        if not silent and hasattr(self, "naver_blog_status_label"):
            self.naver_blog_status_label.configure(text="현재 상태: 네이버 블로그 설정 저장 완료", text_color="#48d980")

    def _save_naver_blog_rules(self) -> None:
        try:
            value = (
                self.naver_blog_rules_box.get("1.0", "end").strip()
                if hasattr(self, "naver_blog_rules_box")
                else self.wordpress_settings.naver_blog_conversion_rules
            )
            value = value or DEFAULT_NAVER_BLOG_CONVERSION_RULES
            self.wordpress_settings.naver_blog_conversion_rules = value
            PromptFileStore.save_values({"naver_blog_conversion_rules": value})
            AppStateStore.save(self.wordpress_settings, save_secrets=False)
            if hasattr(self, "naver_blog_rules_feedback_label"):
                self.naver_blog_rules_feedback_label.configure(
                    text=f"TXT 저장 완료: {PROMPT_STORAGE_DIR / PromptFileStore.FILES['naver_blog_conversion_rules']}",
                    text_color="#48d980",
                )
            self._update_quick_status("N블로그 글변환 규칙 저장", "TXT 파일로 저장했습니다.", "#48d980")
        except Exception as exc:
            if hasattr(self, "naver_blog_rules_feedback_label"):
                self.naver_blog_rules_feedback_label.configure(text="TXT 저장 실패", text_color="#ff6b6b")
            messagebox.showerror("N블로그 규칙 저장 실패", str(exc))

    def _reset_naver_blog_automation_controls(
        self,
        status: str = "현재 상태: 대기 중",
        color: str = "#6dadff",
    ) -> None:
        if hasattr(self, "naver_blog_start_button"):
            self.naver_blog_start_button.configure(
                state="normal",
                text="🚀 자동화 시작 (Playwright)",
            )
        if hasattr(self, "naver_blog_stop_button"):
            self.naver_blog_stop_button.configure(state="disabled", text="자동화 중단")
        if hasattr(self, "naver_blog_status_label"):
            self.naver_blog_status_label.configure(text=status, text_color=color)

    def _stop_naver_blog_bootstrap(self) -> None:
        worker = self.naver_blog_worker
        if worker is None or not worker.is_alive():
            self.naver_blog_worker = None
            self._reset_naver_blog_automation_controls()
            return
        worker.cancel()
        if hasattr(self, "naver_blog_start_button"):
            self.naver_blog_start_button.configure(state="disabled", text="자동화 중단 처리 중...")
        if hasattr(self, "naver_blog_stop_button"):
            self.naver_blog_stop_button.configure(state="disabled", text="중단 중...")
        if hasattr(self, "naver_blog_status_label"):
            self.naver_blog_status_label.configure(
                text="현재 상태: 작업과 전용 Chrome을 안전하게 종료하는 중...",
                text_color="#ffb86b",
            )
        append_runtime_log("NBlog", "사용자가 자동화 중단 버튼을 눌렀습니다.")

    def _start_naver_blog_bootstrap(self, profile_name: str | None = None) -> None:
        if self.naver_blog_worker and self.naver_blog_worker.is_alive():
            messagebox.showinfo("진행 중", "네이버 블로그 자동화 준비가 이미 진행 중입니다.")
            return
        if profile_name and hasattr(self, "naver_blog_active_profile_var"):
            self._sync_naver_blog_write_url_from_profile(profile_name, persist=False)
        self._save_naver_blog_settings(silent=True)
        profile = self._selected_naver_blog_profile()
        blog_id = self._normalize_naver_blog_id(str(profile.get("blog_id") or ""))
        if not blog_id:
            messagebox.showwarning("블로그 ID 필요", "네이버 블로그 ID를 먼저 입력해 주세요.\n예: https://blog.naver.com/soullhk 에서 soullhk")
            return
        workflow_mode = profile_name is None
        topic = ""
        image_mode = normalize_naver_blog_image_mode(
            self.wordpress_settings.naver_blog_image_mode
        )
        manual_image_paths: list[str] = []
        if workflow_mode:
            topic = (
                self.naver_blog_publish_name_entry.get().strip()
                if hasattr(self, "naver_blog_publish_name_entry")
                else self.wordpress_settings.naver_blog_publish_name.strip()
            )
            if not topic:
                messagebox.showwarning("글 주제 필요", "글작성 탭의 '글 주제'를 먼저 입력해 주세요.")
                return
            validation_error = writing_model_validation_error(self.wordpress_settings)
            if validation_error:
                messagebox.showwarning("기본 작성 모델 설정 필요", validation_error)
                return
            if image_mode == NAVER_BLOG_IMAGE_MODE_MANUAL:
                manual_image_paths = self._current_naver_blog_manual_image_paths()
                missing_paths = [
                    path for path in manual_image_paths if not Path(path).is_file()
                ]
                if missing_paths:
                    messagebox.showwarning(
                        "수동 이미지 확인 필요",
                        "다음 이미지 파일을 찾을 수 없습니다. 다시 선택해 주세요.\n\n"
                        + "\n".join(Path(path).name for path in missing_paths),
                    )
                    return
                unsupported_paths = [
                    path
                    for path in manual_image_paths
                    if Path(path).suffix.lower()
                    not in NAVER_BLOG_MANUAL_IMAGE_SUFFIXES
                ]
                if unsupported_paths:
                    messagebox.showwarning(
                        "수동 이미지 확인 필요",
                        "지원하지 않는 이미지 형식입니다. 다시 선택해 주세요.\n\n"
                        + "\n".join(
                            Path(path).name for path in unsupported_paths
                        ),
                    )
                    return
        write_url = build_naver_blog_write_url(profile, self.wordpress_settings.naver_blog_write_url)
        profile_scope = naver_blog_profile_scope(profile)
        if hasattr(self, "naver_blog_start_button"):
            self.naver_blog_start_button.configure(
                state="disabled",
                text="자료 수집·글 작성 중..." if workflow_mode else "전용 Chrome 여는 중...",
            )
        if hasattr(self, "naver_blog_stop_button"):
            self.naver_blog_stop_button.configure(state="normal", text="자동화 중단")
        self.naver_blog_status_label.configure(
            text=(
                f"현재 상태: '{topic}' 최신 자료를 수집하는 중..."
                if workflow_mode
                else "현재 상태: 네이버 로그인창 여는 중..."
            ),
            text_color="#6dadff",
        )
        self.naver_blog_worker = NaverBlogBootstrapWorker(
            write_url,
            blog_id,
            self.result_queue,
            settings=self.wordpress_settings if workflow_mode else None,
            topic=topic,
            image_count=self.wordpress_settings.naver_blog_image_count,
            work_folder=self.wordpress_settings.naver_blog_work_folder,
            body_delay_ms=self.wordpress_settings.naver_blog_body_delay_ms,
            automation_mode=self.wordpress_settings.naver_blog_automation_mode,
            profile_scope=profile_scope,
            image_mode=image_mode,
            manual_image_paths=manual_image_paths,
        )
        self.naver_blog_worker.start()

    def _apply_naver_blog_bootstrap_result(self, payload) -> str:
        message = str(payload)
        write_url = ""
        nickname = ""
        blog_id = ""
        payload_profile_scope = ""
        if isinstance(payload, dict):
            message = str(payload.get("message") or "네이버 블로그 로그인 상태를 저장했습니다.")
            write_url = str(payload.get("write_url") or "").strip()
            nickname = str(payload.get("nickname") or "").strip()
            blog_id = self._normalize_naver_blog_id(str(payload.get("blog_id") or ""))
            requested_scope = str(payload.get("profile_scope") or "").strip().lower()
            if requested_scope in NAVER_BLOG_PROFILE_SCOPES:
                payload_profile_scope = requested_scope
        if not write_url and blog_id:
            write_url = f"https://blog.naver.com/{blog_id}?Redirect=Write&"
        if write_url:
            profiles = self._current_naver_blog_profiles()
            active_name = (
                self.naver_blog_active_profile_var.get()
                if hasattr(self, "naver_blog_active_profile_var")
                else self.wordpress_settings.naver_blog_active_profile
            )
            target_index = next(
                (
                    index
                    for index, profile in enumerate(profiles)
                    if payload_profile_scope
                    and naver_blog_profile_scope(profile, index)
                    == payload_profile_scope
                ),
                None,
            )
            if target_index is None:
                target_index = next(
                    (
                        index
                        for index, profile in enumerate(profiles)
                        if str(profile.get("name") or "") == active_name
                    ),
                    0,
                )
            target_profile = profiles[target_index]
            target_name = str(
                target_profile.get("name") or f"블로그 {target_index + 1}"
            )
            if blog_id:
                target_profile["blog_id"] = blog_id
            target_profile["write_url"] = write_url
            if nickname:
                target_profile["nickname"] = nickname
            blog_id_var = getattr(self, "naver_blog_profile_vars", {}).get(
                f"{target_index}:blog_id"
            )
            if blog_id_var is not None and blog_id:
                blog_id_var.set(blog_id)
            write_url_var = getattr(self, "naver_blog_profile_vars", {}).get(
                f"{target_index}:write_url"
            )
            if write_url_var is not None:
                write_url_var.set(write_url)
            nickname_var = getattr(self, "naver_blog_profile_vars", {}).get(
                f"{target_index}:nickname"
            )
            if nickname_var is not None and nickname:
                nickname_var.set(nickname)
            self.wordpress_settings.naver_blog_profiles = profiles
            if target_name == active_name:
                self.wordpress_settings.naver_blog_write_url = write_url
                if hasattr(self, "naver_blog_write_url_entry"):
                    self.naver_blog_write_url_entry.delete(0, "end")
                    self.naver_blog_write_url_entry.insert(0, write_url)
            AppStateStore.save(self.wordpress_settings, save_secrets=False)
            nickname_text = f" 닉네임 '{nickname}'도 저장했습니다." if nickname else " 닉네임은 자동 추출하지 못해 기존 값을 유지했습니다."
            message = (
                f"{message} {target_name} 전용 프로필과 글쓰기 URL을 저장했습니다."
                f"{nickname_text}"
            )
        return message

    def _format_naver_kin_interval_label(self, minutes: int | str | None) -> str:
        value = self._safe_int(str(minutes or 60), 60)
        if value >= 60 and value % 60 == 0:
            return f"{value // 60}시간"
        return f"{value}분"

    def _naver_kin_interval_minutes_from_label(self, label: str, default_minutes: int) -> int:
        text = str(label or "").strip()
        if text.endswith("시간"):
            return max(1, self._safe_int(text.replace("시간", ""), default_minutes // 60 or 1) * 60)
        return max(1, self._safe_int(text.replace("분", ""), default_minutes))

    def _naver_kin_collect_interval_minutes(self) -> int:
        if not hasattr(self, "naver_kin_collect_interval_menu"):
            return self.wordpress_settings.naver_kin_collect_interval_minutes
        return self._naver_kin_interval_minutes_from_label(self.naver_kin_collect_interval_menu.get(), 60)

    def _naver_kin_answer_interval_minutes(self) -> int:
        if not hasattr(self, "naver_kin_answer_interval_menu"):
            return self.wordpress_settings.naver_kin_answer_interval_minutes
        return self._naver_kin_interval_minutes_from_label(self.naver_kin_answer_interval_menu.get(), 30)

    def _refresh_naver_kin_wordpress_prompt_menu(self) -> None:
        if not hasattr(self, "naver_kin_wordpress_prompt_menu"):
            return
        prompt_sets = PromptFileStore.normalize_prompt_sets(
            self.wordpress_settings.prompt_sets,
            self.wordpress_settings,
        )
        wordpress_sets = [item for item in prompt_sets if item.get("platform") == "wordpress"]
        labels: list[str] = []
        ids_by_label: dict[str, str] = {}
        for index, prompt_set in enumerate(wordpress_sets, start=1):
            base_label = f"워드프레스 · {prompt_set.get('name') or '기본'}"
            label = base_label
            if label in ids_by_label:
                label = f"{base_label} ({index})"
            labels.append(label)
            ids_by_label[label] = str(prompt_set.get("id") or "")
        if not labels:
            labels = ["워드프레스 · 기본"]
            ids_by_label[labels[0]] = "wordpress-default"
        self.naver_kin_wordpress_prompt_ids_by_label = ids_by_label
        self.naver_kin_wordpress_prompt_menu.configure(values=labels)
        selected = resolve_naver_kin_wordpress_prompt_set(self.wordpress_settings)
        selected_id = str(selected.get("id") or "")
        selected_label = next(
            (label for label, prompt_id in ids_by_label.items() if prompt_id == selected_id),
            labels[0],
        )
        self.naver_kin_wordpress_prompt_menu.set(selected_label)
        self.wordpress_settings.naver_kin_wordpress_prompt_id = ids_by_label.get(
            selected_label,
            selected_id,
        )

    def _on_naver_kin_wordpress_prompt_changed(self, label: str) -> None:
        prompt_id = getattr(self, "naver_kin_wordpress_prompt_ids_by_label", {}).get(label, "")
        if prompt_id:
            self.wordpress_settings.naver_kin_wordpress_prompt_id = prompt_id
        self._save_naver_kin_settings(silent=True)

    def _update_naver_kin_schedule_summary(self) -> None:
        if not hasattr(self, "naver_kin_schedule_summary_label"):
            return
        collect_label = self._format_naver_kin_interval_label(self._naver_kin_collect_interval_minutes())
        answer_label = self._format_naver_kin_interval_label(self._naver_kin_answer_interval_minutes())
        self.naver_kin_schedule_summary_label.configure(
            text=(
                f"질문 자동수집은 {collect_label}마다, 답변 등록은 {answer_label}마다 1건씩 처리하도록 예약 기준을 잡습니다. "
                "짧은 시간에 반복 답변하지 않도록 기본값을 넉넉하게 두었습니다."
            )
        )

    def _format_naver_kin_next_run(self, timestamp: float | None = None) -> str:
        try:
            value = float(timestamp if timestamp is not None else getattr(self, "naver_kin_next_run_at", 0) or 0)
        except (TypeError, ValueError):
            value = 0
        if value <= 0:
            return "대기 중"
        remaining = max(0, int(value - time.time()))
        minute, second = divmod(remaining, 60)
        hour, minute = divmod(minute, 60)
        if hour:
            remaining_text = f"{hour}시간 {minute}분 {second}초"
        else:
            remaining_text = f"{minute}분 {second}초"
        return f"{time.strftime('%Y-%m-%d %H:%M', time.localtime(value))} · 남은 시간 {remaining_text}"

    def _update_naver_kin_next_run_label(self) -> None:
        if not hasattr(self, "naver_kin_next_run_label"):
            return
        prefix = "자동화 실행 중" if getattr(self, "naver_kin_automation_running", False) else "다음 실행"
        action_text = (
            "질문 자동수집"
            if getattr(self, "naver_kin_next_action", "answer") == "collect"
            else "답변 등록"
        )
        self.naver_kin_next_run_label.configure(
            text=f"{prefix} ({action_text}): {self._format_naver_kin_next_run()}"
        )

    def _start_naver_kin_clock(self) -> None:
        if self._naver_kin_clock_job is not None:
            self.after_cancel(self._naver_kin_clock_job)
        self._naver_kin_clock_job = self.after(1000, self._tick_naver_kin_clock)

    def _tick_naver_kin_clock(self) -> None:
        self._naver_kin_clock_job = None
        if not getattr(self, "naver_kin_automation_running", False):
            self._update_naver_kin_next_run_label()
            return
        self._update_naver_kin_next_run_label()
        self._start_naver_kin_clock()

    def _persist_naver_kin_schedule_state(self) -> None:
        self.wordpress_settings.naver_kin_next_run_at = float(getattr(self, "naver_kin_next_run_at", 0) or 0)
        self.wordpress_settings.naver_kin_next_action = (
            self.naver_kin_next_action
            if getattr(self, "naver_kin_next_action", "answer") in ("answer", "collect")
            else "answer"
        )
        self.wordpress_settings.naver_kin_last_questions = list(getattr(self, "naver_kin_questions", []))
        AppStateStore.save(self.wordpress_settings, save_secrets=False)

    def _set_naver_kin_automation_button_state(self) -> None:
        if not hasattr(self, "naver_kin_automation_button"):
            return
        if self.naver_kin_automation_running:
            self.naver_kin_automation_button.configure(text="자동화 중지", fg_color="#7f3030", hover_color="#9a3a3a")
        else:
            self.naver_kin_automation_button.configure(text="자동화 시작", fg_color="#3468e8", hover_color="#2d5cd0")

    def _clear_naver_kin_run_log(self) -> None:
        self.naver_kin_run_logs = []
        if hasattr(self, "naver_kin_log_box"):
            try:
                self.naver_kin_log_box.configure(state="normal")
                self.naver_kin_log_box.delete("1.0", "end")
                self.naver_kin_log_box.configure(state="disabled")
            except Exception:
                pass

    def _append_naver_kin_run_log(self, message: str) -> None:
        text = str(message or "").strip()
        if not text:
            return
        timestamp = time.strftime("%H:%M:%S")
        line = f"[{timestamp}] {text}"
        if not hasattr(self, "naver_kin_run_logs"):
            self.naver_kin_run_logs = []
        self.naver_kin_run_logs.append(line)
        self.naver_kin_run_logs = self.naver_kin_run_logs[-200:]
        if hasattr(self, "naver_kin_log_box"):
            try:
                self.naver_kin_log_box.configure(state="normal")
                current = self.naver_kin_log_box.get("1.0", "end").strip()
                if current == "아직 진행 로그가 없습니다.":
                    self.naver_kin_log_box.delete("1.0", "end")
                self.naver_kin_log_box.insert("end", line + "\n")
                self.naver_kin_log_box.see("end")
                self.naver_kin_log_box.configure(state="disabled")
            except Exception:
                pass

    def _recent_naver_kin_run_log_text(self, limit: int = 35) -> str:
        logs = list(getattr(self, "naver_kin_run_logs", []) or [])
        if not logs:
            return "표시할 진행 로그가 없습니다."
        return "\n".join(logs[-max(1, int(limit or 35)):])

    def _toggle_naver_kin_automation(self) -> None:
        if self.naver_kin_automation_running:
            self.naver_kin_automation_running = False
            if self._naver_kin_automation_job is not None:
                self.after_cancel(self._naver_kin_automation_job)
                self._naver_kin_automation_job = None
            if self._naver_kin_clock_job is not None:
                self.after_cancel(self._naver_kin_clock_job)
                self._naver_kin_clock_job = None
            self.naver_kin_next_run_at = 0
            self.naver_kin_next_action = "answer"
            self._persist_naver_kin_schedule_state()
            self._set_naver_kin_automation_button_state()
            self._update_naver_kin_next_run_label()
            if hasattr(self, "naver_kin_status_label"):
                self.naver_kin_status_label.configure(text="현재 상태: N지식인 자동화를 중지했습니다.", text_color="#ffcc66")
            return

        self._save_naver_kin_settings(silent=True)
        self.naver_kin_automation_running = True
        self._set_naver_kin_automation_button_state()
        if hasattr(self, "naver_kin_status_label"):
            self.naver_kin_status_label.configure(
                text="현재 상태: 자동화를 시작합니다. 질문이 없으면 먼저 최신 질문을 수집합니다.",
                text_color="#6dadff",
            )
        now = time.time()
        if self.naver_kin_next_run_at and self.naver_kin_next_run_at > now:
            delay_ms = max(1000, int((self.naver_kin_next_run_at - now) * 1000))
            self._naver_kin_automation_job = self.after(delay_ms, self._run_naver_kin_automation_once)
            self._update_naver_kin_next_run_label()
            self._start_naver_kin_clock()
        else:
            self.naver_kin_next_run_at = now
            self.naver_kin_next_action = (
                "answer"
                if self._next_naver_kin_question_for_automation() is not None
                else "collect"
            )
            self._persist_naver_kin_schedule_state()
            self._update_naver_kin_next_run_label()
            self._start_naver_kin_clock()
            self.after(150, self._run_naver_kin_automation_once)

    def _schedule_next_naver_kin_automation(self, delay_minutes: int | None = None, collect_mode: bool = False) -> None:
        if not self.naver_kin_automation_running:
            return
        if self._naver_kin_automation_job is not None:
            self.after_cancel(self._naver_kin_automation_job)
            self._naver_kin_automation_job = None
        minutes = int(delay_minutes or (self._naver_kin_collect_interval_minutes() if collect_mode else self._naver_kin_answer_interval_minutes()))
        minutes = max(1, minutes)
        self.naver_kin_next_action = "collect" if collect_mode else "answer"
        self.naver_kin_next_run_at = time.time() + (minutes * 60)
        self._persist_naver_kin_schedule_state()
        self._update_naver_kin_next_run_label()
        self._start_naver_kin_clock()
        self._naver_kin_automation_job = self.after(minutes * 60 * 1000, self._run_naver_kin_automation_once)
        if hasattr(self, "naver_kin_status_label"):
            mode_text = "질문 자동수집" if collect_mode else "다음 답변 등록"
            self.naver_kin_status_label.configure(
                text=f"현재 상태: {mode_text}을(를) {self._format_naver_kin_next_run()}에 실행합니다.",
                text_color="#6dadff",
            )

    def _next_naver_kin_question_for_automation(self) -> dict | None:
        skip_statuses = {"진행 중", "답변 완료", "오류"}
        for question in self.naver_kin_questions:
            status = str(question.get("automation_status") or "").strip()
            if status not in skip_statuses and naver_kin_question_ready(question):
                return question
        return None

    def _run_naver_kin_automation_once(self) -> None:
        self._naver_kin_automation_job = None
        if not self.naver_kin_automation_running:
            return
        scheduled_action = (
            self.naver_kin_next_action
            if getattr(self, "naver_kin_next_action", "answer") in ("answer", "collect")
            else "answer"
        )
        if self.naver_kin_automation_worker and self.naver_kin_automation_worker.is_alive():
            self._schedule_next_naver_kin_automation(
                delay_minutes=1,
                collect_mode=scheduled_action == "collect",
            )
            return
        if self.naver_kin_worker and self.naver_kin_worker.is_alive():
            if hasattr(self, "naver_kin_status_label"):
                self.naver_kin_status_label.configure(text="현재 상태: 질문 목록 수집 완료를 기다리는 중...", text_color="#6dadff")
            return
        if scheduled_action == "collect":
            self.naver_kin_next_run_at = 0
            self.naver_kin_next_action = "answer"
            self._persist_naver_kin_schedule_state()
            if hasattr(self, "naver_kin_status_label"):
                self.naver_kin_status_label.configure(
                    text="현재 상태: 예약된 최신 질문 자동수집을 시작합니다.",
                    text_color="#6dadff",
                )
            self._start_naver_kin_bootstrap()
            return

        question = self._next_naver_kin_question_for_automation()
        if question is None:
            if hasattr(self, "naver_kin_status_label"):
                self.naver_kin_status_label.configure(
                    text="현재 상태: 상세 본문까지 준비된 질문이 없어 다음 자동수집 시간까지 대기합니다.",
                    text_color="#6dadff",
                )
            self._schedule_next_naver_kin_automation(
                delay_minutes=self._naver_kin_collect_interval_minutes(),
                collect_mode=True,
            )
            return

        try:
            settings = self._read_wordpress_settings()
            self._validate_wordpress_inputs(settings, allow_empty_password=False)
            model_error = writing_model_validation_error(settings)
            if model_error:
                raise RuntimeError(model_error)
            settings.target_platforms = ["wordpress"]
            settings.post_mode = "공개발행"
            settings.naver_kin_answer_prompt = self._current_naver_kin_answer_prompt()
            settings.naver_kin_answer_template = (
                self.naver_kin_answer_template_box.get("1.0", "end").strip()
                if hasattr(self, "naver_kin_answer_template_box")
                else settings.naver_kin_answer_template
            ) or "자세한 답변은 아래 블로그 글에 정리했습니다.\n{url}"
        except RuntimeError as exc:
            self.naver_kin_automation_running = False
            self._set_naver_kin_automation_button_state()
            self.naver_kin_next_run_at = 0
            self._update_naver_kin_next_run_label()
            if hasattr(self, "naver_kin_status_label"):
                self.naver_kin_status_label.configure(text=f"현재 상태: 자동화 시작 실패 - {exc}", text_color="#ff6b6b")
            messagebox.showerror("N지식인 자동화 설정 오류", str(exc))
            return

        question["automation_status"] = "진행 중"
        question["automation_started_at"] = time.strftime("%Y-%m-%d %H:%M:%S")
        self._persist_naver_kin_schedule_state()
        self._render_naver_kin_questions(self.naver_kin_questions)
        self._clear_naver_kin_run_log()
        self._append_naver_kin_run_log(f"자동화 시작: {question.get('title', '질문')}")
        self._append_naver_kin_run_log("1단계: 워드프레스 글 발행 준비를 시작합니다.")
        if hasattr(self, "naver_kin_status_label"):
            self.naver_kin_status_label.configure(
                text=f"현재 상태: '{question.get('title', '질문')}' 워드프레스 글 발행과 지식인 답변을 진행합니다.",
                text_color="#6dadff",
            )
        self.naver_kin_automation_worker = NaverKinAutomationWorker(settings, question, self.result_queue)
        self.naver_kin_automation_worker.start()

    def _on_naver_kin_interval_changed(self) -> None:
        self._update_naver_kin_schedule_summary()
        self._save_naver_kin_settings(silent=True)

    def _save_naver_kin_settings(self, silent: bool = False) -> None:
        if hasattr(self, "naver_kin_url_entry"):
            self.wordpress_settings.naver_kin_question_list_url = (
                self.naver_kin_url_entry.get().strip() or NAVER_KIN_QUESTION_LIST_URL
            )
        if hasattr(self, "naver_kin_sort_menu"):
            self.wordpress_settings.naver_kin_sort_mode = self.naver_kin_sort_menu.get()
        self.wordpress_settings.naver_kin_collect_interval_minutes = self._naver_kin_collect_interval_minutes()
        self.wordpress_settings.naver_kin_answer_interval_minutes = self._naver_kin_answer_interval_minutes()
        self.wordpress_settings.naver_kin_next_run_at = float(getattr(self, "naver_kin_next_run_at", 0) or 0)
        self.wordpress_settings.naver_kin_next_action = (
            self.naver_kin_next_action
            if getattr(self, "naver_kin_next_action", "answer") in ("answer", "collect")
            else "answer"
        )
        if hasattr(self, "naver_kin_wordpress_prompt_menu"):
            selected_label = self.naver_kin_wordpress_prompt_menu.get()
            selected_prompt_id = getattr(
                self,
                "naver_kin_wordpress_prompt_ids_by_label",
                {},
            ).get(selected_label, "")
            if selected_prompt_id:
                self.wordpress_settings.naver_kin_wordpress_prompt_id = selected_prompt_id
        if hasattr(self, "naver_kin_answer_template_box"):
            self.wordpress_settings.naver_kin_answer_template = (
                self.naver_kin_answer_template_box.get("1.0", "end").strip()
                or "자세한 답변은 아래 블로그 글에 정리했습니다.\n{url}"
            )
        self.wordpress_settings.naver_kin_last_questions = list(getattr(self, "naver_kin_questions", []))
        AppStateStore.save(self.wordpress_settings, save_secrets=False)
        if not silent and hasattr(self, "naver_kin_status_label"):
            self.naver_kin_status_label.configure(text="현재 상태: N지식인 설정 저장 완료", text_color="#48d980")

    def _start_naver_kin_bootstrap(self) -> None:
        if self.naver_kin_worker and self.naver_kin_worker.is_alive():
            messagebox.showinfo("진행 중", "N지식인 질문 목록 확인이 이미 진행 중입니다.")
            return
        self._save_naver_kin_settings(silent=True)
        if hasattr(self, "naver_kin_start_button"):
            self.naver_kin_start_button.configure(state="disabled", text="확인 중...")
        if hasattr(self, "naver_kin_status_label"):
            self.naver_kin_status_label.configure(text="현재 상태: N지식인 질문 목록을 여는 중...", text_color="#6dadff")
        self._update_quick_status("N지식인 자동화 준비", "전용 Chrome으로 질문 목록과 최신순 정렬을 확인합니다.", "#6dadff")
        self.naver_kin_worker = NaverKinBootstrapWorker(
            self.wordpress_settings.naver_kin_question_list_url,
            self.wordpress_settings.naver_kin_sort_mode,
            self.result_queue,
        )
        self.naver_kin_worker.start()

    def _handle_naver_kin_done(self, payload) -> None:
        if hasattr(self, "naver_kin_start_button"):
            self.naver_kin_start_button.configure(state="normal", text="질문 목록 확인")
        self.naver_kin_worker = None
        questions = payload.get("questions", []) if isinstance(payload, dict) else []
        previous_by_url = {
            str(item.get("url") or ""): item
            for item in getattr(self, "naver_kin_questions", [])
            if str(item.get("url") or "")
        }
        normalized_questions: list[dict] = []
        for item in questions:
            if not isinstance(item, dict):
                continue
            url = str(item.get("url") or "").strip()
            title = clean_naver_kin_question_title(item.get("title"))
            if not title or not url:
                continue
            previous = previous_by_url.get(url, {})
            normalized = {
                "title": title,
                "url": url,
                "question_text": clean_naver_kin_question_body(
                    item.get("question_text"),
                    title,
                ),
                "detail_error": str(item.get("detail_error") or "").strip(),
                "collected_at": str(item.get("collected_at") or "").strip(),
                "has_image": bool(item.get("has_image")),
                "stale": bool(item.get("stale")),
                "skip_reason": str(item.get("skip_reason") or "").strip(),
                "automation_status": str(previous.get("automation_status") or "").strip(),
                "wordpress_url": str(previous.get("wordpress_url") or "").strip(),
                "wordpress_title": str(previous.get("wordpress_title") or "").strip(),
                "answered_at": str(previous.get("answered_at") or "").strip(),
            }
            if normalized["automation_status"] == "오류" and naver_kin_question_ready(normalized):
                normalized["automation_status"] = ""
            normalized_questions.append(normalized)
        self.naver_kin_questions = normalized_questions
        self.wordpress_settings.naver_kin_last_questions = list(self.naver_kin_questions)
        AppStateStore.save(self.wordpress_settings, save_secrets=False)
        self._render_naver_kin_questions(self.naver_kin_questions)
        message = "N지식인 질문 목록 접근을 확인했습니다."
        if isinstance(payload, dict) and payload.get("current_url"):
            message += f" 현재 URL: {payload['current_url']}"
        if hasattr(self, "naver_kin_status_label"):
            count = len(self.naver_kin_questions)
            body_count = sum(1 for question in self.naver_kin_questions if str(question.get("question_text") or "").strip())
            self.naver_kin_status_label.configure(
                text=f"현재 상태: 질문 {count}개 확인 완료 · 본문 {body_count}개 수집",
                text_color="#48d980",
            )
        self._update_quick_status("N지식인 준비 완료", message, "#48d980")
        if self.naver_kin_automation_running:
            if self._next_naver_kin_question_for_automation() is not None:
                self.naver_kin_next_action = "answer"
                self.naver_kin_next_run_at = 0
                self._persist_naver_kin_schedule_state()
                self.after(500, self._run_naver_kin_automation_once)
            else:
                self._schedule_next_naver_kin_automation(
                    delay_minutes=self._naver_kin_collect_interval_minutes(),
                    collect_mode=True,
                )

    def _handle_naver_kin_error(self, payload) -> None:
        if hasattr(self, "naver_kin_start_button"):
            self.naver_kin_start_button.configure(state="normal", text="질문 목록 확인")
        self.naver_kin_worker = None
        if hasattr(self, "naver_kin_status_label"):
            self.naver_kin_status_label.configure(text="현재 상태: N지식인 질문 목록 확인 실패", text_color="#ff6b6b")
        self._update_quick_status("N지식인 오류", str(payload), "#ff6b6b")
        if self.naver_kin_automation_running:
            self._schedule_next_naver_kin_automation(
                delay_minutes=self._naver_kin_collect_interval_minutes(),
                collect_mode=True,
            )
        else:
            messagebox.showwarning("N지식인 자동화 준비 실패", str(payload))

    def _handle_naver_kin_automation_done(self, payload: dict) -> None:
        question_url = str(payload.get("question_url") or "").strip()
        for question in self.naver_kin_questions:
            if str(question.get("url") or "").strip() == question_url:
                question["automation_status"] = "답변 완료"
                question["wordpress_url"] = str(payload.get("wordpress_url") or "").strip()
                question["wordpress_title"] = str(payload.get("wordpress_title") or "").strip()
                question["answer_text"] = str(payload.get("answer_text") or "").strip()
                question["answered_at"] = time.strftime("%Y-%m-%d %H:%M:%S")
                break
        self.naver_kin_automation_worker = None
        self._persist_naver_kin_schedule_state()
        self._render_naver_kin_questions(self.naver_kin_questions)
        wordpress_url = str(payload.get("wordpress_url") or "").strip()
        message = f"N지식인 답변 등록 완료. 워드프레스 URL: {wordpress_url}" if wordpress_url else "N지식인 답변 등록 완료."
        cardnews_count = int(payload.get("cardnews_count") or 0)
        cleanup_count = int(payload.get("cleanup_count") or 0)
        if cardnews_count:
            message += f" 본문 카드뉴스 {cardnews_count}장 포함."
        if cleanup_count:
            message += f" 임시 이미지 {cleanup_count}개 삭제."
        if hasattr(self, "naver_kin_status_label"):
            self.naver_kin_status_label.configure(text=f"현재 상태: {message}", text_color="#48d980")
        self._append_naver_kin_run_log(message)
        self._update_quick_status("N지식인 자동화 완료", message, "#48d980")
        messagebox.showinfo(
            "N지식인 자동화 진행 로그",
            "자동화가 완료되었습니다.\n\n[진행 로그]\n" + self._recent_naver_kin_run_log_text(),
        )
        if self.naver_kin_automation_running:
            if self._next_naver_kin_question_for_automation() is not None:
                self._schedule_next_naver_kin_automation(
                    delay_minutes=self._naver_kin_answer_interval_minutes()
                )
            else:
                self._schedule_next_naver_kin_automation(
                    delay_minutes=self._naver_kin_collect_interval_minutes(),
                    collect_mode=True,
                )
        else:
            self.naver_kin_next_run_at = 0
            self._update_naver_kin_next_run_label()

    def _handle_naver_kin_automation_error(self, payload: str) -> None:
        error_message = str(payload)
        for question in self.naver_kin_questions:
            if str(question.get("automation_status") or "") == "진행 중":
                question["automation_status"] = "오류"
                question["automation_error"] = error_message
                question["error_at"] = time.strftime("%Y-%m-%d %H:%M:%S")
                break
        self.naver_kin_automation_worker = None
        self._persist_naver_kin_schedule_state()
        self._render_naver_kin_questions(self.naver_kin_questions)
        if hasattr(self, "naver_kin_status_label"):
            self.naver_kin_status_label.configure(text=f"현재 상태: N지식인 자동화 오류 - {error_message}", text_color="#ff6b6b")
        self._append_naver_kin_run_log(f"오류 발생: {error_message}")
        self._update_quick_status("N지식인 자동화 오류", error_message, "#ff6b6b")
        messagebox.showwarning(
            "N지식인 자동화 오류",
            f"{error_message}\n\n[최근 진행 로그]\n{self._recent_naver_kin_run_log_text()}",
        )
        if self.naver_kin_automation_running:
            # 같은 질문에서 무한 반복하지 않도록 오류 항목은 건너뛰고 다음 답변 간격 뒤에 이어갑니다.
            if self._next_naver_kin_question_for_automation() is not None:
                self._schedule_next_naver_kin_automation(
                    delay_minutes=self._naver_kin_answer_interval_minutes()
                )
            else:
                self._schedule_next_naver_kin_automation(
                    delay_minutes=self._naver_kin_collect_interval_minutes(),
                    collect_mode=True,
                )
        else:
            self.naver_kin_next_run_at = 0
            self._update_naver_kin_next_run_label()

    def _render_naver_kin_questions(self, questions: list[dict]) -> None:
        if not hasattr(self, "naver_kin_question_frame"):
            return
        for widget in self.naver_kin_question_frame.winfo_children():
            widget.destroy()
        if not questions:
            ctk.CTkLabel(
                self.naver_kin_question_frame,
                text="아직 확인된 질문이 없습니다. 위의 '질문 목록 확인' 버튼으로 최신 질문을 가져와 주세요.",
                text_color="#9aa7bb",
                anchor="w",
                justify="left",
                font=ctk.CTkFont(size=14, weight="bold"),
            ).grid(row=0, column=0, padx=10, pady=12, sticky="ew")
            self._finish_theme_paint()
            return

        for index, question in enumerate(questions[:10], start=1):
            title = str(question.get("title") or f"질문 {index}").strip()
            url = str(question.get("url") or "").strip()
            question_text = re.sub(r"\s+", " ", str(question.get("question_text") or "")).strip()
            detail_error = str(question.get("detail_error") or "").strip()
            row = ctk.CTkFrame(
                self.naver_kin_question_frame,
                fg_color="#111826",
                corner_radius=14,
                border_width=1,
                border_color="#243247",
            )
            row.grid(row=index - 1, column=0, pady=(0, 10), sticky="ew")
            row.grid_columnconfigure(1, weight=1)
            ctk.CTkLabel(
                row,
                text=f"{index}",
                width=34,
                text_color="#6dadff",
                font=ctk.CTkFont(size=15, weight="bold"),
            ).grid(row=0, column=0, rowspan=2, padx=(12, 6), pady=12, sticky="n")
            ctk.CTkLabel(
                row,
                text=title,
                text_color="#dce6f3",
                anchor="w",
                justify="left",
                wraplength=760,
                font=ctk.CTkFont(size=15, weight="bold"),
            ).grid(row=0, column=1, padx=(0, 10), pady=(12, 2), sticky="ew")
            ctk.CTkLabel(
                row,
                text=url or "URL 없음",
                text_color="#7f8da4",
                anchor="w",
                justify="left",
                wraplength=760,
                font=ctk.CTkFont(size=12),
            ).grid(row=1, column=1, padx=(0, 10), pady=(0, 4), sticky="ew")
            preview_text = (
                f"본문: {question_text[:220]}{'...' if len(question_text) > 220 else ''}"
                if question_text
                else (f"본문 수집 실패: {detail_error}" if detail_error else "본문 수집 결과 없음")
            )
            ctk.CTkLabel(
                row,
                text=preview_text,
                text_color="#a7b3c4" if question_text else "#f4c95d",
                anchor="w",
                justify="left",
                wraplength=760,
                font=ctk.CTkFont(size=12),
            ).grid(row=2, column=1, padx=(0, 10), pady=(0, 12), sticky="ew")
            automation_status = str(question.get("automation_status") or "대기 중").strip() or "대기 중"
            wordpress_url = str(question.get("wordpress_url") or "").strip()
            status_text = f"자동화: {automation_status}"
            if wordpress_url:
                status_text += f" · 발행 URL: {wordpress_url}"
            ctk.CTkLabel(
                row,
                text=status_text,
                text_color="#48d980" if automation_status == "답변 완료" else "#9aa7bb",
                anchor="w",
                justify="left",
                wraplength=760,
                font=ctk.CTkFont(size=12, weight="bold"),
            ).grid(row=3, column=1, padx=(0, 10), pady=(0, 12), sticky="ew")
            ctk.CTkButton(
                row,
                text="질문 열기",
                width=96,
                height=34,
                corner_radius=10,
                fg_color="#314761",
                hover_color="#3f5c7f",
                font=ctk.CTkFont(size=13, weight="bold"),
                command=lambda target_url=url: self._open_source_url(target_url) if target_url else None,
            ).grid(row=0, column=2, padx=(0, 12), pady=(12, 4), sticky="e")
            ctk.CTkButton(
                row,
                text="글쓰기 재료로",
                width=112,
                height=34,
                corner_radius=10,
                fg_color="#19a957",
                hover_color="#168f4b",
                font=ctk.CTkFont(size=13, weight="bold"),
                command=lambda item=question: self._prepare_naver_kin_question_for_writing(item),
            ).grid(row=1, column=2, rowspan=3, padx=(0, 12), pady=(0, 12), sticky="e")
        self._finish_theme_paint()

    def _prepare_naver_kin_question_for_writing(self, question: dict) -> None:
        title = str(question.get("title") or "").strip()
        url = str(question.get("url") or "").strip()
        question_text = str(question.get("question_text") or "").strip()
        if hasattr(self, "topic_entry") and title:
            self.topic_entry.delete(0, "end")
            self.topic_entry.insert(0, title)
        if hasattr(self, "reference_textbox"):
            reference = f"[N지식인 질문]\n{title}\n"
            if url:
                reference += f"\n질문 URL: {url}\n"
            if question_text:
                reference += f"\n질문 본문:\n{question_text}\n"
            reference += "\n이 질문에 답변할 수 있도록 사실 확인 후 워드프레스 답변형 글을 작성하세요."
            self.reference_textbox.delete("1.0", "end")
            self.reference_textbox.insert("1.0", reference)
            self._update_reference_count()
        self.current_keyword = title
        self.selected_keyword_var.set(title)
        if hasattr(self, "manual_keyword_entry"):
            self.manual_keyword_entry.delete(0, "end")
            self.manual_keyword_entry.insert(0, title)
        self._select_naver_kin_prompt_for_writing()
        self._save_ui_state()
        self._switch_page("writing")
        self._reset_writing_section_completion()
        self._open_writing_section("keyword", complete_previous=True)
        self.keyword_status_label.configure(text="N지식인 질문을 글쓰기 재료로 넣었습니다.")
        self.article_progress_label.configure(
            text="질문 내용을 기준으로 참고내용을 보강한 뒤 글 작성을 진행하면 됩니다."
        )

