    def _refresh_automation_queue(self) -> None:
        if not hasattr(self, "automation_list"):
            return
        self._ensure_automation_queue_schedules()
        completed_ids = {
            str(item.get("id") or "")
            for item in self.automation_queue
            if str(item.get("status") or "") == "업로드 완료"
        }
        if completed_ids:
            self.automation_queue = [
                item for item in self.automation_queue if str(item.get("id") or "") not in completed_ids
            ]
            for item_id in completed_ids:
                self.automation_selection_vars.pop(item_id, None)
            self.wordpress_settings.automation_queue = list(self.automation_queue)
            AppStateStore.save(self.wordpress_settings, save_secrets=False)
            self._send_remote_queue_snapshot()
        queue_items = list(self.automation_queue)
        queue_ids = {str(item.get("id") or "") for item in queue_items}
        self.automation_selection_vars = {
            item_id: variable
            for item_id, variable in self.automation_selection_vars.items()
            if item_id in queue_ids
        }
        if hasattr(self, "automation_count_label"):
            self.automation_count_label.configure(text=f"대기열 {len(queue_items)}개")
        if hasattr(self, "automation_select_all_var"):
            all_selected = bool(queue_items) and all(
                (
                    self.automation_selection_vars.get(str(item.get("id") or "")) is not None
                    and self.automation_selection_vars[str(item.get("id") or "")].get()
                )
                for item in queue_items
            )
            self.automation_select_all_var.set(all_selected)

        render_signature = tuple(
            (
                str(item.get("id") or ""),
                str(item.get("title") or ""),
                str(item.get("status") or ""),
                str(item.get("scheduled_at") or ""),
                tuple(item.get("target_platforms") or []),
                str(item.get("thumbnail_path") or ""),
                len(item.get("cardnews_image_paths") or item.get("cardnews_paths") or []),
            )
            for item in queue_items
        )
        if (
            render_signature == self._automation_queue_render_signature
            and self.automation_list.winfo_children()
        ):
            self._finish_theme_paint()
            return
        self._automation_queue_render_signature = render_signature
        for child in self.automation_list.winfo_children():
            child.destroy()

        if not queue_items:
            empty_card = ctk.CTkFrame(self.automation_list, fg_color="#1d2635", corner_radius=18)
            empty_card.grid(row=0, column=0, padx=18, pady=18, sticky="ew")
            empty_card.grid_columnconfigure(0, weight=1)
            ctk.CTkLabel(
                empty_card,
                text="아직 대기열에 담긴 글이 없습니다.",
                text_color="#dce6f3",
                font=ctk.CTkFont(size=18, weight="bold"),
            ).grid(row=0, column=0, padx=22, pady=(22, 6), sticky="w")
            ctk.CTkLabel(
                empty_card,
                text="블로그글쓰기 4번 썸네일 제작에서 ‘대기열 추가’를 누르면 이곳에 작업목록이 쌓입니다.",
                text_color="#aab7c8",
                wraplength=680,
                justify="left",
                font=ctk.CTkFont(size=14),
            ).grid(row=1, column=0, padx=22, pady=(0, 22), sticky="w")
            self._finish_theme_paint()
            return

        for row, item in enumerate(reversed(queue_items)):
            card = ctk.CTkFrame(self.automation_list, fg_color="#1d2635", corner_radius=18)
            card.grid(row=row, column=0, padx=18, pady=(18 if row == 0 else 0, 12), sticky="ew")
            card.grid_columnconfigure(0, weight=0)
            card.grid_columnconfigure(1, weight=1)
            card.grid_columnconfigure(2, weight=0)

            title = str(item.get("title") or "제목 없음")
            keyword = str(item.get("keyword") or item.get("topic") or "키워드 없음")
            platforms = ", ".join(item.get("target_platforms") or []) or "대상 블로그 미선택"
            created_at = str(item.get("created_at") or "")
            scheduled_at = item.get("scheduled_at")
            scheduled_text = self._format_automation_schedule_time(scheduled_at)
            thumbnail_path = str(item.get("thumbnail_path") or "")
            status = str(item.get("status") or "대기 중")
            item_id = str(item.get("id") or "")
            selection_var = self.automation_selection_vars.setdefault(item_id, tk.BooleanVar(value=False))

            ctk.CTkCheckBox(
                card,
                text="",
                variable=selection_var,
                command=self._sync_automation_select_all_state,
                width=26,
                checkbox_width=22,
                checkbox_height=22,
                fg_color="#3468e8",
                hover_color="#2d5cd0",
            ).grid(row=0, column=0, rowspan=4, padx=(18, 0), pady=20, sticky="nw")

            ctk.CTkLabel(
                card,
                text=title,
                text_color="#f2f6ff",
                font=ctk.CTkFont(size=18, weight="bold"),
                anchor="w",
                justify="left",
                wraplength=760,
            ).grid(row=0, column=1, padx=16, pady=(18, 6), sticky="ew")

            action_row = ctk.CTkFrame(card, fg_color="transparent")
            action_row.grid(row=0, column=2, padx=(0, 16), pady=(16, 4), sticky="ne")
            ctk.CTkButton(
                action_row,
                text="미리보기",
                width=82,
                height=34,
                corner_radius=11,
                fg_color="#314761",
                hover_color="#3f5c7f",
                font=ctk.CTkFont(size=12, weight="bold"),
                command=lambda target_id=item_id: self._preview_automation_queue_item(target_id),
            ).grid(row=0, column=0, padx=(0, 8))
            ctk.CTkButton(
                action_row,
                text="삭제",
                width=64,
                height=34,
                corner_radius=11,
                fg_color="#7f3030",
                hover_color="#9a3a3a",
                font=ctk.CTkFont(size=12, weight="bold"),
                command=lambda target_id=item_id: self._delete_automation_queue_item(target_id),
            ).grid(row=0, column=1)

            ctk.CTkLabel(
                card,
                text=f"키워드: {keyword}  ·  대상: {platforms}  ·  상태: {status}",
                text_color="#b8c5d8",
                font=ctk.CTkFont(size=14),
                anchor="w",
                justify="left",
            ).grid(row=1, column=1, padx=16, sticky="ew")
            detail_text = f"담은 시간: {created_at}"
            if thumbnail_path:
                detail_text += f"  ·  썸네일: {thumbnail_path}"
            else:
                detail_text += "  ·  썸네일: 없음"
            if item.get("published_url"):
                detail_text += f"  ·  발행 URL: {item['published_url']}"
            if item.get("upload_error"):
                detail_text += f"  ·  오류: {str(item['upload_error'])[:120]}"
            ctk.CTkLabel(
                card,
                text=detail_text,
                text_color="#8292a9",
                font=ctk.CTkFont(size=12),
                anchor="w",
                justify="left",
                wraplength=760,
            ).grid(row=2, column=1, padx=16, pady=(6, 18), sticky="ew")

            schedule_row = ctk.CTkFrame(card, fg_color="transparent")
            schedule_row.grid(row=3, column=1, columnspan=2, padx=16, pady=(0, 18), sticky="ew")
            schedule_row.grid_columnconfigure(1, weight=1)
            ctk.CTkLabel(
                schedule_row,
                text="등록 예정시간",
                text_color="#dce6f3",
                font=ctk.CTkFont(size=13, weight="bold"),
            ).grid(row=0, column=0, padx=(0, 8), sticky="w")
            schedule_entry = ctk.CTkEntry(
                schedule_row,
                height=34,
                corner_radius=10,
                fg_color="#111826",
                border_color="#314761",
                font=ctk.CTkFont(size=13, weight="bold"),
            )
            schedule_entry.grid(row=0, column=1, padx=(0, 8), sticky="ew")
            schedule_entry.insert(0, scheduled_text if scheduled_text != "미정" else "")
            ctk.CTkButton(
                schedule_row,
                text="시간변경",
                width=92,
                height=34,
                corner_radius=10,
                fg_color="#314761",
                hover_color="#3f5c7f",
                font=ctk.CTkFont(size=12, weight="bold"),
                command=lambda target_id=item_id, entry=schedule_entry: self._update_automation_item_schedule(
                    target_id,
                    entry.get(),
                ),
            ).grid(row=0, column=2, sticky="e")
        self._finish_theme_paint()

    def _configure_public_data_table_columns(self, frame) -> None:
        # Fixed minimum widths on every column made the white-theme table overflow
        # and look shifted. Keep only selector/rank fixed; let content columns flex.
        column_specs = [
            (0, 42),
            (0, 38),
            (4, 0),
            (2, 0),
            (1, 0),
            (1, 0),
            (1, 0),
            (1, 0),
        ]
        for col, (weight, minsize) in enumerate(column_specs):
            frame.grid_columnconfigure(col, weight=weight, minsize=minsize)

    def _public_data_table_palette(self) -> dict[str, str]:
        if self._normalize_app_theme(self.wordpress_settings.app_theme) == "화이트테마":
            return {
                "table_fg": "#f7f9fc",
                "header_fg": "#e6eefc",
                "row_odd": "#eef4fb",
                "row_even": "#e8eff7",
                "empty_fg": "#eef4fb",
                "text": "#1f2937",
                "muted": "#536173",
                "subtext": "#667085",
                "border": "#c9d4e3",
            }
        return {
            "table_fg": "#111826",
            "header_fg": "#182235",
            "row_odd": "#1d2635",
            "row_even": "#162031",
            "empty_fg": "#1d2635",
            "text": "#f2f6ff",
            "muted": "#d7e0ed",
            "subtext": "#aab7c8",
            "border": "#273a54",
        }

