    def _randomize_thumbnail_border_color(self, refresh_preview: bool = True) -> str:
        palette = ["빨간색", "파란색", "검정색", "민트색", "노란색", "핑크색"]
        current_color = self.thumbnail_border_color_menu.get() if hasattr(self, "thumbnail_border_color_menu") else ""
        candidates = [color for color in palette if color != current_color] or palette
        selected_color = random.choice(candidates)
        self.thumbnail_border_color_menu.set(selected_color)
        if refresh_preview:
            self._generate_thumbnail_preview()
        return selected_color

    def _safe_int(self, value: str, default: int) -> int:
        try:
            return int(value)
        except (TypeError, ValueError):
            return default

    def _wrap_thumbnail_text(self, text: str, width: int, font_size: int) -> str:
        return "\n".join(self._thumbnail_text_lines(text, width, font_size))

    def _thumbnail_text_lines(self, text: str, width: int, font_size: int) -> list[str]:
        max_width = max(80, width - 90)
        font = self._thumbnail_measure_fonts.get(font_size)
        if font is None:
            font = tkfont.Font(family="Apple SD Gothic Neo", size=font_size, weight="bold")
            self._thumbnail_measure_fonts[font_size] = font
            if len(self._thumbnail_measure_fonts) > 12:
                oldest_size = next(iter(self._thumbnail_measure_fonts))
                if oldest_size != font_size:
                    self._thumbnail_measure_fonts.pop(oldest_size, None)
        raw_lines = [line.strip() for line in text.splitlines() if line.strip()]
        if not raw_lines:
            raw_lines = ["썸네일", "미리보기"]

        wrapped: list[str] = []
        for raw_line in raw_lines:
            wrapped.extend(self._wrap_thumbnail_line_by_pixels(raw_line, max_width, font))

        return wrapped[:6] or ["썸네일", "미리보기"]

    def _wrap_thumbnail_line_by_pixels(self, text: str, max_width: int, font: tkfont.Font) -> list[str]:
        if font.measure(text) <= max_width:
            return [text]

        tokens = text.split(" ")
        lines: list[str] = []
        current = ""
        for token in tokens:
            candidate = f"{current} {token}".strip()
            if candidate and font.measure(candidate) <= max_width:
                current = candidate
                continue

            if current:
                lines.append(current)
                current = ""

            if font.measure(token) <= max_width:
                current = token
            else:
                current = self._append_wrapped_char_chunks(token, max_width, font, lines)

        if current:
            lines.append(current)
        return lines

    def _append_wrapped_char_chunks(
        self,
        text: str,
        max_width: int,
        font: tkfont.Font,
        lines: list[str],
    ) -> str:
        current = ""
        for char in text:
            candidate = current + char
            if candidate and font.measure(candidate) <= max_width:
                current = candidate
            else:
                if current:
                    lines.append(current)
                current = char
        return current

    def _load_resized_background_image(self, width: int, height: int, bg_color: str) -> tuple[tk.PhotoImage, float, float] | None:
        if not self.thumbnail_background_image_path:
            return None
        if Image is not None and ImageTk is not None:
            try:
                source, modified_ns = self._load_pillow_source_image(self.thumbnail_background_image_path)
                source_width, source_height = source.size
                target_width, target_height, x, y = self._thumbnail_image_geometry(
                    width,
                    height,
                    source_width,
                    source_height,
                )
                opacity = round(float(self.thumbnail_image_opacity_var.get()))
                grayscale = bool(self.thumbnail_image_grayscale_var.get())
                cache_key = (
                    self.thumbnail_background_image_path,
                    modified_ns,
                    target_width,
                    target_height,
                    round(x, 2),
                    round(y, 2),
                    bg_color,
                    opacity,
                    grayscale,
                )
                if self._thumbnail_background_cache and self._thumbnail_background_cache[0] == cache_key:
                    return self._thumbnail_background_cache[1]
                photo = self._pillow_resized_photo(
                    source,
                    target_width,
                    target_height,
                    bg_color,
                    opacity,
                    grayscale,
                )
                result = (photo, x, y)
                self._thumbnail_background_cache = (cache_key, result)
                return result
            except (OSError, ValueError, tk.TclError):
                pass
        try:
            original = tk.PhotoImage(file=self.thumbnail_background_image_path)
        except tk.TclError:
            messagebox.showerror("이미지 열기 실패", "현재 배경 이미지는 열 수 없습니다. PNG 또는 GIF 파일을 사용해 주세요.")
            self.thumbnail_selected_image_label_text.set("이미지 파일을 찾을 수 없음")
            return None

        source_width = max(1, original.width())
        source_height = max(1, original.height())
        target_width, target_height, x, y = self._thumbnail_image_geometry(width, height, source_width, source_height)
        try:
            modified_ns = Path(self.thumbnail_background_image_path).stat().st_mtime_ns
        except OSError:
            modified_ns = 0
        cache_key = (
            self.thumbnail_background_image_path,
            modified_ns,
            target_width,
            target_height,
            round(x, 2),
            round(y, 2),
            bg_color,
            round(float(self.thumbnail_image_opacity_var.get())),
            bool(self.thumbnail_image_grayscale_var.get()),
        )
        if self._thumbnail_background_cache and self._thumbnail_background_cache[0] == cache_key:
            return self._thumbnail_background_cache[1]
        resized = self._resize_photo_nearest(original, target_width, target_height, bg_color)
        result = (resized, x, y)
        self._thumbnail_background_cache = (cache_key, result)
        return result

