    def _load_pillow_source_image(self, image_path: str):
        path = Path(image_path).expanduser()
        modified_ns = path.stat().st_mtime_ns
        cached = self._source_image_cache.get(str(path))
        if cached and cached[0] == modified_ns:
            return cached[1], modified_ns
        with Image.open(path) as opened:
            source = opened.convert("RGBA").copy()
        self._source_image_cache[str(path)] = (modified_ns, source)
        if len(self._source_image_cache) > 4:
            oldest_key = next(iter(self._source_image_cache))
            if oldest_key != str(path):
                self._source_image_cache.pop(oldest_key, None)
        return source, modified_ns

    def _pillow_resized_photo(
        self,
        source,
        target_width: int,
        target_height: int,
        bg_color: str,
        opacity_value: int,
        grayscale: bool,
    ):
        resampling = getattr(Image, "Resampling", Image)
        resized = source.resize((target_width, target_height), resampling.LANCZOS)
        if grayscale and ImageOps is not None:
            alpha = resized.getchannel("A")
            resized = ImageOps.grayscale(resized).convert("RGBA")
            resized.putalpha(alpha)
        background = Image.new("RGBA", resized.size, (*self._hex_to_rgb(bg_color), 255))
        opacity = max(0, min(100, int(opacity_value))) / 100
        alpha = resized.getchannel("A").point(lambda value: round(value * opacity))
        resized.putalpha(alpha)
        background.alpha_composite(resized)
        return ImageTk.PhotoImage(background)

    def _thumbnail_image_geometry(
        self,
        canvas_width: int,
        canvas_height: int,
        source_width: int,
        source_height: int,
    ) -> tuple[int, int, float, float]:
        scale = max(20, min(160, round(float(self.thumbnail_image_scale_var.get())))) / 100
        box_width = max(1, round(canvas_width * scale))
        box_height = max(1, round(canvas_height * scale))
        source_ratio = source_width / max(1, source_height)
        box_ratio = box_width / max(1, box_height)
        if source_ratio >= box_ratio:
            target_width = box_width
            target_height = max(1, round(box_width / source_ratio))
        else:
            target_height = box_height
            target_width = max(1, round(box_height * source_ratio))

        position = self.thumbnail_image_position_menu.get()
        margin = max(8, min(canvas_width, canvas_height) // 24)
        if position == "왼쪽상단":
            x, y = margin, margin
        elif position == "오른쪽상단":
            x, y = canvas_width - target_width - margin, margin
        elif position == "왼쪽하단":
            x, y = margin, canvas_height - target_height - margin
        elif position == "오른쪽하단":
            x, y = canvas_width - target_width - margin, canvas_height - target_height - margin
        else:
            x, y = (canvas_width - target_width) / 2, (canvas_height - target_height) / 2
        return target_width, target_height, x, y

    def _cardnews_image_geometry(
        self,
        canvas_width: int,
        canvas_height: int,
        source_width: int,
        source_height: int,
    ) -> tuple[int, int, float, float]:
        scale = max(20, min(180, round(float(self.cardnews_image_scale_var.get())))) / 100
        box_width = max(1, round(canvas_width * scale))
        box_height = max(1, round(canvas_height * scale))
        source_ratio = source_width / max(1, source_height)
        box_ratio = box_width / max(1, box_height)
        if source_ratio >= box_ratio:
            target_width = box_width
            target_height = max(1, round(box_width / source_ratio))
        else:
            target_height = box_height
            target_width = max(1, round(box_height * source_ratio))

        position = self.cardnews_image_position_menu.get()
        margin = max(8, min(canvas_width, canvas_height) // 24)
        if position == "왼쪽상단":
            x, y = margin, margin
        elif position == "오른쪽상단":
            x, y = canvas_width - target_width - margin, margin
        elif position == "왼쪽하단":
            x, y = margin, canvas_height - target_height - margin
        elif position == "오른쪽하단":
            x, y = canvas_width - target_width - margin, canvas_height - target_height - margin
        else:
            x, y = (canvas_width - target_width) / 2, (canvas_height - target_height) / 2
        return target_width, target_height, x, y

    def _resize_photo_nearest(
        self,
        source: tk.PhotoImage,
        target_width: int,
        target_height: int,
        bg_color: str,
        opacity_value: int | None = None,
        grayscale: bool | None = None,
    ) -> tk.PhotoImage:
        output = tk.PhotoImage(width=target_width, height=target_height)
        source_width = max(1, source.width())
        source_height = max(1, source.height())
        if opacity_value is None:
            opacity_value = round(float(self.thumbnail_image_opacity_var.get()))
        opacity = max(0, min(100, opacity_value)) / 100
        bg_rgb = self._hex_to_rgb(bg_color)
        if grayscale is None:
            grayscale = self.thumbnail_image_grayscale_var.get()
        for y in range(target_height):
            source_y = min(source_height - 1, int(y * source_height / target_height))
            row: list[str] = []
            for x in range(target_width):
                source_x = min(source_width - 1, int(x * source_width / target_width))
                rgb = self._photo_pixel_rgb(source, source_x, source_y)
                if grayscale:
                    gray = round((rgb[0] * 0.299) + (rgb[1] * 0.587) + (rgb[2] * 0.114))
                    rgb = (gray, gray, gray)
                blended = tuple(round((channel * opacity) + (bg_rgb[index] * (1 - opacity))) for index, channel in enumerate(rgb))
                row.append("#%02x%02x%02x" % blended)
            output.put("{" + " ".join(row) + "}", to=(0, y))
        return output

    def _photo_pixel_rgb(self, image: tk.PhotoImage, x: int, y: int) -> tuple[int, int, int]:
        value = image.get(x, y)
        if isinstance(value, tuple):
            return tuple(int(part) for part in value[:3])  # type: ignore[return-value]
        if isinstance(value, str):
            value = value.strip()
            if value.startswith("#") and len(value) >= 7:
                return int(value[1:3], 16), int(value[3:5], 16), int(value[5:7], 16)
        return 0, 0, 0

    def _hex_to_rgb(self, color: str) -> tuple[int, int, int]:
        color = color.strip()
        if color.startswith("#") and len(color) >= 7:
            return int(color[1:3], 16), int(color[3:5], 16), int(color[5:7], 16)
        return 255, 255, 255

    def _show_thumbnail_preview(self) -> None:
        self.thumbnail_preview_mode = "thumbnail"
        self._generate_thumbnail_preview()

    def _show_cardnews_preview(self) -> None:
        self._draw_body_cardnews_preview()

    def _update_thumbnail_preview_mode_buttons(self) -> None:
        return

    def _generate_thumbnail_preview(self) -> None:
        width = max(200, self._safe_int(self.thumbnail_width_entry.get(), 400))
        height = max(200, self._safe_int(self.thumbnail_height_entry.get(), 400))
        font_size = max(20, self._safe_int(self.thumbnail_font_size_entry.get(), 56))
        text_value = self.thumbnail_prompt_preview.get("1.0", "end").strip()
        actual_text_lines = self._thumbnail_text_lines(text_value, width, font_size)
        preview_limit = 380
        scale = min(preview_limit / width, preview_limit / height, 1)
        preview_width = max(160, round(width * scale))
        preview_height = max(160, round(height * scale))
        preview_font_size = max(12, round(font_size * scale))
        self._draw_thumbnail_on_canvas(
            self.thumbnail_preview_canvas,
            preview_width,
            preview_height,
            preview_font_size,
            keep_photo=True,
            text_lines=actual_text_lines,
        )

    def _draw_body_cardnews_preview(self) -> None:
        if not hasattr(self, "body_cardnews_preview_canvas"):
            return
        self._draw_body_cardnews_on_canvas(
            self.body_cardnews_preview_canvas,
            preview_limit=320,
            photo_attr="body_cardnews_preview_background_photo",
        )

    def _draw_body_cardnews_on_canvas(self, canvas: tk.Canvas, preview_limit: int, photo_attr: str) -> None:
        actual_width = max(400, self._safe_int(self.cardnews_width_entry.get(), 1024))
        actual_height = max(400, self._safe_int(self.cardnews_height_entry.get(), 1024))
        preview_scale = min(preview_limit / actual_width, preview_limit / actual_height, 1)
        width = max(160, round(actual_width * preview_scale))
        height = max(120, round(actual_height * preview_scale))
        bg_color = self._thumbnail_color_value(self.cardnews_bg_color_menu.get())
        border_color = self._thumbnail_color_value(self.cardnews_border_color_menu.get())
        text_color = self._thumbnail_color_value(self.cardnews_text_color_menu.get())
        stroke_color = self._thumbnail_color_value(self.cardnews_text_stroke_menu.get())
        shadow_mode = self.cardnews_shadow_menu.get()
        font_size = max(16, min(48, round(self._safe_int(self.cardnews_font_size_entry.get(), 78) * preview_scale)))
        canvas.configure(width=width, height=height, bg=bg_color)
        canvas.delete("all")
        setattr(self, photo_attr, None)

        use_background_image = (
            self.cardnews_background_mode_menu.get() == "선택 이미지 사용"
            and bool(self.cardnews_background_image_path)
        )
        if use_background_image:
            background_result = self._load_resized_cardnews_background_image(width, height, bg_color)
            if background_result is not None:
                background_photo, image_x, image_y = background_result
                setattr(self, photo_attr, background_photo)
                canvas.create_image(image_x, image_y, image=background_photo, anchor="nw")

        if border_color:
            border_width = max(10, width // 18)
            canvas.create_rectangle(
                border_width / 2,
                border_width / 2,
                width - border_width / 2,
                height - border_width / 2,
                outline=border_color,
                width=border_width,
            )

        if self.cardnews_specs:
            index = max(0, min(self.active_cardnews_slide_index, len(self.cardnews_specs) - 1))
            spec = self.cardnews_specs[index]
            heading = spec.get("heading", "").strip() or "핵심 정보"
            summary = spec.get("summary", "").strip() or "핵심 내용을 한눈에 보기 쉽게 정리했습니다."
            signature = self.cardnews_signature_entry.get().strip()
            total = len(self.cardnews_specs)
        else:
            index = 0
            heading = "카드뉴스 미리보기"
            summary = "글이 완성되면 본문 H2가 카드뉴스 슬라이드로 자동 준비됩니다."
            signature = self.cardnews_signature_entry.get().strip() or "BLOG HELPER CARD NEWS"
            total = 1

        heading_lines = self._wrap_text_for_svg(heading, width - 72, font_size, 3)
        summary_lines = self._wrap_text_for_svg(summary, width - 86, 14, 2)
        heading_text = "\n".join(heading_lines)
        summary_text = "\n".join(summary_lines)

        canvas.create_text(
            width / 2,
            30,
            text=f"{index + 1} / {total}",
            fill="#6b7280",
            font=("Apple SD Gothic Neo", 12, "bold"),
            justify="center",
        )

        heading_font = ("Apple SD Gothic Neo", font_size, "bold")
        heading_y = height * 0.38
        if shadow_mode != "없음":
            offset = 2 if shadow_mode == "약한 그림자" else 4
            canvas.create_text(
                (width / 2) + offset,
                heading_y + offset,
                text=heading_text,
                fill="#000000",
                font=heading_font,
                justify="center",
                width=width - 72,
            )
        if stroke_color:
            for dx, dy in [(-2, 0), (2, 0), (0, -2), (0, 2)]:
                canvas.create_text(
                    (width / 2) + dx,
                    heading_y + dy,
                    text=heading_text,
                    fill=stroke_color,
                    font=heading_font,
                    justify="center",
                    width=width - 72,
                )
        canvas.create_text(
            width / 2,
            heading_y,
            text=heading_text,
            fill=text_color,
            font=heading_font,
            justify="center",
            width=width - 72,
        )

        summary_box_height = max(46, min(70, height * 0.25))
        summary_top = (height * 0.68) - (summary_box_height / 2)
        summary_bottom = (height * 0.68) + (summary_box_height / 2)
        canvas.create_rectangle(
            34,
            summary_top,
            width - 34,
            summary_bottom,
            fill="#ffffff",
            outline="#d8dee8",
            width=2,
        )
        canvas.create_text(
            width / 2,
            (summary_top + summary_bottom) / 2,
            text=summary_text,
            fill="#1f2937",
            font=("Apple SD Gothic Neo", 14, "bold"),
            justify="center",
            width=width - 86,
        )
        if signature:
            canvas.create_text(
                width / 2,
                height * 0.9,
                text=signature,
                fill=border_color,
                font=("Apple SD Gothic Neo", max(10, round(min(width, height) * 0.029)), "bold"),
                anchor="center",
                width=width - 72,
                justify="center",
            )

    def _draw_thumbnail_on_canvas(
        self,
        canvas: tk.Canvas,
        width: int,
        height: int,
        font_size: int,
        keep_photo: bool,
        text_lines: list[str] | None = None,
    ) -> None:
        text_value = self.thumbnail_prompt_preview.get("1.0", "end").strip()
        bg_color = self._thumbnail_color_value(self.thumbnail_bg_color_menu.get())
        border_color = self._thumbnail_color_value(self.thumbnail_border_color_menu.get())
        text_color = self._thumbnail_color_value(self.thumbnail_text_color_menu.get())
        stroke_color = self._thumbnail_color_value(self.thumbnail_text_stroke_menu.get())
        shadow_mode = self.thumbnail_shadow_menu.get()

        canvas.configure(width=width, height=height, bg=bg_color)
        canvas.delete("all")

        if keep_photo:
            self.thumbnail_canvas_image = None
            self.thumbnail_background_photo = None

        use_background_image = (
            self.thumbnail_background_mode_menu.get() == "선택 이미지 사용"
            and bool(self.thumbnail_background_image_path)
        )
        if use_background_image:
            background_result = self._load_resized_background_image(width, height, bg_color)
            if background_result is not None:
                background_photo, image_x, image_y = background_result
                if keep_photo:
                    self.thumbnail_background_photo = background_photo
                    photo = self.thumbnail_background_photo
                else:
                    canvas._thumbnail_background_photo = background_photo
                    photo = canvas._thumbnail_background_photo
                canvas.create_image(image_x, image_y, image=photo, anchor="nw")

        if border_color:
            border_width = max(8, width // 24)
            canvas.create_rectangle(
                border_width / 2,
                border_width / 2,
                width - border_width / 2,
                height - border_width / 2,
                outline=border_color,
                width=border_width,
            )

        preview_text = "\n".join(text_lines) if text_lines is not None else self._wrap_thumbnail_text(text_value, width, font_size)
        center_x = width / 2
        center_y = height / 2
        font = ("Apple SD Gothic Neo", font_size, "bold")

        if shadow_mode != "없음":
            shadow_offset = 3 if shadow_mode == "약한 그림자" else 7
            canvas.create_text(
                center_x + shadow_offset,
                center_y + shadow_offset,
                text=preview_text,
                fill="#000000",
                font=font,
                justify="center",
                width=width - 90,
            )

        if stroke_color:
            for offset_x, offset_y in [(-2, 0), (2, 0), (0, -2), (0, 2)]:
                canvas.create_text(
                    center_x + offset_x,
                    center_y + offset_y,
                    text=preview_text,
                    fill=stroke_color,
                    font=font,
                    justify="center",
                    width=width - 90,
                )

        canvas.create_text(
            center_x,
            center_y,
            text=preview_text,
            fill=text_color,
            font=font,
            justify="center",
            width=width - 90,
        )

    def _save_thumbnail_image(self) -> None:
        self._generate_thumbnail_preview()
        title = self.article_title_entry.get().strip() or self.generated_article_title or self._selected_or_manual_keyword()
        save_path = filedialog.asksaveasfilename(
            title="썸네일 저장",
            defaultextension=".png",
            initialfile=build_thumbnail_filename(title),
            filetypes=[("PNG 파일", "*.png")],
        )
        if not save_path:
            return

        destination = Path(save_path)
        if destination.suffix.lower() != ".png":
            destination = destination.with_suffix(".png")

        try:
            exported_path = self._export_thumbnail_png(destination)
        except RuntimeError as exc:
            messagebox.showerror("썸네일 저장 실패", str(exc))
            return

        self.thumbnail_saved_path = str(exported_path)
        self._save_ui_state()
        messagebox.showinfo("썸네일 저장 완료", f"썸네일을 PNG로 저장했습니다.\n{exported_path}")

    def _export_thumbnail_png(self, destination: Path | None = None) -> Path:
        target_path = destination or THUMBNAIL_EXPORT_FILE
        width = max(200, self._safe_int(self.thumbnail_width_entry.get(), 400))
        height = max(200, self._safe_int(self.thumbnail_height_entry.get(), 400))
        font_size = max(20, self._safe_int(self.thumbnail_font_size_entry.get(), 56))

        target_path.parent.mkdir(parents=True, exist_ok=True)
        svg_markup = self._build_thumbnail_svg(width, height, font_size)
        return render_svg_to_png(
            svg_markup,
            target_path,
            max(width, height),
            "썸네일",
        )

    def _generated_thumbnail_export_path(self, title: str = "") -> Path:
        article_title = title or self.article_title_entry.get().strip() or self.generated_article_title
        GENERATED_UPLOAD_DIR.mkdir(parents=True, exist_ok=True)
        return GENERATED_UPLOAD_DIR / build_thumbnail_filename(article_title)

    def _generate_body_cardnews_images(self) -> None:
        article_html = self.article_editor.get("1.0", "end").strip()
        title = self.article_title_entry.get().strip() or self.generated_article_title or self._selected_or_manual_keyword()
        if not article_html or "생성된 글이 여기에 표시됩니다" in article_html:
            messagebox.showwarning("글 생성 필요", "먼저 3번에서 글을 생성하거나 본문을 입력해 주세요.")
            return

        provider = self.writing_inline_images_provider_menu.get() if hasattr(self, "writing_inline_images_provider_menu") else ""
        if provider != "카드뉴스 생성":
            self.cardnews_status_label.configure(
                text="2번 추천키워드선택의 이미지 삽입 방식이 '카드뉴스 생성'이 아니어도 수동 생성은 가능합니다.",
                text_color="#ffcc66",
            )

        self._save_active_cardnews_slide()
        count = max(1, min(self._safe_int(self.writing_inline_images_count_menu.get(), 2), 4))
        if not self.cardnews_specs:
            self.cardnews_specs = self._body_cardnews_specs(article_html, title, count)
            self._merge_saved_cardnews_styles()
            self.active_cardnews_slide_index = 0
            self._render_active_cardnews_slide()
        self._merge_saved_cardnews_styles()
        specs = self.cardnews_specs[:count]
        self.cardnews_image_paths = []
        self.generate_cardnews_button.configure(state="disabled", text="생성 중...")
        self.cardnews_status_label.configure(text=f"본문 카드뉴스 {len(specs)}장을 생성하고 있습니다...", text_color="#6dadff")
        self.update_idletasks()
        original_style = self._current_cardnews_style()

        try:
            for index, spec in enumerate(specs, start=1):
                self._apply_cardnews_style(spec.get("style"), refresh_preview=False)
                output_path = DATA_DIR / f"body-cardnews-{int(time.time() * 1000)}-{index}.png"
                self._export_body_cardnews_png(
                    output_path,
                    heading=spec["heading"],
                    summary=spec["summary"],
                    index=index,
                    total=len(specs),
                )
                self.cardnews_image_paths.append(str(output_path))
            self.cardnews_list_label.configure(
                text="\n".join(f"{idx}. {Path(path).name}" for idx, path in enumerate(self.cardnews_image_paths, start=1)),
                text_color="#48d980",
            )
            self.cardnews_status_label.configure(
                text="카드뉴스 생성 완료. 본문 중간 섹션에 자동 반영했습니다.",
                text_color="#48d980",
            )
            self._insert_generated_cardnews_into_article(show_warning=False)
            self._save_ui_state()
        except Exception as exc:
            self.cardnews_status_label.configure(text="카드뉴스 생성 실패", text_color="#ff6b6b")
            messagebox.showerror("카드뉴스 생성 실패", str(exc))
        finally:
            active_style = self.cardnews_specs[self.active_cardnews_slide_index].get("style") if self.cardnews_specs else original_style
            self._apply_cardnews_style(active_style or original_style, refresh_preview=True)
            self.generate_cardnews_button.configure(state="normal", text="카드뉴스 생성 및 본문 반영")

    def _load_body_cardnews_slides(self, show_warning: bool = True) -> bool:
        article_html = self.article_editor.get("1.0", "end").strip()
        title = self.article_title_entry.get().strip() or self.generated_article_title or self._selected_or_manual_keyword()
        if not article_html or "생성된 글이 여기에 표시됩니다" in article_html:
            if show_warning:
                messagebox.showwarning("글 생성 필요", "먼저 3번에서 글을 생성하거나 본문을 입력해 주세요.")
            return False
        count = max(1, min(self._safe_int(self.writing_inline_images_count_menu.get(), 2), 4))
        self.cardnews_specs = self._body_cardnews_specs(article_html, title, count)
        self._merge_saved_cardnews_styles()
        self.active_cardnews_slide_index = 0
        self.cardnews_image_paths = []
        self.cardnews_list_label.configure(text="생성된 카드뉴스 없음", text_color="#6dadff")
        self._render_active_cardnews_slide()
        self.cardnews_status_label.configure(
            text=f"본문 H2를 바탕으로 카드뉴스 슬라이드 {len(self.cardnews_specs)}개를 자동 준비했습니다. 슬라이드별 디자인을 수정할 수 있습니다.",
            text_color="#48d980",
        )
        self._show_cardnews_preview()
        self._save_ui_state()
        return True

    def _move_cardnews_slide(self, direction: int) -> None:
        if not self.cardnews_specs:
            return
        self._save_active_cardnews_slide()
        self.active_cardnews_slide_index = max(
            0,
            min(len(self.cardnews_specs) - 1, self.active_cardnews_slide_index + direction),
        )
        self._render_active_cardnews_slide()
        self._show_cardnews_preview()

    def _default_cardnews_style(self) -> dict:
        return {
            "width": self.wordpress_settings.cardnews_width,
            "height": self.wordpress_settings.cardnews_height,
            "ratio": self.wordpress_settings.cardnews_ratio,
            "background_mode": self.wordpress_settings.cardnews_background_mode,
            "background_image_path": self.wordpress_settings.cardnews_background_image_path,
            "image_position": self.wordpress_settings.cardnews_image_position,
            "image_scale": self.wordpress_settings.cardnews_image_scale,
            "image_opacity": self.wordpress_settings.cardnews_image_opacity,
            "image_grayscale": self.wordpress_settings.cardnews_image_grayscale,
            "bg_color": self.wordpress_settings.cardnews_bg_color,
            "border_color": self.wordpress_settings.cardnews_border_color,
            "text_color": self.wordpress_settings.cardnews_text_color,
            "text_stroke_color": self.wordpress_settings.cardnews_text_stroke_color,
            "font_size": self.wordpress_settings.cardnews_font_size,
            "shadow": self.wordpress_settings.cardnews_shadow,
            "signature": self.wordpress_settings.cardnews_signature,
        }

    def _current_cardnews_style(self) -> dict:
        if not hasattr(self, "cardnews_width_entry"):
            return self._default_cardnews_style()
        return {
            "width": self._safe_int(self.cardnews_width_entry.get(), 1024),
            "height": self._safe_int(self.cardnews_height_entry.get(), 1024),
            "ratio": self.cardnews_ratio_menu.get(),
            "background_mode": self.cardnews_background_mode_menu.get(),
            "background_image_path": self.cardnews_background_image_path,
            "image_position": self.cardnews_image_position_menu.get(),
            "image_scale": round(float(self.cardnews_image_scale_var.get())),
            "image_opacity": round(float(self.cardnews_image_opacity_var.get())),
            "image_grayscale": bool(self.cardnews_image_grayscale_var.get()),
            "bg_color": self.cardnews_bg_color_menu.get(),
            "border_color": self.cardnews_border_color_menu.get(),
            "text_color": self.cardnews_text_color_menu.get(),
            "text_stroke_color": self.cardnews_text_stroke_menu.get(),
            "font_size": self._safe_int(self.cardnews_font_size_entry.get(), 78),
            "shadow": self.cardnews_shadow_menu.get(),
            "signature": self.cardnews_signature_entry.get().strip(),
        }

    def _apply_cardnews_style(self, style: dict | None, refresh_preview: bool = True) -> None:
        if not hasattr(self, "cardnews_width_entry"):
            return
        merged = self._default_cardnews_style()
        if isinstance(style, dict):
            merged.update({key: value for key, value in style.items() if value is not None})
        self._loading_cardnews_slide_style = True
        try:
            self.cardnews_width_entry.delete(0, "end")
            self.cardnews_width_entry.insert(0, str(merged.get("width", 1024)))
            self.cardnews_height_entry.delete(0, "end")
            self.cardnews_height_entry.insert(0, str(merged.get("height", 1024)))
            self.cardnews_ratio_menu.set(str(merged.get("ratio", "1:1")))
            self.cardnews_background_mode_menu.set(str(merged.get("background_mode", "단색 배경")))
            self.cardnews_bg_color_menu.set(str(merged.get("bg_color", "흰색")))
            self.cardnews_border_color_menu.set(str(merged.get("border_color", "파란색")))
            self.cardnews_text_color_menu.set(str(merged.get("text_color", "검정색")))
            self.cardnews_text_stroke_menu.set(str(merged.get("text_stroke_color", "없음")))
            self.cardnews_font_size_entry.delete(0, "end")
            self.cardnews_font_size_entry.insert(0, str(merged.get("font_size", 78)))
            self.cardnews_shadow_menu.set(str(merged.get("shadow", "없음")))
            self.cardnews_signature_entry.delete(0, "end")
            self.cardnews_signature_entry.insert(0, str(merged.get("signature", "BLOG HELPER CARD NEWS")))
            self.cardnews_background_image_path = str(merged.get("background_image_path", "") or "")
            self.cardnews_selected_image_label_text.set(
                Path(self.cardnews_background_image_path).name if self.cardnews_background_image_path else "선택된 파일 없음"
            )
            self.cardnews_image_position_menu.set(str(merged.get("image_position", "가운데")))
            self.cardnews_image_scale_var.set(float(merged.get("image_scale", 100) or 100))
            self.cardnews_image_opacity_var.set(float(merged.get("image_opacity", 35) or 35))
            self.cardnews_image_grayscale_var.set(bool(merged.get("image_grayscale", False)))
            if hasattr(self, "cardnews_image_scale_value_label"):
                self.cardnews_image_scale_value_label.configure(text=f"{round(float(self.cardnews_image_scale_var.get()))}%")
            if hasattr(self, "cardnews_image_opacity_value_label"):
                self.cardnews_image_opacity_value_label.configure(text=f"{round(float(self.cardnews_image_opacity_var.get()))}%")
        finally:
            self._loading_cardnews_slide_style = False
        if refresh_preview:
            self._show_cardnews_preview()

    def _current_cardnews_slide_styles(self) -> list[dict]:
        if self.cardnews_specs:
            try:
                self._save_active_cardnews_slide()
            except Exception:
                pass
            styles = [spec.get("style", self._default_cardnews_style()) for spec in self.cardnews_specs[:4]]
            return [style for style in styles if isinstance(style, dict)]
        return [self._current_cardnews_style()] if hasattr(self, "cardnews_width_entry") else list(self.wordpress_settings.cardnews_slide_styles or [])

    def _merge_saved_cardnews_styles(self) -> None:
        saved_styles = list(self.wordpress_settings.cardnews_slide_styles or [])
        for index, spec in enumerate(self.cardnews_specs):
            generated_style = spec.get("style") if isinstance(spec.get("style"), dict) else {}
            if index < len(saved_styles) and isinstance(saved_styles[index], dict):
                saved_style = dict(saved_styles[index])
                # 카드 테두리는 글마다 새 색상을 사용하고, 나머지 슬라이드별 설정은 복원합니다.
                if generated_style.get("border_color"):
                    saved_style["border_color"] = generated_style["border_color"]
                spec["style"] = saved_style
            elif generated_style:
                spec["style"] = dict(generated_style)
            else:
                spec["style"] = self._current_cardnews_style() if hasattr(self, "cardnews_width_entry") else self._default_cardnews_style()

    def _save_active_cardnews_slide(self) -> None:
        if not self.cardnews_specs:
            return
        index = max(0, min(self.active_cardnews_slide_index, len(self.cardnews_specs) - 1))
        if hasattr(self, "cardnews_heading_entry"):
            self.cardnews_specs[index]["heading"] = self.cardnews_heading_entry.get().strip() or "핵심 정보"
        if hasattr(self, "cardnews_summary_entry"):
            self.cardnews_specs[index]["summary"] = self.cardnews_summary_entry.get().strip() or "핵심 내용을 한눈에 보기 쉽게 정리했습니다."
        if hasattr(self, "cardnews_width_entry") and not getattr(self, "_loading_cardnews_slide_style", False):
            self.cardnews_specs[index]["style"] = self._current_cardnews_style()

    def _on_cardnews_slide_text_changed(self, event=None) -> None:
        self._mark_text_input_activity(event)
        if self._cardnews_text_preview_job is not None:
            self.after_cancel(self._cardnews_text_preview_job)
        self._cardnews_text_preview_job = self.after(900, self._run_cardnews_slide_text_update)

    def _run_cardnews_slide_text_update(self) -> None:
        self._cardnews_text_preview_job = None
        if self._defer_while_text_composing("_cardnews_text_preview_job", self._run_cardnews_slide_text_update, 1.2):
            return
        self._save_active_cardnews_slide()
        self._show_cardnews_preview()
        signature = self.cardnews_signature_entry.get().strip()
        slide_styles = self._current_cardnews_slide_styles()
        self.wordpress_settings.cardnews_signature = signature
        self.wordpress_settings.cardnews_slide_styles = slide_styles
        AppStateStore.update_fields(
            cardnews_signature=signature,
            cardnews_slide_styles=slide_styles,
        )

    def _render_active_cardnews_slide(self) -> None:
        if not hasattr(self, "cardnews_heading_entry"):
            return
        self.cardnews_heading_entry.delete(0, "end")
        self.cardnews_summary_entry.delete(0, "end")
        self.cardnews_signature_entry.delete(0, "end")
        if not self.cardnews_specs:
            self.cardnews_signature_entry.insert(0, self.wordpress_settings.cardnews_signature)
            self.cardnews_slide_label.configure(text="슬라이드 없음")
            self._show_cardnews_preview()
            return
        index = max(0, min(self.active_cardnews_slide_index, len(self.cardnews_specs) - 1))
        self.active_cardnews_slide_index = index
        spec = self.cardnews_specs[index]
        self._apply_cardnews_style(spec.get("style"), refresh_preview=False)
        self.cardnews_heading_entry.insert(0, spec.get("heading", ""))
        self.cardnews_summary_entry.insert(0, spec.get("summary", ""))
        self.cardnews_slide_label.configure(text=f"슬라이드 {index + 1} / {len(self.cardnews_specs)}")
        self._show_cardnews_preview()

    def _insert_generated_cardnews_into_article(self, show_warning: bool = True) -> bool:
        existing_paths = [Path(path) for path in self.cardnews_image_paths if Path(path).exists()]
        if not existing_paths:
            if show_warning:
                messagebox.showwarning("카드뉴스 없음", "먼저 카드뉴스 생성을 실행해 주세요.")
            return False
        title = self.article_title_entry.get().strip() or self.generated_article_title or "본문 카드뉴스"
        article_html = remove_cardnews_image_figures(self.article_editor.get("1.0", "end").strip())
        figures = [build_cardnews_image_figure(path, title, index) for index, path in enumerate(existing_paths, start=1)]
        updated_html = insert_inline_image_figures(article_html, figures)
        updated_html = compact_inline_image_sources_for_editor(updated_html, title)
        self.article_editor.delete("1.0", "end")
        self.article_editor.insert("1.0", updated_html)
        self.generated_article_html = updated_html
        self.cardnews_status_label.configure(text=f"본문에 카드뉴스 {len(existing_paths)}장을 자동 반영했습니다.", text_color="#48d980")
        self._save_ui_state()
        return True

    def _ensure_cardnews_ready_for_publish(self) -> bool:
        provider = self.writing_inline_images_provider_menu.get() if hasattr(self, "writing_inline_images_provider_menu") else ""
        enabled = self.inline_images_enabled_var.get() if hasattr(self, "inline_images_enabled_var") else False
        if not enabled or provider != "카드뉴스 생성":
            return True

        article_html = self.article_editor.get("1.0", "end").strip()
        if not article_html or "생성된 글이 여기에 표시됩니다" in article_html:
            return False

        if not self.cardnews_specs and not self._load_body_cardnews_slides(show_warning=False):
            return False

        existing_paths = [Path(path) for path in self.cardnews_image_paths if Path(path).exists()]
        expected_count = max(1, min(self._safe_int(self.writing_inline_images_count_menu.get(), 2), 4))
        if len(existing_paths) < min(expected_count, len(self.cardnews_specs)):
            self._generate_body_cardnews_images()
            existing_paths = [Path(path) for path in self.cardnews_image_paths if Path(path).exists()]
        elif "blog-helper-cardnews-image" not in article_html:
            self._insert_generated_cardnews_into_article(show_warning=False)

        if not existing_paths:
            self.publish_status_label.configure(
                text="본문 카드뉴스 PNG를 만들지 못해 업로드를 중단했습니다.",
                text_color="#ff6b6b",
            )
            return False
        return "blog-helper-cardnews-image" in self.article_editor.get("1.0", "end")

    def _body_cardnews_specs(self, article_html: str, fallback_title: str, count: int) -> list[dict[str, str]]:
        sections: list[dict[str, str]] = []
        h2_matches = list(re.finditer(r"<h2[^>]*>(.*?)</h2>", article_html, flags=re.I | re.S))
        for index, match in enumerate(h2_matches):
            heading = self._clean_cardnews_text(match.group(1))
            section_start = match.end()
            section_end = h2_matches[index + 1].start() if index + 1 < len(h2_matches) else len(article_html)
            section_text = plain_text_from_html(article_html[section_start:section_end], limit=260)
            summary = self._one_line_summary(section_text or plain_text_from_html(article_html, limit=260))
            if heading:
                sections.append({"heading": heading, "summary": summary})
            if len(sections) >= count:
                break
        if not sections:
            sections.append(
                {
                    "heading": fallback_title or self._selected_or_manual_keyword() or "핵심 정보",
                    "summary": self._one_line_summary(plain_text_from_html(article_html, limit=260)),
                }
            )
        selected_sections = sections[:count]
        border_colors = random.sample(
            CARDNEWS_BORDER_COLOR_PALETTE,
            k=min(len(selected_sections), len(CARDNEWS_BORDER_COLOR_PALETTE)),
        )
        for index, section in enumerate(selected_sections):
            style = (
                self._current_cardnews_style()
                if hasattr(self, "cardnews_width_entry")
                else self._default_cardnews_style()
            )
            style["border_color"] = border_colors[index]
            section["style"] = style
        return selected_sections

    def _one_line_summary(self, text: str) -> str:
        text = self._clean_cardnews_text(text)
        parts = re.split(r"(?<=[.!?。])\s+|\n+", text)
        summary = next((part.strip() for part in parts if len(part.strip()) >= 12), text)
        return summary[:58].rstrip(" ,.;:·-") or "핵심 내용을 한눈에 보기 쉽게 정리했습니다."

    def _clean_cardnews_text(self, text: str) -> str:
        text = unescape(re.sub(r"<[^>]+>", " ", text or ""))
        return re.sub(r"\s+", " ", text).strip()

    def _export_body_cardnews_png(self, destination: Path, heading: str, summary: str, index: int, total: int) -> Path:
        width = max(400, self._safe_int(self.cardnews_width_entry.get(), 1024))
        height = max(400, self._safe_int(self.cardnews_height_entry.get(), 1024))
        svg_markup = self._build_body_cardnews_svg(width, height, heading, summary, index, total)
        destination.parent.mkdir(parents=True, exist_ok=True)
        return render_svg_to_png(
            svg_markup,
            destination,
            max(width, height),
            "카드뉴스",
        )

    def _build_body_cardnews_svg(self, width: int, height: int, heading: str, summary: str, index: int, total: int) -> str:
        border_color = self._thumbnail_color_value(self.cardnews_border_color_menu.get()) or "#3468e8"
        bg_color = self._thumbnail_color_value(self.cardnews_bg_color_menu.get()) or "#ffffff"
        text_color = self._thumbnail_color_value(self.cardnews_text_color_menu.get()) or "#111111"
        stroke_color = self._thumbnail_color_value(self.cardnews_text_stroke_menu.get())
        shadow_mode = self.cardnews_shadow_menu.get()
        signature = self.cardnews_signature_entry.get().strip()
        heading_font_size = max(28, self._safe_int(self.cardnews_font_size_entry.get(), 78))
        summary_font_size = max(20, round(heading_font_size * 0.44))
        heading_lines = self._wrap_text_for_svg(heading, width - 190, heading_font_size, 3)
        summary_lines = self._wrap_text_for_svg(summary, width - 220, summary_font_size, 2)
        elements = [
            f'<svg xmlns="http://www.w3.org/2000/svg" width="{width}" height="{height}" viewBox="0 0 {width} {height}">',
            f'<rect width="100%" height="100%" rx="0" fill="{bg_color}" />',
        ]
        if self.cardnews_image_grayscale_var.get():
            elements.append(
                '<defs><filter id="blog-helper-card-gray"><feColorMatrix type="matrix" '
                'values="0.299 0.587 0.114 0 0 0.299 0.587 0.114 0 0 0.299 0.587 0.114 0 0 0 0 0 1 0"/></filter></defs>'
            )
        if self.cardnews_background_mode_menu.get() == "선택 이미지 사용" and self.cardnews_background_image_path:
            image_data_url = self._cardnews_background_data_url()
            if image_data_url:
                source_width, source_height = self._cardnews_background_source_size()
                image_width, image_height, image_x, image_y = self._cardnews_image_geometry(width, height, source_width, source_height)
                opacity = max(0, min(100, round(float(self.cardnews_image_opacity_var.get())))) / 100
                filter_attr = ' filter="url(#blog-helper-card-gray)"' if self.cardnews_image_grayscale_var.get() else ""
                elements.append(
                    f'<image href="{image_data_url}" x="{image_x}" y="{image_y}" width="{image_width}" height="{image_height}" '
                    f'preserveAspectRatio="xMidYMid meet" opacity="{opacity:.2f}"{filter_attr} />'
                )
                elements.append('<rect width="100%" height="100%" fill="#ffffff" opacity="0.32" />')
        elements.extend(
            [
                f'<rect x="{width * 0.057}" y="{height * 0.057}" width="{width * 0.886}" height="{height * 0.886}" fill="none" stroke="{border_color}" stroke-width="{max(12, min(width, height) * 0.033)}" />',
                f'<text x="{width * 0.914}" y="{height * 0.11}" text-anchor="end" font-family="Apple SD Gothic Neo, Noto Sans CJK KR, sans-serif" font-size="{max(18, min(width, height) * 0.027)}" font-weight="800" fill="{border_color}">{index}/{total}</text>',
            ]
        )
        heading_line_gap = heading_font_size * 1.18
        start_y = (height * 0.38) - ((len(heading_lines) - 1) * heading_line_gap / 2)
        for line_index, line in enumerate(heading_lines):
            if shadow_mode != "없음":
                shadow_offset = 4 if shadow_mode == "약한 그림자" else 9
                elements.append(
                    f'<text x="{(width / 2) + shadow_offset}" y="{start_y + (line_index * heading_line_gap) + shadow_offset}" text-anchor="middle" dominant-baseline="middle" '
                    f'font-family="Apple SD Gothic Neo, Noto Sans CJK KR, sans-serif" font-size="{heading_font_size}" font-weight="900" fill="#000000">{escape(line)}</text>'
                )
            stroke_attrs = (
                f' stroke="{stroke_color}" stroke-width="{max(3, heading_font_size // 16)}" stroke-linejoin="round" paint-order="stroke fill"'
                if stroke_color
                else ""
            )
            elements.append(
                f'<text x="{width / 2}" y="{start_y + (line_index * heading_line_gap)}" text-anchor="middle" dominant-baseline="middle" '
                f'font-family="Apple SD Gothic Neo, Noto Sans CJK KR, sans-serif" font-size="{heading_font_size}" font-weight="900" fill="{text_color}"{stroke_attrs}>{escape(line)}</text>'
            )
        summary_y = height * 0.68
        summary_line_gap = summary_font_size * 1.25
        summary_box_height = (summary_font_size * 2.8) + ((len(summary_lines) - 1) * summary_line_gap)
        elements.append(f'<rect x="{width * 0.127}" y="{summary_y - (summary_box_height / 2)}" width="{width * 0.746}" height="{summary_box_height}" rx="{max(16, min(width, height) * 0.029)}" fill="#ffffff" opacity="0.72" />')
        for line_index, line in enumerate(summary_lines):
            elements.append(
                f'<text x="{width / 2}" y="{summary_y + ((line_index - ((len(summary_lines) - 1) / 2)) * summary_line_gap)}" text-anchor="middle" dominant-baseline="middle" '
                f'font-family="Apple SD Gothic Neo, Noto Sans CJK KR, sans-serif" font-size="{summary_font_size}" font-weight="700" fill="#303845">{escape(line)}</text>'
            )
        if signature:
            elements.append(
                f'<text x="{width / 2}" y="{height * 0.9}" text-anchor="middle" font-family="Apple SD Gothic Neo, Noto Sans CJK KR, sans-serif" '
                f'font-size="{max(18, min(width, height) * 0.029)}" font-weight="800" fill="{border_color}">{escape(signature)}</text>'
            )
        elements.append("</svg>")
        return "\n".join(elements)

    def _wrap_text_for_svg(self, text: str, max_width: int, font_size: int, max_lines: int) -> list[str]:
        font = tkfont.Font(family="Apple SD Gothic Neo", size=font_size, weight="bold")
        words = list(text.strip()) if not re.search(r"\s", text.strip()) else text.strip().split()
        lines: list[str] = []
        current = ""
        for word in words:
            separator = "" if not re.search(r"\s", text.strip()) else " "
            candidate = f"{current}{separator}{word}".strip() if current else word
            if font.measure(candidate) <= max_width:
                current = candidate
                continue
            if current:
                lines.append(current)
            current = word
            if len(lines) >= max_lines:
                break
        if current and len(lines) < max_lines:
            lines.append(current)
        if not lines:
            lines = [text[:18] or "핵심 정보"]
        if len(lines) == max_lines and font.measure(lines[-1]) > max_width:
            while lines[-1] and font.measure(lines[-1] + "...") > max_width:
                lines[-1] = lines[-1][:-1]
            lines[-1] = lines[-1].rstrip() + "..."
        return lines[:max_lines]

    def _build_thumbnail_svg(self, width: int, height: int, font_size: int) -> str:
        text_value = self.thumbnail_prompt_preview.get("1.0", "end").strip()
        bg_color = self._thumbnail_color_value(self.thumbnail_bg_color_menu.get())
        border_color = self._thumbnail_color_value(self.thumbnail_border_color_menu.get())
        text_color = self._thumbnail_color_value(self.thumbnail_text_color_menu.get())
        stroke_color = self._thumbnail_color_value(self.thumbnail_text_stroke_menu.get())
        shadow_mode = self.thumbnail_shadow_menu.get()
        lines = self._thumbnail_text_lines(text_value, width, font_size)
        font = tkfont.Font(family="Apple SD Gothic Neo", size=font_size, weight="bold")
        line_height = max(font_size * 1.18, font.metrics("linespace") * 0.92)
        center_x = width / 2
        first_y = (height / 2) - ((len(lines) - 1) * line_height / 2)
        elements: list[str] = [
            f'<svg xmlns="http://www.w3.org/2000/svg" width="{width}" height="{height}" viewBox="0 0 {width} {height}">',
        ]
        if self.thumbnail_image_grayscale_var.get():
            elements.append(
                '<defs><filter id="blog-helper-gray"><feColorMatrix type="matrix" '
                'values="0.299 0.587 0.114 0 0 0.299 0.587 0.114 0 0 0.299 0.587 0.114 0 0 0 0 0 1 0"/></filter></defs>'
            )
        elements.extend([
            f'<rect width="100%" height="100%" fill="{bg_color}" />',
        ])

        if self.thumbnail_background_mode_menu.get() == "선택 이미지 사용" and self.thumbnail_background_image_path:
            image_data_url = self._thumbnail_background_data_url()
            if image_data_url:
                source_width, source_height = self._thumbnail_background_source_size()
                image_width, image_height, image_x, image_y = self._thumbnail_image_geometry(width, height, source_width, source_height)
                opacity = max(0, min(100, round(float(self.thumbnail_image_opacity_var.get())))) / 100
                filter_attr = ' filter="url(#blog-helper-gray)"' if self.thumbnail_image_grayscale_var.get() else ""
                elements.append(
                    f'<image href="{image_data_url}" x="{image_x}" y="{image_y}" width="{image_width}" height="{image_height}" '
                    f'preserveAspectRatio="xMidYMid meet" opacity="{opacity:.2f}"{filter_attr} />'
                )

        if border_color:
            border_width = max(8, width // 24)
            half = border_width / 2
            rect_width = width - border_width
            rect_height = height - border_width
            elements.append(
                f'<rect x="{half}" y="{half}" width="{rect_width}" height="{rect_height}" '
                f'fill="none" stroke="{border_color}" stroke-width="{border_width}" />'
            )

        def add_text(fill: str, x_offset: float = 0, y_offset: float = 0, stroke: str = "", stroke_width: int = 0) -> None:
            stroke_attrs = f' stroke="{stroke}" stroke-width="{stroke_width}" stroke-linejoin="round" paint-order="stroke fill"' if stroke else ""
            for index, line in enumerate(lines):
                y = first_y + (index * line_height)
                elements.append(
                    f'<text x="{center_x + x_offset}" y="{y + y_offset}" text-anchor="middle" dominant-baseline="middle" '
                    f'font-family="Apple SD Gothic Neo, Noto Sans CJK KR, sans-serif" font-size="{font_size}" '
                    f'font-weight="800" fill="{fill}"{stroke_attrs}>'
                    f'{escape(line)}</text>'
                )

        if shadow_mode != "없음":
            shadow_offset = 3 if shadow_mode == "약한 그림자" else 7
            add_text("#000000", shadow_offset, shadow_offset)
        if stroke_color:
            add_text(text_color, stroke=stroke_color, stroke_width=max(3, font_size // 14))
        else:
            add_text(text_color)

        elements.append("</svg>")
        return "\n".join(elements)

    def _thumbnail_background_data_url(self) -> str:
        path = Path(self.thumbnail_background_image_path)
        if not path.exists():
            return ""
        suffix = path.suffix.lower()
        mime_type = {
            ".jpg": "image/jpeg",
            ".jpeg": "image/jpeg",
            ".gif": "image/gif",
            ".webp": "image/webp",
            ".png": "image/png",
        }.get(suffix, "image/png")
        encoded = base64.b64encode(path.read_bytes()).decode("ascii")
        return f"data:{mime_type};base64,{encoded}"

    def _thumbnail_background_source_size(self) -> tuple[int, int]:
        try:
            image = tk.PhotoImage(file=self.thumbnail_background_image_path)
            return max(1, image.width()), max(1, image.height())
        except tk.TclError:
            return 1, 1

    def _cardnews_background_data_url(self) -> str:
        path = Path(self.cardnews_background_image_path)
        if not path.exists():
            return ""
        suffix = path.suffix.lower()
        mime_type = {
            ".jpg": "image/jpeg",
            ".jpeg": "image/jpeg",
            ".gif": "image/gif",
            ".webp": "image/webp",
            ".png": "image/png",
        }.get(suffix, "image/png")
        encoded = base64.b64encode(path.read_bytes()).decode("ascii")
        return f"data:{mime_type};base64,{encoded}"

    def _cardnews_background_source_size(self) -> tuple[int, int]:
        try:
            image = tk.PhotoImage(file=self.cardnews_background_image_path)
            return max(1, image.width()), max(1, image.height())
        except tk.TclError:
            return 1, 1

    def _thumbnail_canvas_screen_position(self) -> tuple[int, int]:
        parent_canvas = getattr(self.writing_scroll, "_parent_canvas", None)
        if parent_canvas is None:
            return self.thumbnail_preview_canvas.winfo_rootx(), self.thumbnail_preview_canvas.winfo_rooty()

        x_offset = 0
        y_offset = 0
        widget = self.thumbnail_preview_canvas
        while widget is not None and widget != self.writing_scroll:
            x_offset += widget.winfo_x()
            y_offset += widget.winfo_y()
            widget = widget.master

        x = parent_canvas.winfo_rootx() + x_offset - int(parent_canvas.canvasx(0))
        y = parent_canvas.winfo_rooty() + y_offset - int(parent_canvas.canvasy(0))
        return int(x), int(y)

    def _labeled_entry(self, parent, row: int, label: str, placeholder: str) -> ctk.CTkEntry:
        label_widget = ctk.CTkLabel(
            parent,
            text=label,
            font=ctk.CTkFont(size=16, weight="bold"),
        )
        label_widget.grid(row=row, column=0, padx=24, pady=(0 if row == 1 else 18, 8), sticky="w")

        entry = ctk.CTkEntry(
            parent,
            height=56,
            corner_radius=16,
            fg_color="#3b4658",
            border_width=0,
            placeholder_text=placeholder,
            font=ctk.CTkFont(size=16, weight="bold"),
        )
        entry.grid(row=row + 1, column=0, padx=24, sticky="ew")
        return entry

    def _labeled_option_menu(self, parent, row: int, label: str, values: list[str], command: Callable[[str], None]):
        label_widget = ctk.CTkLabel(
            parent,
            text=label,
            font=ctk.CTkFont(size=16, weight="bold"),
        )
        label_widget.grid(row=row, column=0, padx=24, pady=(0 if row == 8 else 18, 8), sticky="w")

        menu = ctk.CTkOptionMenu(
            parent,
            values=values,
            height=50,
            corner_radius=16,
            fg_color="#3b4658",
            button_color="#3b4658",
            button_hover_color="#49586d",
            dropdown_fg_color="#273142",
            dropdown_hover_color="#3468e8",
            font=ctk.CTkFont(size=15, weight="bold"),
            dropdown_font=ctk.CTkFont(size=14),
            command=command,
        )
        menu.grid(row=row + 1, column=0, padx=24, sticky="ew")
        return menu

    def _populate_wordpress_fields(self) -> None:
        if hasattr(self, "theme_menu"):
            self.theme_menu.set(self.wordpress_settings.app_theme or "블랙테마")
        if hasattr(self, "app_title_var"):
            self.app_title_var.set(self.wordpress_settings.app_title or "현기쿠")
        if hasattr(self, "app_title_display_label"):
            self.app_title_display_label.configure(text=self.wordpress_settings.app_title or "현기쿠")
        if hasattr(self, "sidebar_title"):
            self.sidebar_title.configure(text=self.wordpress_settings.app_title or "현기쿠")
        self._apply_sidebar_menu_labels(self.wordpress_settings.sidebar_menu_labels)
        self.blog_url_entry.insert(0, self.wordpress_settings.blog_url)
        self.username_entry.insert(0, self.wordpress_settings.username)
        self.password_entry.insert(0, self.wordpress_settings.app_password)
        self.category_menu.configure(values=self._category_names())
        self.category_menu.set(self.wordpress_settings.category_name or "카테고리 없음")
        self._refresh_category_checkboxes()
        self.post_mode_menu.set(self.wordpress_settings.post_mode)
        self.webmaster_naver_var.set(self.wordpress_settings.webmaster_submit_naver)
        self.webmaster_daum_var.set(self.wordpress_settings.webmaster_submit_daum)
        self.webmaster_google_var.set(self.wordpress_settings.webmaster_submit_google)
        self.webmaster_completion_message_var.set(
            self.wordpress_settings.webmaster_completion_message
        )
        self.webmaster_completion_message_switch.configure(
            text=(
                "완료메세지 ON"
                if self.wordpress_settings.webmaster_completion_message
                else "완료메세지 OFF"
            )
        )
        self.gpt_api_entry.insert(0, "OpenAI")
        self.gpt_secret_entry.insert(0, self.wordpress_settings.gpt_api_key)
        self.gpt_model_menu.set(self.wordpress_settings.gpt_model)
        self.gemini_secret_entry.insert(0, self.wordpress_settings.gemini_api_key)
        self.gemini_model_menu.set(self.wordpress_settings.gemini_model)
