    def _save_wordpress_settings(self) -> None:
        try:
            settings = self._read_wordpress_settings()
            self._validate_wordpress_inputs(settings, allow_empty_password=False)
            self.wordpress_settings = settings
            AppStateStore.save(settings)
            self._set_wp_status("● 설정 저장 완료", "#48d980")
            self._update_quick_status(
                "설정 저장됨",
                "Application Password를 입력한 뒤 검사 버튼으로 연결 확인을 진행해 주세요.",
                "#48d980",
            )
        except RuntimeError as exc:
            messagebox.showerror("설정 오류", str(exc))

    def _save_gpt_settings(self) -> None:
        settings = self._read_wordpress_settings()
        if not settings.gpt_api_key:
            messagebox.showerror("입력 오류", "GPT API 키를 입력해 주세요.")
            return
        self.wordpress_settings = settings
        AppStateStore.save(settings)
        self.gpt_status_label.configure(text="● GPT API 저장 완료", text_color="#48d980")
        self._update_quick_status("GPT API 저장됨", f"기본 모델: {settings.gpt_model}", "#48d980")

    def _test_gpt_connection(self) -> None:
        if self.gpt_test_worker and self.gpt_test_worker.is_alive():
            messagebox.showinfo("진행 중", "GPT API 연결 확인이 이미 진행 중입니다.")
            return

        settings = self._read_wordpress_settings()
        if not settings.gpt_api_key:
            messagebox.showerror("입력 오류", "GPT API 키를 입력해 주세요.")
            return

        self.wordpress_settings = settings
        AppStateStore.save(settings)
        self.gpt_status_label.configure(text="● GPT API 연결 확인 중...", text_color="#6dadff")
        self._update_quick_status("GPT API 검사 중", "OpenAI API 응답을 확인하고 있습니다.", "#6dadff")
        self.gpt_test_button.configure(state="disabled", text="확인 중...")
        self.gpt_test_worker = OpenAITestWorker(settings.gpt_api_key, settings.gpt_model, self.result_queue)
        self.gpt_test_worker.start()

    def _save_gemini_settings(self) -> None:
        settings = self._read_wordpress_settings()
        if not settings.gemini_api_key:
            messagebox.showerror("입력 오류", "제미나이 API 키를 입력해 주세요.")
            return
        self.wordpress_settings = settings
        AppStateStore.save(settings)
        self.gemini_status_label.configure(text="● 제미나이 API 저장 완료", text_color="#48d980")
        self._update_quick_status("제미나이 API 저장됨", f"기본 모델: {settings.gemini_model}", "#48d980")

    def _save_imagen_settings(self) -> None:
        settings = self._read_wordpress_settings()
        needs_imagen_for_inline = settings.inline_images_enabled and settings.inline_images_provider != "카드뉴스 생성"
        if (settings.cardnews_enabled or needs_imagen_for_inline) and not settings.imagen_api_key:
            messagebox.showerror("입력 오류", "본문 이미지 자동 생성을 사용하려면 Imagen API 키를 입력해 주세요.")
            return
        self.wordpress_settings = settings
        AppStateStore.save(settings)
        status = "사용" if settings.inline_images_enabled else "사용 안 함"
        self.imagen_status_label.configure(text="● Imagen API 저장 완료", text_color="#48d980")
        self._update_quick_status(
            "Imagen API 저장됨",
            f"모델: {settings.imagen_model}\n본문 이미지: {status}, {settings.inline_images_count}장 · {settings.inline_images_provider}",
            "#48d980",
        )

    def _save_codex_settings(self) -> None:
        settings = self._read_wordpress_settings()
        if settings.codex_cli_enabled:
            detected = resolve_codex_cli_path(settings.codex_cli_path)
            if not detected:
                messagebox.showerror("입력 오류", "Codex CLI를 찾지 못했습니다. 자동감지 또는 로그인을 먼저 진행해 주세요.")
                return
            settings.codex_cli_path = detected
            self.codex_cli_path_entry.delete(0, "end")
            self.codex_cli_path_entry.insert(0, detected)
        self.wordpress_settings = settings
        AppStateStore.save(settings)
        self.codex_status_label.configure(text="● Codex CLI 설정 저장 완료", text_color="#48d980")
        self._update_quick_status(
            "Codex CLI 저장됨",
            f"경로: {settings.codex_cli_path or 'codex'}\n제한 시간: {settings.codex_cli_timeout}초",
            "#48d980",
        )

