    def _open_tistory_write_page(self) -> None:
        settings = self._read_wordpress_settings()
        settings.tistory_automation_prompt = self._current_tistory_automation_prompt()
        write_url = self._build_tistory_write_url(settings)
        if not write_url:
            messagebox.showerror("입력 오류", "티스토리 블로그 주소 또는 글쓰기 URL을 먼저 입력해 주세요.")
            return
        AppStateStore.save(settings)
        login_url = build_tistory_login_url(write_url)
        self._open_source_url(login_url)
        self.tistory_status_label.configure(text="● 티스토리 로그인 화면 열림", text_color="#6dadff")
        self._update_quick_status("티스토리 로그인 확인", "브라우저에서 로그인 후 글쓰기 화면으로 이동됩니다.", "#6dadff")

    def _build_tistory_write_url(self, settings: WordPressSettings) -> str:
        return build_tistory_write_url(settings.tistory_blog_url, settings.tistory_write_url)

    def _confirm_tistory_login_before_automation(self, write_url: str) -> bool:
        login_url = build_tistory_login_url(write_url)
        self._open_source_url(login_url)
        return messagebox.askokcancel(
            "티스토리 로그인 확인",
            "브라우저에서 티스토리 로그인을 완료해 주세요.\n\n"
            "로그인이 끝나고 글쓰기 화면으로 이동된 뒤 [확인]을 누르면 자동입력을 시작합니다.\n"
            "아직 로그인 전이면 [취소]를 누른 뒤 다시 실행해 주세요.",
        )

