    def _save_prompt_settings(self) -> None:
        try:
            prompt_values = self._platform_prompt_values_from_boxes()
            PromptFileStore.save_values(prompt_values)
            PromptFileStore.save_prompt_sets(self.wordpress_settings.prompt_sets)
            settings = self._read_wordpress_settings()
            self.wordpress_settings = settings
            AppStateStore.save(settings, save_secrets=False)
            self._refresh_prompt_set_menus()
            self.prompt_feedback_label.configure(
                text=f"프롬프트 저장 완료: {PROMPT_STORAGE_DIR}",
                text_color="#48d980",
            )
            self._update_quick_status(
                "프롬프트 저장 완료",
                f"플랫폼별 프롬프트와 제목별 프롬프트 세트를 저장했습니다.\n{PROMPT_STORAGE_DIR}",
                "#48d980",
            )
        except Exception as exc:
            self.prompt_feedback_label.configure(text="프롬프트 저장 실패", text_color="#ff6b6b")
            messagebox.showerror("프롬프트 저장 실패", str(exc))

    def _open_prompt_folder(self) -> None:
        try:
            PromptFileStore._ensure_directory()
            folder = PROMPT_DIR if PROMPT_DIR.exists() else PROMPT_STORAGE_DIR
            self._open_source_url(folder.as_uri())
        except OSError as exc:
            messagebox.showerror("폴더 열기 실패", str(exc))

    def _reset_prompt_settings(self) -> None:
        defaults = {
            "wordpress": (DEFAULT_WORDPRESS_TITLE_PROMPT, DEFAULT_WORDPRESS_ARTICLE_PROMPT),
            "tistory": (DEFAULT_TISTORY_TITLE_PROMPT, DEFAULT_TISTORY_ARTICLE_PROMPT),
            "naver_blog": (DEFAULT_NAVER_BLOG_TITLE_PROMPT, DEFAULT_NAVER_BLOG_TOPIC_PROMPT),
            "blogspot": (DEFAULT_BLOGSPOT_TITLE_PROMPT, DEFAULT_BLOGSPOT_ARTICLE_PROMPT),
        }
        for platform, (title_prompt, article_prompt) in defaults.items():
            self.prompt_title_boxes[platform].delete("1.0", "end")
            self.prompt_title_boxes[platform].insert("1.0", title_prompt)
            self.prompt_article_boxes[platform].delete("1.0", "end")
            self.prompt_article_boxes[platform].insert("1.0", article_prompt)
        if self.tistory_automation_prompt_box:
            self.tistory_automation_prompt_box.delete("1.0", "end")
            self.tistory_automation_prompt_box.insert("1.0", DEFAULT_TISTORY_AUTOMATION_PROMPT)
        if self.naver_kin_answer_prompt_box:
            self.naver_kin_answer_prompt_box.delete("1.0", "end")
            self.naver_kin_answer_prompt_box.insert("1.0", DEFAULT_NAVER_KIN_ANSWER_PROMPT)
        self.wordpress_settings.wordpress_title_prompt_template = DEFAULT_WORDPRESS_TITLE_PROMPT
        self.wordpress_settings.wordpress_article_prompt_template = DEFAULT_WORDPRESS_ARTICLE_PROMPT
        self.wordpress_settings.tistory_title_prompt_template = DEFAULT_TISTORY_TITLE_PROMPT
        self.wordpress_settings.tistory_article_prompt_template = DEFAULT_TISTORY_ARTICLE_PROMPT
        self.wordpress_settings.tistory_automation_prompt = DEFAULT_TISTORY_AUTOMATION_PROMPT
        self.wordpress_settings.naver_blog_title_prompt = DEFAULT_NAVER_BLOG_TITLE_PROMPT
        self.wordpress_settings.naver_blog_topic_prompt = DEFAULT_NAVER_BLOG_TOPIC_PROMPT
        self.wordpress_settings.naver_kin_answer_prompt = DEFAULT_NAVER_KIN_ANSWER_PROMPT
        self.wordpress_settings.blogspot_title_prompt_template = DEFAULT_BLOGSPOT_TITLE_PROMPT
        self.wordpress_settings.blogspot_article_prompt_template = DEFAULT_BLOGSPOT_ARTICLE_PROMPT
        self.wordpress_settings.title_prompt_template = DEFAULT_WORDPRESS_TITLE_PROMPT
        self.wordpress_settings.article_prompt_template = DEFAULT_WORDPRESS_ARTICLE_PROMPT
        self.wordpress_settings.prompt_sets = PromptFileStore.default_prompt_sets(self.wordpress_settings)
        self.wordpress_settings.selected_prompt_id = self.wordpress_settings.prompt_sets[0]["id"]
        self.wordpress_settings.naver_blog_prompt_id = "naver-blog-default"
        self.wordpress_settings.naver_blog_prompt_type = "기본"
        for platform in ("wordpress", "tistory", "naver_blog", "blogspot"):
            active = next((item for item in self.wordpress_settings.prompt_sets if item.get("platform") == platform), None)
            if active:
                self.active_prompt_set_ids[platform] = str(active.get("id"))
        self._refresh_prompt_set_menus()
        self._load_prompt_set_into_boxes(self.active_prompt_platform)
        PromptFileStore.save_settings(self.wordpress_settings)
        AppStateStore.save(self.wordpress_settings, save_secrets=False)
        self.prompt_feedback_label.configure(text=f"기본값 TXT 복원 완료: {PROMPT_STORAGE_DIR}", text_color="#9aa7bb")
        self._update_quick_status(
            "프롬프트 기본값 복원",
            f"플랫폼별 기본 프롬프트를 TXT 파일로 복원했습니다.\n{PROMPT_STORAGE_DIR}",
            "#9aa7bb",
        )

    def _test_wordpress_connection(self) -> None:
        if self.wp_test_worker and self.wp_test_worker.is_alive():
            messagebox.showinfo("진행 중", "워드프레스 연결 테스트가 진행 중입니다.")
            return

        try:
            settings = self._read_wordpress_settings()
            self._validate_wordpress_inputs(settings, allow_empty_password=False)
            self.wordpress_settings = settings
            AppStateStore.save(settings)
            self._set_wp_status("● 워드프레스 연결 검사 중...", "#6dadff")
            self._update_quick_status("연결 검사 중", "워드프레스 REST API 응답을 확인하고 있습니다.", "#6dadff")
            self.wp_test_button.configure(state="disabled", text="검사 중...")
            self.wp_test_worker = WordPressTestWorker(settings, self.result_queue)
            self.wp_test_worker.start()
        except RuntimeError as exc:
            messagebox.showerror("입력 오류", str(exc))

    def _set_trend_keyword_buttons_state(self, state: str = "normal") -> None:
        if hasattr(self, "daum_keywords_button"):
            self.daum_keywords_button.configure(state=state, text="다음 실시간")
        if hasattr(self, "signal_keywords_button"):
            self.signal_keywords_button.configure(state=state, text="시그널 키워드")
        if hasattr(self, "newneek_keywords_button"):
            self.newneek_keywords_button.configure(state=state, text="뉴닉 키워드")

    def start_analysis(self) -> None:
        keyword = self.topic_entry.get().strip()
        enabled_sources = [source for source, var in self.source_vars.items() if var.get()]
        if not keyword:
            messagebox.showwarning("입력 필요", "먼저 쓰고 싶은 주제를 입력해 주세요.")
            return
        if not enabled_sources:
            messagebox.showwarning("소스 선택 필요", "최소 1개의 분석 소스를 선택해 주세요.")
            return
        if self.analysis_worker and self.analysis_worker.is_alive():
            messagebox.showinfo("진행 중", "현재 키워드 분석이 진행 중입니다.")
            return

        self._stop_writing_auto_progress()
        self._reset_writing_section_completion()
        self.current_keyword = keyword
        self.current_insights = []
        self.daum_reference_map = {}
        self.signal_reference_map = {}
        self.newneek_reference_map = {}
        self.collected_reference_map = {}
        self.selected_keyword_var.set("")
        if hasattr(self, "manual_keyword_entry"):
            self.manual_keyword_entry.delete(0, "end")
        self._clear_keyword_choices()
        self._clear_result_cards()
        self.article_progress_bar.stop()
        self.article_progress_bar.configure(mode="determinate")
        self.article_progress_bar.set(0)
        self.article_progress_label.configure(text="키워드를 선택한 뒤 글 작성 버튼을 누르면 진행 상황이 표시됩니다.")
        self.generate_article_button.configure(state="normal", text="다음: 글 작성")
        self.article_summary_label.configure(
            text="아직 생성된 글이 없습니다. 키워드를 선택한 뒤 글 작성을 실행해 주세요.",
            text_color="#c4cede",
        )
        self.article_title_entry.delete(0, "end")
        self.article_editor.delete("1.0", "end")
        self.article_editor.insert("1.0", "생성된 글이 여기에 표시됩니다. 내용을 직접 수정한 뒤 업로드할 수 있습니다.")
        self.thumbnail_prompt_preview.delete("1.0", "end")
        self.thumbnail_prompt_preview.insert("1.0", "썸네일에 들어갈 메인 문구를 직접 입력하거나, 글 제목을 자동으로 가져올 수 있습니다.")
        self.thumbnail_saved_path = ""
        self._generate_thumbnail_preview()
        self._open_writing_section("topic")
        self.progress_bar.configure(mode="determinate")
        self.progress_bar.set(0.03)
        self.keyword_status_label.configure(text="키워드 분석 스레드 시작 중...")
        self._set_writing_progress(1, f"'{keyword}' 추천 키워드를 분석하고 있습니다.", 0.03)
        self.find_keywords_button.configure(state="disabled", text="분석 중...")
        self._set_trend_keyword_buttons_state("disabled")
        self._save_ui_state()

        self.analysis_worker = AnalysisWorker(keyword, enabled_sources, self.result_queue)
        self.analysis_worker.start()

    def load_daum_keywords(self) -> None:
        if self.daum_worker and self.daum_worker.is_alive():
            messagebox.showinfo("진행 중", "다음 실시간 검색어를 가져오는 중입니다.")
            return
        if self.signal_worker and self.signal_worker.is_alive():
            messagebox.showinfo("진행 중", "시그널 실시간 검색어를 가져오는 중입니다.")
            return
        if self.newneek_worker and self.newneek_worker.is_alive():
            messagebox.showinfo("진행 중", "뉴닉 키워드를 가져오는 중입니다.")
            return

        self._stop_writing_auto_progress()
        self._reset_writing_section_completion()
        self.daum_reference_map = {}
        self.signal_reference_map = {}
        self.newneek_reference_map = {}
        self.collected_reference_map = {}
        self.current_keyword = "다음 실시간 검색어"
        self.current_insights = []
        self.selected_keyword_var.set("")
        if hasattr(self, "manual_keyword_entry"):
            self.manual_keyword_entry.delete(0, "end")
        self._clear_keyword_choices()
        self._clear_result_cards()
        self.progress_bar.configure(mode="indeterminate")
        self.progress_bar.start()
        self.keyword_status_label.configure(text="다음 실시간 검색어 수집 중...")
        self._set_writing_progress(1, "다음 실시간 검색어를 불러오고 있습니다.", 0.05)
        self._set_trend_keyword_buttons_state("disabled")
        self.daum_keywords_button.configure(text="불러오는 중...")
        self.find_keywords_button.configure(state="disabled")
        self.daum_worker = DaumRealtimeKeywordWorker(self.result_queue)
        self.daum_worker.start()

    def load_signal_keywords(self) -> None:
        if self.daum_worker and self.daum_worker.is_alive():
            messagebox.showinfo("진행 중", "다음 실시간 검색어를 가져오는 중입니다.")
            return
        if self.signal_worker and self.signal_worker.is_alive():
            messagebox.showinfo("진행 중", "시그널 실시간 검색어를 가져오는 중입니다.")
            return
        if self.newneek_worker and self.newneek_worker.is_alive():
            messagebox.showinfo("진행 중", "뉴닉 키워드를 가져오는 중입니다.")
            return

